window.DESIGNERS = {
  "kawakubo": {
    "en": "Rei Kawakubo",
    "ja": "川久保玲",
    "bio": "1942年、東京生まれ。父は慶應義塾大学の職員で、本人も慶應義塾大学文学部で美学・美術史を学んだ。服飾の専門教育は受けていない。卒業後は旭化成の宣伝部に入り、繊維の広告の仕事でスタイリングを担当するうちに、撮影に使いたい服が見つからないことから自分で服を作るようになった。フリーのスタイリストを経て、1969年に「COMME des GARÇONS（少年のように）」の名で服を作り始め、1973年に株式会社コム デ ギャルソンを設立した。\n1975年に東京で最初のコレクションを発表し、1978年にメンズのHOMMEを開始。1981年、山本耀司とともにパリ・コレクションに参加した。黒を基調に、穴をあけ、裾を切りっぱなしにし、身体の線を隠すゆったりした服は、欧米のプレスから「ボロルック」「ヒロシマ・シック」と酷評と称賛の両方を受け、「黒の衝撃」と呼ばれた。これは装飾と身体の美しさを当然とする西洋のモードへの根本的な問いかけであり、ここから日本のデザイナーが世界のファッションを動かす時代が始まった。\n川久保の作風は毎シーズン大きく変わるが、一貫しているのは「新しいもの」を作ること、そして「美しい」「女らしい」「服とはこういうもの」という前提を疑うことだ。1997年春夏の「Body Meets Dress, Dress Meets Body」（通称こぶドレス）では、詰め物で身体の形そのものを変え、2012年春夏には平面（2D）の服、2014年春夏以降は着ることを前提にしない彫刻のようなオブジェを発表した。ショーのあとに言葉で説明することはほとんどなく、タイトルも短い。\nデザイナーとしてだけでなく経営者としても特異な存在で、ひとつの会社の中にHOMME、HOMME PLUS、tricot、SHIRT、PLAY、BLACK、Homme Deuxなど多数のラインを持ち、渡辺淳弥（JUNYA WATANABE）、栗原たお（tao）、二宮啓（noir kei ninomiya）ら社内のデザイナーに自分の名前のブランドを持たせて育てた。阿部千登勢（sacai）や阿部潤一（kolor）も同社の出身。2004年にはロンドンに、複数のブランドを一つの建物に集めた「Dover Street Market」を開き、銀座、ニューヨーク、北京などにも広げて小売の形を変えた。1990年代からは店舗、広告、雑誌『Six』などのグラフィックまで自らの思想を貫いた。\n2017年にはメトロポリタン美術館のコスチューム・インスティテュートで、存命のデザイナーとしてはイヴ・サンローラン以来2人目となる大規模な個展「Rei Kawakubo/Comme des Garçons: Art of the In-Between」が開かれた。夫はDover Street Marketの経営にも関わるエイドリアン・ジョフィ。\n古着でCOMME des GARÇONSを見るときは、タグのAD表記（例：AD1999は1999年製）が年代の目安になる。1980年代前半の黒くほつれた服、1990年代のHOMME PLUSの縮絨やポリエステルのテーラリング、1997年春夏のこぶドレス関連、2000年代前半のプリントなどは特に人気が高い。"
  },
  "watanabe": {
    "en": "Junya Watanabe",
    "ja": "渡辺淳弥",
    "bio": "1961年、福島県生まれ。文化服装学院を1984年に卒業し、同年COMME des GARÇONSにパタンナーとして入社した。川久保玲のもとで複雑な立体裁断と素材の扱いを身につけ、1987年からニットのライン「tricot COMME des GARÇONS」のデザインを任された。\n1992年、COMME des GARÇONSの中のブランドとして自身の名を冠した「JUNYA WATANABE COMME des GARÇONS」を東京で発表し、翌1993年からパリ・コレクションに参加した。ウィメンズでは、ハニカム状に折りたたんで広げる生地、透けるオーガンジーを何層にも重ねた造形、防水素材やナイロンを使ったテクニカルな服、パッチワークなど、パターンと素材の実験で高い評価を得た。2001年にはメンズの「JUNYA WATANABE COMME des GARÇONS MAN」を開始。ここで渡辺は、Levi's、Carhartt、The North Face、New Balance、Brooks Brothers、Barbour、Karrimor、Moncler、Converseなど、アメリカやイギリスの定番ブランドと組み、パッチワークや切り替え、素材の置き換えで再構築する手法を確立した。ワークウェアやアウトドア、ミリタリーという「実用の服」を素材にしながら、どこにもない一着にする。この「コラボレーションの名手」というあり方は、のちのストリートとラグジュアリーの協業ブームを先取りしていた。\n2003年からはCOMME des GARÇONS HOMMEのデザインも担当し（全面的な担当を2012年頃からとする資料もある）、2005年には自身のブランドのeYeライン（eYe JUNYA WATANABE MAN）も始めた。インタビューにはほとんど応じず、川久保と同じく言葉ではなく服で語るデザイナーとして知られる。\n古着では、メンズのパッチワークのデニムやワークジャケット、Levi'sとのリメイク、The North Faceとのアウター、ウィメンズの2000年前後の実験的なシーズンが人気。COMME des GARÇONS社のブランドなので、タグのAD表記で年代がわかる。",
    "mentors": [
      "kawakubo"
    ]
  },
  "yamamoto": {
    "en": "Yohji Yamamoto",
    "ja": "山本耀司",
    "bio": "1943年、東京生まれ。父は第二次世界大戦で戦死し、母が新宿・歌舞伎町で営む洋装店で育った。慶應義塾大学法学部を卒業後、一度は就職を考えたが、母の仕事を手伝うために文化服装学院に入学し、1969年に装苑賞と遠藤賞を受賞。その賞でパリへ渡ったが、当時のパリでは仕事が見つからず帰国した。\n1972年に株式会社ワイズを設立し、ウィメンズの「Y's」を始めた。1977年に東京でコレクションを発表し、1981年に川久保玲とともにパリ・コレクションに参加。黒を中心に、非対称で、身体と服の間にゆとりを残すカッティング、裾が垂れ下がるような服は、ヨーロッパのモードの「女性の身体を美しく見せる」前提を覆し、「黒の衝撃」と呼ばれた。山本自身は「黒は控えめでありながら傲慢な色」と語っている。\n山本の服の大きな特徴は、男女の境界を曖昧にすることにある。男性用のコートやジャケットを女性に着せるような仕立て、ギャバジンやウールのゆったりしたスーツは、性別の役割を服から外す試みだった。1984年に始めたメンズの「Yohji Yamamoto POUR HOMME」は、テーラリングのコート、セットアップ、レーヨンのシャツなどで今も絶大な人気がある。写真家アウグスト・ザンダーの20世紀初頭の肖像写真や、職人の作業着も重要な着想源だった。\n1989年にはヴィム・ヴェンダースが山本を撮ったドキュメンタリー『都市とモードのビデオノート』が公開された。2003年にはadidasとの「Y-3」を始め、スポーツウェアとハイファッションを融合した先駆けとなった。舞台衣装（北野武の映画『Dolls』など）や、空手の黒帯としても知られる。\n2009年、急な事業拡大がたたって民事再生法の適用を申請したが、投資ファンドの支援を受けて再建した。現在もパリで毎シーズン発表を続け、Ground Y、S'YTE、B Yohji Yamamoto、LIMI feu（娘の山本里美のブランド）など多くのラインがある。\n古着では、1980〜90年代のPOUR HOMMEのコートやジャケット、セットアップ、ウールギャバジンのパンツ、レーヨンのシャツが定番。2000年前後のメッセージや刺繍のあるシーズン、Y'sのウィメンズも人気。"
  },
  "miyake": {
    "en": "Issey Miyake",
    "ja": "三宅一生",
    "bio": "1938年、広島市生まれ。7歳のときに原子爆弾で被爆し、母はその数年後に亡くなった。本人はこの体験を長く語らず、「破壊ではなく創造するもの、美しく喜びを与えるものを考えたい」という思いを持ち続けた。多摩美術大学でグラフィックデザインを学び、在学中から服のデザインを始めた。\n1965年に渡仏し、パリのクチュール組合の学校で学んだのち、ギ・ラロッシュ、ユベール・ド・ジバンシィのアシスタントを務めた。1968年の五月革命で、少数の顧客のためのオートクチュールではなく、多くの人のための服を作りたいと考えるようになり、ニューヨークのジェフリー・ビーンのもとを経て1970年に帰国し、三宅デザイン事務所を設立。1973年にパリ・コレクションに参加した。\n三宅の服の根本にある考えは「一枚の布」。西洋の立体裁断とも日本の着物の平面とも違い、布と身体の間に生まれる空間を大事にする。1976年に「三宅一生と一枚の布」展を開き、1980年代には籐や紙、プラスチックで作ったボディ（ボディワークス）、山口小夜子らを起用した東西を超えるショーを発表した。\n素材と技術の研究開発を服づくりの中心に置いたことも特徴で、縫製したあとにプリーツをかける製品プリーツを開発し、1993年に「PLEATS PLEASE ISSEY MIYAKE」を発表。軽く、しわにならず、洗えて、どんな体型にも合う服は世界中で愛用された。アップル創業者スティーブ・ジョブズの黒いタートルネックを作ったことでも知られる。1998〜1999年には藤原大とともに、一本の糸から布と服を同時に作る「A-POC」を開発。2010年には折り紙の数学から生まれた「132 5. ISSEY MIYAKE」を発表した。\n1999年にメインラインのデザインを滝沢直己に託してからも、研究開発チーム「Reality Lab.」を率いた。2007年には安藤忠雄の設計で東京・六本木に「21_21 DESIGN SIGHT」を開設。2010年には文化勲章を受章した。2022年8月5日、肝細胞がんのため84歳で死去した。\n古着では1980年代のメインライン、1990年代のPLEATS PLEASEの柄物、A-POCのピース、ISSEY MIYAKE MENのジャケットなどが人気。ラインが多いので、タグのライン名で見分ける。"
  },
  "takizawa": {
    "en": "Naoki Takizawa",
    "ja": "滝沢直己",
    "bio": "1960年、東京生まれ。桑沢デザイン研究所でデザインを学び、1982年に三宅デザイン事務所に入社した。三宅一生のもとで素材と技術を軸にした服づくりを学び、メンズラインのISSEY MIYAKE MENのデザイナーを1993年頃から務めた。\n1999年、三宅一生からISSEY MIYAKEのメインラインのデザインを引き継いだ。創業者の思想を受け継ぎながら、より日常に寄り添う服、新しい素材や技術を取り入れた服を発表し、2006年まで担当した。三宅が研究開発に専念する体制への移行期を支えた存在といえる。\n2006年に独立して自身の会社「NAOKI TAKIZAWA DESIGN」を設立し、自身のブランドを発表したほか、2011〜2013年頃にはユニクロのデザインディレクターとして、ヒートテックなどの機能素材を使った商品のデザインにも関わった。日本のファッション教育や企業のデザインのアドバイザーとしても活動している。\n古着では、滝沢がデザインした1999〜2006年頃のISSEY MIYAKEのメインラインや、ISSEY MIYAKE MENのジャケットに注目が集まる。",
    "mentors": [
      "miyake"
    ]
  },
  "fujiwara": {
    "en": "Dai Fujiwara",
    "ja": "藤原大",
    "bio": "1967年、東京生まれ。北京の中央美術学院で水墨画を学んだのち、多摩美術大学でテキスタイルデザインを学んだ。1994年に三宅デザイン事務所に入社し、三宅一生のもとで素材とテキスタイルの開発に関わった。\n1998〜1999年、三宅とともに「A-POC（A Piece of Cloth）」を開発した。コンピューターで制御した編み機や織機で、一本の糸から筒状の布を作り、その布に服の形があらかじめ編み込まれていて、点線に沿ってはさみで切り抜くだけで服になる。どこで切るかで袖の長さや形を変えられ、無駄な布も縫製もほとんど出ない画期的な仕組みで、1999年春夏のショーでは赤い一続きの布に包まれたモデルたちが次々と現れる演出で話題になった。\n2006年からISSEY MIYAKEのクリエイティブディレクターを務め、日本各地や世界の色を集める「カラーハンティング」などのテーマでコレクションを発表した。2011年に退任し、その後はDAI FUJIWARA名義で、テキスタイルやプロダクト、企業との共同研究、教育などのプロジェクトを手がけている。\nA-POCは、のちに宮前義之らが率いる「A-POC ABLE ISSEY MIYAKE」として現在も研究が続いている。古着ではA-POCの初期のピースや、藤原期のメインラインが注目される。",
    "mentors": [
      "miyake"
    ]
  },
  "miyamae": {
    "en": "Yoshiyuki Miyamae",
    "ja": "宮前義之",
    "bio": "1976年生まれ。文化服装学院を卒業後、2001年に三宅デザイン事務所に入社した。入社後すぐに藤原大のチームに加わり、一本の糸から服を作る「A-POC」の研究開発を担当した。\n2011年、藤原大の後任としてISSEY MIYAKEのデザイナーに就任した。宮前の時代のISSEY MIYAKEは、A-POCで培った技術を発展させた素材開発が特徴で、熱で縮む糸を使って布に立体的な模様を浮かび上がらせる「Steam Stretch」、ドット状の樹脂で伸縮を固定する「Baked Stretch」など、新しい加工技術をコレクションに取り入れた。色彩豊かでありながら、技術そのものが服の美しさになる作風で、2019年まで担当した。\n2019年からは近藤悟史にメインラインを託し、2021年に始まった「A-POC ABLE ISSEY MIYAKE」を率いている。エンジニアリングチームとともに、A-POCの考え方を現代の技術で発展させ、デザイナーやアーティスト、企業との協業も積極的に行っている。\n古着では、宮前期（2011〜2019）のメインラインの加工素材の服や、A-POC ABLEのアイテムが注目される。",
    "mentors": [
      "fujiwara"
    ]
  },
  "kondo": {
    "en": "Satoshi Kondo",
    "ja": "近藤悟史",
    "bio": "1984年、京都府生まれ。大阪の専門学校でファッションを学び、2007年に三宅デザイン事務所に入社した。入社後はプリーツの専門ラインPLEATS PLEASE ISSEY MIYAKEのチームに所属し、のちにメインラインのチームで宮前義之のもとで経験を積んだ。\n2019年、ISSEY MIYAKEのデザイナーに就任した。2020年春夏のデビュー・コレクション「A Sense of Joy」では、ダンサーが跳ね回るような演出で、服を着て動くことの喜びをテーマにした。以後も、紙のような素材、折りたたむとコンパクトになる服（2021年春夏「UNPACK THE COMPACT」）、和紙や竹などの日本の素材、アーティストとの協業など、三宅一生の「一枚の布」の思想と、身体や動きの楽しさを結びつけたコレクションを続けている。\n2022年に三宅一生が亡くなってからも、その理念を受け継ぐ中心的なデザイナーとして、パリで毎シーズン発表している。近藤のISSEY MIYAKEは、技術的でありながらユーモアや軽やかさがあると評価されている。",
    "mentors": [
      "miyamae"
    ]
  },
  "takahashi": {
    "en": "Jun Takahashi",
    "ja": "高橋盾",
    "bio": "1969年、群馬県桐生市生まれ。高校時代からパンクロックに夢中になり、セックス・ピストルズやヴィヴィアン・ウエストウッドの服に強い影響を受けた。上京して文化服装学院に入学し、在学中の1990年、友人と「UNDERCOVER」を始めた。同じ頃、NIGOとともに藤原ヒロシの周囲に集まり、バンド「東京セックスピストルズ」ではボーカルを務めた。\n1993年、NIGOと原宿の裏通りに店「NOWHERE」を開いた。半分をUNDERCOVER、半分をA BATHING APEが使ったこの店は、1990年代の「裏原宿」ブームの象徴となる。Tシャツやパーカーのグラフィックから始まったが、高橋は早い段階から服そのものの構造に興味を持ち、1994年に東京でショーを始めた。\nUNDERCOVERの作風は、パンクの破壊と手作業、グラフィックと引用、可愛さと不気味さの共存にある。服を切り裂いて縫い合わせたパッチワーク、手描きや刺繍、熊のぬいぐるみを縫い合わせたライト「GRACE」、目のない顔のモチーフなどがよく知られる。「We make noise not clothes（服ではなくノイズを作る）」を掲げ、毎シーズンにタイトルを付ける。\n2002-03年秋冬「Witch's Cell Division」でパリ・コレクションに参加し、2003年春夏「SCAB」、2003-04年秋冬「Paper Doll」、2004年春夏「Languid」、2004-05年秋冬「but beautiful… part parasitic part stuffed」、2005年春夏「but beautiful II」、2005-06年秋冬「Arts & Crafts」、2006年春夏「T」など、パリ初期のコレクションは今もアーカイブとして非常に人気が高い（シーズン名の詳細はブランドのページ参照）。\nNIKEとのランニングライン「GYAKUSOU」（2010年頃〜）、ユニクロとの「UU」（2010年）、メンズのショーの再開、2018年1月のピッティ・ウオモでのゲストショー、映画『時計じかけのオレンジ』や『シャイニング』を引用したコレクション、Valentinoとの協業（2019年）など、ストリートとモードを自由に行き来している。2015年頃からメンズをパリで発表し、ウィメンズとメンズのショーを分けるようになった。\n古着では、2003〜2006年のパリ初期のシーズン、1990年代の裏原宿期のグラフィックTシャツやパーカー、パッチワークの服が特に高値で取引される。",
    "mentors": [
      "fujiwara_h"
    ]
  },
  "miyashita": {
    "en": "Takahiro Miyashita",
    "ja": "宮下貴裕",
    "bio": "1973年、東京生まれ。高校卒業後、ファッションの学校には通わず、古着店などで働きながら独学で服を学んだ。ロック、特にカート・コバーン、ジョン・レノン、ザ・ストゥージズ、ガンズ・アンド・ローゼズなどの音楽と、それを着ていた人たちの服に深く影響を受けた。\n1996年に「NUMBER (N)INE」を始めた。宮下の服は、古着のような加工を施したデニム、ネルシャツ、ミリタリージャケット、レザー、ニットを、細く鋭いシルエットでまとめ、音楽とともに生きる若者の姿を描いた。ほぼすべてのシーズンにロックの曲名やミュージシャンにちなんだタイトルを付け、ショーの演出や音楽にも強いこだわりを持った。2004年からパリでショーを行い、2003〜2008年頃の作品は「東京メンズの黄金期」を象徴するものとして世界中に熱狂的なファンを持つ。\n2009年、宮下はNUMBER (N)INEを離れた（ブランド名は別会社で継続）。2010年に「TAKAHIROMIYASHITA TheSoloist.」を始め、より個人的で、テーラリングの効いたジャケットやコート、片側だけに付いたディテール、ミリタリーの再構築など、内省的で緻密な作風へと移った。2015年頃からはパリで発表した。\n2025年7月、15周年を節目にTheSoloist.を離れ、同年「NUMBER (N)INE by Takahiro Miyashita」として再始動を発表した。\n古着ではNUMBER (N)INEの2003年「Touch Me I'm Sick」、2004年春夏「Dream Baby Dream」、2005-06年秋冬「The High Streets」、2006-07年秋冬「Noir」、2007-08年秋冬「Love God Murder」などのシーズンがシーズン名で探される。タグの年代や素材表示で見分けるのが基本。"
  },
  "abe_c": {
    "en": "Chitose Abe",
    "ja": "阿部千登勢",
    "bio": "1965年、岐阜県生まれ。名古屋ファッション専門学校を卒業後、ワールドに入社し、その後COMME des GARÇONSに移ってパタンナーとして働いた。渡辺淳弥のJUNYA WATANABE COMME des GARÇONSの立ち上げにも関わったとされる。結婚し、kolorの阿部潤一の妻となった。\n出産を機に退社し、1999年、子育てをしながら自宅で5型のニットから「sacai」を始めた。名前は旧姓の「さかい」から。最初は小さな展示会で、日常に着られるけれど少しだけ特別な服を目指した。\nsacaiの最大の特徴は、異なる服を一着に「ドッキング」するハイブリッドの手法。ニットの身頃にシャツの裾、MA-1のボンバージャケットにプリーツのスカート、トレンチコートとドレス、デニムとレースなど、普段見慣れた服を素材にしながら、見たことのない形を作る。前から見るとニット、後ろから見るとシャツといった服は、パターンの技術と素材の知識があってこそ成り立つ。\n2009年からパリでショーを行い、2011年にメンズを始めた。NIKE（LDWaffle、VaporWaffleなど）、The North Face、Carhartt WIP、Moncler、Dior（2021年）、Jean Paul Gaultierのクチュールのゲスト（2021年）、Apple、Undercoverなどとの協業も多く、2020年代のストリートとラグジュアリーの協業ブームを代表するデザイナーの一人となった。2021年には東京オリンピックに関連したプロジェクトなども手がけた。\n古着では、2010年代のハイブリッドのブルゾンやニット、NIKEとのスニーカーが人気。",
    "mentors": [
      "kawakubo"
    ]
  },
  "abe_j": {
    "en": "Junichi Abe",
    "ja": "阿部潤一",
    "bio": "1965年生まれ。文化服装学院を卒業後、ワールドを経てCOMME des GARÇONSに入社し、ニットやパターンの仕事を経験した。妻はsacaiの阿部千登勢。\n独立後、1994年頃に「Pinceau」を始めたのち、2004年に「kolor」を始めた。「大人のための、少しだけひねりのある服」を目指し、色・素材・パターンを一着の中でずらして切り替える手法を確立した。遠目には普通のジャケットやコートに見えても、近くで見ると袖だけ素材が違う、後ろ身頃だけ色が違うといった複雑な作り。シャツやニットを重ねたように見える服、異素材の切り替えのブルゾンなど、日本の機屋と作る素材にも定評がある。\n2012年からパリでメンズのショーを行い、ウィメンズも展開。adidasとのkolor/BEACON、ゴルフ、アウトドアのラインなども手がけた。2025年1月のパリでのショーを最後にデザイナーを退任し、アドバイザーとなった。後任は堀内太郎。\n古着では、2010年代のパリ期の切り替えのアウターやニットが人気。",
    "mentors": [
      "kawakubo"
    ]
  },
  "horiuchi": {
    "en": "Taro Horiuchi",
    "ja": "堀内太郎",
    "bio": "1982年、東京生まれ。ベルギーのアントワープ王立芸術アカデミーで学んだ。在学中から服づくりとアートの境界に関心を持ち、卒業後の2007年に自身のブランド「TARO HORIUCHI」を始め、東京で発表した。\n2016年には、服を「プロダクト」として捉え、無駄のない形と機能、素材の良さを追求するブランド「th products」を立ち上げた。シーズンを超えて着られる、静かで洗練された服で評価を得た。\n2025年、kolorの創業者・阿部潤一の退任を受けて、kolorのデザイナーに就任した。kolorらしい色と素材の切り替えを、堀内らしい抑制の効いたバランスで受け継ぐことが期待されている。"
  },
  "nakamura": {
    "en": "Hiroki Nakamura",
    "ja": "中村ヒロキ",
    "bio": "1970年、山梨県生まれ。高校時代にアメリカの文化に憧れ、卒業後にアラスカなどで過ごした経験を持つ。スノーボードに打ち込み、帰国後はBURTONの日本法人で働き、スノーボードのブーツやウェアの企画を担当した。\n2000年、靴のブランドとして「visvim」を始めた。名前に意味はなく、響きで選んだという。ネイティブ・アメリカンのモカシンの構造をスニーカーに取り入れた「FBT」、スエードのブーツ、ハイキングシューズなどで注目され、2001年頃から服も展開した。\n中村の服づくりの核は、古いもの、手で作られたものへの深い敬意にある。日本の民藝、アメリカのヴィンテージのワークウェアやミリタリー、ネイティブ・アメリカンやアジア、アフリカの手仕事を世界中で収集・研究し、泥染めや藍染め、柿渋などの天然染め、手織りの布、古い織機、職人の手刺繍などを多用する。時間とともに色が落ち、味が出ることを前提にした服は、価格は高いが「一生もの」として世界中に熱心な愛用者を持つ。\n2010年代には、ジョン・メイヤーやエリック・クラプトンらミュージシャンの愛用で海外の人気が高まり、パリでも展示会を開くようになった。ウィメンズの「WMV」、京都の店など、場所づくりにもこだわる。\n古着では、初期のFBT、ブーツ、天然染めの服、限定の「ICT」ラインなどが人気。"
  },
  "nishiyama": {
    "en": "Tetsu Nishiyama",
    "ja": "西山徹",
    "bio": "1974年、東京生まれ。10代の頃からスケートボードやパンク、ハードコアのシーンに親しみ、1990年代初めに裏原宿で「FORTY PERCENTS AGAINST RIGHTS（FPAR）」を始めた。政治的な言葉やグラフィックをTシャツに載せたこのブランドは、のちのWTAPSの前身とされる。\n1996年に「WTAPS（ダブルタップス）」を立ち上げた。名前は、銃を2発続けて撃つ射撃の技術「ダブルタップ」から。ミリタリーウェアとワークウェアを下敷きに、日常で着る「制服」としての服を作るという考え方が一貫している。M-65やジャングルファティーグ、BDUなどの軍服の型を正確に研究しつつ、素材やシルエット、ロゴの入れ方で現代の街の服にする。\n裏原宿世代の代表格の一人として、NEIGHBORHOOD、Supreme、NIKE、Vans、Champion、New Eraなどとの協業も多い。2020年代も国内外で高い人気を保っている。\n古着では、2000年代のミリタリーのジャケットやパンツ、FPARのTシャツ、協業アイテムが人気。"
  },
  "takizawa_s": {
    "en": "Shinsuke Takizawa",
    "ja": "滝沢伸介",
    "bio": "1967年生まれ。若い頃からモーターサイクル、サーフィン、ミリタリーのカルチャーに親しみ、DJやスタイリストとしても活動した。1994年、原宿で「NEIGHBORHOOD」を始めた。\nNEIGHBORHOODの世界観は、アメリカのバイカーやチョッパーのカルチャー、ミリタリー、サーフ、ロックンロールを東京的に再解釈したもの。レザーのライダースジャケット、デニム、ワークシャツ、スカルや髑髏、十字架のグラフィックなど、硬派で男くさいスタイルを貫いている。\n裏原宿ブームの中心ブランドの一つとして人気を集め、今も長く続いている。ハーレーダビッドソン、adidas、Vans、Supreme、WTAPS、Porterなどとの協業も多い。インテリアや植物（鉢）のラインなども展開し、ライフスタイル全体を提案している。\n古着では、1990年代〜2000年代前半のレザーやデニム、初期のグラフィックTシャツが人気。"
  },
  "nigo": {
    "en": "NIGO",
    "ja": "NIGO",
    "bio": "1970年、群馬県前橋市生まれ。文化服装学院で学んだのち、雑誌『Popeye』でスタイリストとして働き、藤原ヒロシの身の回りの世話をしていたことから「藤原ヒロシ二号」で「NIGO」と呼ばれるようになった。DJとしても活動した。\n1993年、高橋盾とともに原宿の裏通りに店「NOWHERE」を開き、「A BATHING APE」を始めた。名前は映画『猿の惑星』と、「ぬるま湯につかった猿（A Bathing Ape in Lukewarm Water）」という言葉から。猿の顔のロゴ、独自の迷彩柄（BAPE CAMO）、全面ジッパーのシャークパーカー、NIKEのエアフォース1を思わせるBAPE STAなどで、1990年代後半〜2000年代に世界的な人気を得た。少量生産と行列のできる販売方法は、のちのストリートブランドの手本になった。\nファレル・ウィリアムス、カニエ・ウェスト、ノトーリアス・B.I.G.らヒップホップのアーティストに愛用され、2003年にはファレルとBillionaire Boys ClubとICECREAMを始めた。2011年に経営難からBAPEを香港のI.T社に売却し、2013年に離れた。\nその後はHUMAN MADE（2010年〜）を主宰し、ヴィンテージのアメリカの服を下敷きにした服で再び人気を得た。ユニクロのUTのクリエイティブディレクター、音楽プロデューサーとしても活動。2021年9月にKENZOのアーティスティックディレクターに就任し、創業者・高田賢三が築いたブランドを日本人として率いている。\n古着では、1990年代後半〜2000年代前半のNIGO期のBAPEのアイテム、HUMAN MADEのヴィンテージ風の服が人気。",
    "mentors": [
      "fujiwara_h"
    ]
  },
  "kitamura": {
    "en": "Nobuhiko Kitamura",
    "ja": "北村信彦",
    "bio": "1962年、東京生まれ。文化服装学院在学中から服づくりを始め、1984年、21歳で入社したオゾンコミュニティで「HYSTERIC GLAMOUR」を立ち上げた。\nHYSTERIC GLAMOURは、1960〜70年代のロック、ポップアート、アメリカのB級映画やコミック、ピンナップ、ポルノ雑誌的なグラフィックを、東京のロックな女の子のための服として再解釈した。目の大きな女の子「ヒスガール」のグラフィック、ブランケット柄のアイテム、加工したデニム、レオパードやハートの柄などが代表的。\n写真や音楽との関わりも深く、荒木経惟、森山大道、テリー・リチャードソン、アンディ・ウォーホル財団などとのコラボや写真集を数多く手がけた。ソニック・ユースのキム・ゴードンなど海外のミュージシャンにも愛用され、1990年代の東京のストリートを代表するブランドとなった。\n古着では、1990年代のガールのグラフィックTシャツ、デニム、レザー、ブランケット柄のアイテムが人気で、海外のヴィンテージ市場でも評価が高い。"
  },
  "hirata_t": {
    "en": "Toshikiyo Hirata",
    "ja": "平田俊清",
    "bio": "1949年、岡山県生まれ。日本のジーンズの発祥地とされる倉敷市児島で、デニムの縫製と加工の仕事に携わった。児島は学生服や作業服の縫製で栄えた町で、1960年代から国産ジーンズの生産地となった。\n1985年、平田はジーンズの縫製・加工の会社「キャピタル」を設立した。大手ブランドの生産を請け負いながら、洗いや色落ち、ダメージなどの加工技術を磨き、日本のデニムの品質を支える職人の一人となった。のちに息子の平田和宏が加わり、自社ブランドとしてのKAPITALが世界的に知られるようになった。"
  },
  "hirata_k": {
    "en": "Kazuhiro Hirata",
    "ja": "平田和宏",
    "bio": "平田俊清の息子。若い頃にアメリカで暮らし、アメリカの古着、ヒッピーやネイティブ・アメリカンの文化、手仕事に強い影響を受けた。帰国後、2000年前後から父の会社キャピタルのデザインを担当するようになった。\n和宏のKAPITALは、日本の藍染め、刺し子、ボロ（継ぎはぎの古布）、パッチワーク、手作業の加工と、アメリカのジーンズ、ワークウェア、ミリタリー、ヒッピー、ネイティブ・アメリカンの意匠、さらにはアジアやアフリカの民族衣装を混ぜ合わせた、独特の世界観で知られる。センチュリーデニム、骨（ボーン）柄、スマイルマーク、ボロのジャケット、リングコートなど、遊び心のあるアイテムが多い。\n毎シーズンのルックブックの撮影も独創的で、海外の古着好きやファッション関係者からの評価が非常に高い。国内外に直営店を持ち、児島を世界に知らしめたブランドの一つになった。"
  },
  "honma": {
    "en": "Masaaki Homma",
    "ja": "本間正章",
    "bio": "1965年生まれ。若い頃からアメリカのストリートカルチャーや音楽に親しみ、1997年に藤田昌洋とともに「mastermind JAPAN」を設立した。\nmastermind JAPANの象徴は、スカル&クロスボーン（髑髏と交差した骨）のモチーフ。これを、カシミア、上質な革、スワロフスキーのクリスタル、繊細な刺繍などラグジュアリーな素材と組み合わせ、ストリートでありながら高級な「ラグジュアリー・ストリート」というジャンルを2000年代に確立した。黒を中心とした色使いと、細身のシルエットも特徴。\n2013年にいったんコレクションを休止したが、2017年に海外向けのmastermind WORLDなどで再開した。Louis Vuitton、Converse、Undercover、NEW ERAなどとの協業も多い。\n古着では、2000年代のスカル柄のニット、デニム、レザー、協業アイテムが人気。"
  },
  "mihara": {
    "en": "Mihara Yasuhiro",
    "ja": "三原康裕",
    "bio": "1972年、長崎県生まれ。多摩美術大学のテキスタイルデザイン科に入学したが、在学中に独学で靴づくりを始め、職人の工房に通って技術を学んだ。1997年に靴のブランド「archi doom」をスタートさせた。\n三原の靴は、粘土から型を起こしたオリジナルのソール、溶けたようなソール、古いスニーカーをそっくりコピーしたようなアイロニカルなデザインで知られる。大量生産のスニーカーに対する批評的なまなざしと、職人の手仕事が同居している。1999年頃から服も手がけ、「MIHARAYASUHIRO」として展開した。\n2000年にPUMAとの協業を始め（本格的には2004年頃から）、世界的に知られるようになった。2007年からミラノ、のちパリでメンズのショーを行い、服でもクラシックな服をわざと崩したり、パーツをずらしたりする解体的なデザインを発表した。2016年に「Maison MIHARA YASUHIRO」に改称。\n古着では、オリジナルソールのスニーカー、PUMAとの協業モデル、2000年代の服が人気。"
  },
  "margiela": {
    "en": "Martin Margiela",
    "ja": "マルタン・マルジェラ",
    "bio": "1957年、ベルギーのヘンク生まれ。祖母がお針子で、子どもの頃から人形の服を作っていたという。ハッセルトの学校でファッションの基礎を学んだのち、アントワープ王立芸術アカデミーのファッション科に進み、1980年に卒業した。アン・ドゥムルメステール、ドリス・ヴァン・ノッテンら「アントワープ・シックス」と同じ時期に学んだため、彼らと合わせて「6+1」と呼ばれることもある。\n卒業後はイタリアでフリーランスのデザイナーとして働き、1984年から1987年までパリでジャン＝ポール・ゴルチエのアシスタントを務めた。1988年、ブリュッセルのブティック経営者ジェニー・メイレンスとともに「Maison Martin Margiela」を設立し、1989年春夏にパリでデビューした。最初のショーは、パリの郊外の劇場で、モデルが赤く塗った靴底で白い布の上に足跡を残すという演出だった。\nマルジェラの作風は、1990年代の「脱構築（デコンストラクション）」の代表とされる。縫い代やダーツ、裏地、肩パッドなど本来隠れる部分を表に出し、古着、軍物の靴下、手袋、皿、トランプなどの既製品を作り変えて服にする「アーティザナル」（のちのライン0）、仕立て用の人台（スタンド）をそのままジャケットにした服、極端に大きくしたオーバーサイズの服、ドイツ軍のトレーナーをもとにしたスニーカー、日本の足袋から生まれた先の割れた「Tabi」ブーツなどを生んだ。\nもうひとつの大きな特徴は「匿名性」。マルジェラ本人は写真に写らず、インタビューもファックスで答え、名前の代わりに「私たち」という主語を使った。ブランドのラベルは白い無地の布を四隅の白い糸で留めただけで、0〜23の数字のうち丸のついた番号でラインを示した（0=アーティザナル、1=ウィメンズ、10=メンズ、14=ワードローブ、22=靴など）。スタッフは白衣を着て、店も家具も白く塗られた。\n1997年から2003年まではHermèsのウィメンズのデザイナーも兼任し、カシミアのダブルフェイスのコートやロザンジュ（ひし形）のスカーフなど、ブランドとは対照的な静かな服を作った。2002年、Dieselのレンツォ・ロッソが率いるOTBがブランドを買収し、2009年にマルジェラはファッション界を去った。\nその後は美術家として活動し、2021年にパリのラファイエット・アンティシパシオンで個展を開いた。2019年にはライナー・ホルツェマー監督のドキュメンタリー『Martin Margiela: In His Own Words』（声と手だけで本人が登場）が公開された。古着では1990年代の白タグ期、アーティザナル、Hermès期のウィメンズが非常に高く評価されている。",
    "mentors": [
      "gaultier"
    ]
  },
  "demeulemeester": {
    "en": "Ann Demeulemeester",
    "ja": "アン・ドゥムルメステール",
    "bio": "1959年、ベルギーのヴァースメール生まれ。10代の頃は肖像画家を目指していたが、服に関心を移し、アントワープ王立芸術アカデミーのファッション科に進んで1981年に卒業した。在学中に、のちに夫となる写真家のパトリック・ロビンと出会った。\n1985年にロビンとともに自身のブランドを始め、1986年にロンドンのブリティッシュ・デザイナー・ショーで、ドリス・ヴァン・ノッテン、ダーク・ビッケンバーグ、ウォルター・ヴァン・ベイレンドンク、ダーク・ヴァン・セーヌ、マリナ・イーとともに「アントワープ・シックス」として注目された。1992年にパリでデビューし、1996年にメンズを始めた。\nドゥムルメステールの服は、黒と白を基調に、長く細いシルエット、非対称の裾、羽根やリボン、レザーのレースアップ、ベストやロングブーツなど、詩的でロック的なロマンティシズムを持つ。パンクの詩人パティ・スミスを敬愛し、彼女の写真や詩をコレクションに取り入れたことでも知られる。性別に縛られない服で、メンズもウィメンズも同じ空気を持つ。\n2013年11月、手紙を公開してブランドを離れることを発表した。その後は陶器の食器、家具、照明のデザインに取り組み、2020年にはアントワープの起業家クラウディオ・アントニオリがブランドを買収した。\n古着では、1990年代〜2000年代前半のレザーのジャケット、ロングブーツ、細身のパンツ、ベストなどが人気で、アルチザン系やゴシックな装いの好きな人に根強い支持がある。"
  },
  "vannoten": {
    "en": "Dries Van Noten",
    "ja": "ドリス・ヴァン・ノッテン",
    "bio": "1958年、ベルギーのアントワープ生まれ。祖父は古着の仕立て直しから紳士服の店を始め、父も高級紳士服店を営む家に育った。父の買い付けにミラノやパリへ同行し、子どもの頃から服の商売を見てきた。アントワープ王立芸術アカデミーのファッション科で学び、1980年に卒業した。\n卒業後はフリーランスとしてイタリアなどのブランドのデザインを手がけ、1986年に自身のメンズのコレクションを発表した。同年ロンドンのブリティッシュ・デザイナー・ショーで「アントワープ・シックス」の一人として注目され、アントワープに店を開いた。1991年にメンズ、1993年にウィメンズでパリへ進出した。\nヴァン・ノッテンは「プリントと色彩の名手」と呼ばれる。インドや中央アジア、アフリカの民族衣装、美術館の絵画、日本の着物、花の写真などから着想した柄を、異なる素材や色と大胆に重ね、それでいて品のある服にする。メンズとウィメンズの境界を行き来するテーラリングも高く評価された。\n経営者としても独特で、長年広告をほとんど出さず、ショーと店を中心に、ファッションウィークのたびに「年に4つの小さなコレクション」を地道に積み上げた。2014年にはパリの装飾芸術美術館で回顧展「Dries Van Noten: Inspirations」が開かれ、2017年にはドキュメンタリー『ドリス・ヴァン・ノッテン ファブリックと花を愛する男』が公開された。\n2018年にスペインのPuigが過半数の株式を取得し、2024年6月のメンズのショーを最後に引退した。引退後は、アントワープの若いクリエイターを支援する財団や、美容・香水の仕事に関わっている。後任はジュリアン・クラウスナー。古着では1990年代〜2010年代のプリントのシャツやジャケットが人気。"
  },
  "raf": {
    "en": "Raf Simons",
    "ja": "ラフ・シモンズ",
    "bio": "1968年、ベルギー北部のネールペルト生まれ。父は軍人、母は清掃員の家庭に育ち、田舎の町でニューウェーブやパンクのレコードに夢中になった。ヘンクの学校で工業デザインと家具デザインを学び、家具デザイナーとして働いた。在学中にインターンとしてウォルター・ヴァン・ベイレンドンクのもとで働き、彼に連れられてマルタン・マルジェラのショーを見たことが、服の道へ進むきっかけになった。\nファッションの正式な教育を受けないまま、1995年に自身のメンズのブランド「Raf Simons」を始めた。最初は細身のテーラリングのスーツと学生服のような服で、ショーではなくビデオで発表した。1997年からパリで発表し、ニューウェーブ、パンク、テクノ、ゴシック、映画（『時計じかけのオレンジ』など）、若者の反抗や孤独をテーマにしたコレクションで熱狂的な支持を得た。\n2001-02年秋冬「Riot! Riot! Riot!」、2002-03年秋冬「Virginia Creeper」（ジョイ・ディヴィジョンやニュー・オーダーのジャケットを手がけたピーター・サヴィルのグラフィックを使ったコート）、2003-04年秋冬「Closer」などは伝説的なシーズンとして、古着市場で非常に高値で取引される。細身のシルエットはエディ・スリマンとともに2000年代のメンズを変えた。\n2000年代初めに一時ブランドを休止し、ウィーン応用美術大学のファッション科の教授も務めた。2005年からJil Sanderのクリエイティブディレクターとして、ミニマリズムに鮮やかな色とクチュールの技術を持ち込み、2012年からDiorで初のクチュールを含むウィメンズ（映画『ディオールと私』）、2016年からCalvin Kleinのチーフ・クリエイティブ・オフィサー、2020年からはPradaでミウッチャ・プラダと共同クリエイティブディレクターを務める。\nadidas、Fred Perry、Eastpak、Sterling Ruby（アーティスト）などとの協業も多い。2022年11月、27年続いた自身のブランドを終了した。現代美術の熱心なコレクターでもある。"
  },
  "kva": {
    "en": "Kris Van Assche",
    "ja": "クリス・ヴァン・アッシュ",
    "bio": "1976年、ベルギーのロンデルゼール生まれ。アントワープ王立芸術アカデミーのファッション科を1998年に卒業した。卒業後すぐにエディ・スリマンのアシスタントとなり、Yves Saint Laurent Rive Gauche Homme、続いて2000年からDior Hommeのデザインチームで細身のシルエットの時代を支えた。\n2004年にパリで自身のブランド「KRISVANASSCHE」を始め、ミニマルでグラフィックなメンズを発表した。2007年、エディ・スリマンの後任としてDior Hommeのアーティスティックディレクターに就任し、2018年まで約11年率いた。ヴァン・アッシュはエディの極細のシルエットを、より余裕のあるテーラリング、ストリートやスケート、ユースカルチャーの要素へと広げ、アーティストのM/M（Paris）などとの協業も行った。この時期のDior Hommeはエディ期とはサイズ感もムードも大きく違う。\n2018年からBerlutiのアーティスティックディレクターを務め、2021年に退任した。2023年には自身のキャリアをまとめた本『55 Collections』を出版した。",
    "mentors": [
      "hedi"
    ]
  },
  "martens": {
    "en": "Glenn Martens",
    "ja": "グレン・マーティンス",
    "bio": "1983年、ベルギーのブルージュ生まれ。最初はインテリア建築を学んだが、ファッションに転じ、アントワープ王立芸術アカデミーのファッション科を2008年に首席で卒業した。\n卒業後はJean Paul Gaultierのジュニアデザイナーとして働き、2012年頃に自身のブランドを発表した。2013年、Y/Projectの共同創業者ヨハン・セルファティが亡くなったことを受けて、同ブランドのクリエイティブディレクターに就任した。マーティンスのY/Projectは、二重の襟、ねじれたデニム、着方を変えられる服、身体の上でずれる構造など、服の常識をユーモアとともに崩す作風で人気を集め、2017年にANDAM賞を受賞した。UGGとのブーツの協業なども話題になった。\n2020年にはDieselのクリエイティブディレクターに就任し、ダメージ加工のデニム、Dロゴ、Y2K的なセクシーな服でブランドを再び若い世代の人気ブランドにした。2022年にはJean Paul Gaultierのクチュールのゲストデザイナーも務めた。\n2024年にY/Projectを離れ、2025年1月にMaison Margielaのクリエイティブディレクターに就任した（ジョン・ガリアーノの後任）。2025年7月に初のアーティザナル・コレクションを発表。2026年9月、Margielaに専念するためDieselを離れると発表した。",
    "mentors": [
      "gaultier",
      "serfaty"
    ]
  },
  "meunier": {
    "en": "Sébastien Meunier",
    "ja": "セバスチャン・ムニエ",
    "bio": "フランス出身。マルタン・マルジェラのもとで長く働き、Maison Martin Margielaのメンズのデザインを担当した。マルジェラの匿名的で知的な服づくりを内側から経験したデザイナーの一人。\n2010年からAnn Demeulemeesterのメンズに参加し、2013年に創業者アン・ドゥムルメステールが去ったあと、同ブランドのクリエイティブディレクターに就任した。ムニエは、黒と白、長いシルエット、羽根やリボンといったブランドの詩的でダークな世界観を大切にしながら、より現代的な着やすさを加えて2020年まで率いた。2020年、ブランドがクラウディオ・アントニオリに売却されたのを機に退任した。",
    "mentors": [
      "margiela"
    ]
  },
  "ldss": {
    "en": "Ludovic de Saint Sernin",
    "ja": "ルドヴィック・ドゥ・サン・セルナン",
    "bio": "1991年、フランス・パリ生まれ。パリのエコール・デュペレで学び、Balmainなどで経験を積んだのち、2017年に自身のブランド「Ludovic de Saint Sernin」を始めた。\nサン・セルナンの服は、性別の境界を越えたセンシュアルなメンズで知られる。両サイドを紐で結ぶ極小のブリーフ、スワロフスキーのクリスタルをちりばめた服、透けるメッシュなど、身体と欲望をテーマにした作風で、若い世代を中心に注目を集めた。\n2022年10月にAnn Demeulemeesterのクリエイティブディレクターに就任し、2023年春夏のコレクションを発表したが、1シーズンで退任した。その後は自身のブランドに専念している。"
  },
  "gallici": {
    "en": "Stefano Gallici",
    "ja": "ステファノ・ガリーチ",
    "bio": "イタリア出身。Ann Demeulemeesterのデザインチームの一員として働き、創業者の詩的でダークな世界観、黒と白の色使い、長いシルエットを内側から学んだ。\n2023年、ルドヴィック・ドゥ・サン・セルナンの退任を受けて、Ann Demeulemeesterのクリエイティブディレクターに抜擢された。ガリーチのAnn Demeulemeesterは、創業者の時代のロマンティシズムとロックな感覚を尊重しながら、若い世代の感覚でレイヤードやレザーを再解釈している。デビュー以来、ブランドの本来の姿を取り戻したと評価する声が多い。"
  },
  "klausner": {
    "en": "Julian Klausner",
    "ja": "ジュリアン・クラウスナー",
    "bio": "カナダ・モントリオール出身。ベルギーで服づくりを学び、2018年頃からDries Van Notenのデザインチームに加わって、ウィメンズのデザインを担当した。ドリス・ヴァン・ノッテンのもとで、プリントと色彩、素材の組み合わせ方を学んだ。\n2024年、創業者ドリス・ヴァン・ノッテンの引退を受けて、Dries Van Notenのクリエイティブディレクターに就任した。創業者の色とプリントの感覚を受け継ぎながら、新しい世代のブランドをどう作るかが注目されている。",
    "mentors": [
      "vannoten"
    ]
  },
  "demna": {
    "en": "Demna",
    "ja": "デムナ",
    "bio": "1981年、ジョージア（当時はソビエト連邦）のスフミ生まれ。1993年、アブハジア紛争で家族とともに難民となり、トビリシに逃れた。この体験は、のちのコレクションにも繰り返し現れる。トビリシ国立大学で国際経済学を学んだのち、家族とともにドイツへ移り、アントワープ王立芸術アカデミーのファッション科を2006年に卒業した。\n卒業後はWalter Van Beirendonckのもとで働き、2009年から2013年頃までMaison Martin Margielaでウィメンズのデザインチームを率いた。2013年にはLouis Vuittonでニコラ・ジェスキエールのもと、ウィメンズのシニアデザイナーを務めた。\n2014年、弟のグラム・ヴァザリアや友人たちとパリで「Vetements」を立ち上げた。オーバーサイズのパーカー、DHLのロゴのTシャツ、極端に長い袖、古着のリーバイスを継ぎ合わせたジーンズなど、日常着をそのまま引用した服で2015〜2017年に大旋風を起こし、ラグジュアリーとストリートの境界を変えた。\n2015年10月にBalenciagaのアーティスティックディレクターに就任し、約10年率いた。巨大なショルダーのコート、トリプルS（2017年）、トラック、スピード・トレーナー、IKEAのバッグに似たトート、Crocsとの協業、ゲーム「Afterworld」での発表、泥のランウェイや吹雪のショーなど、挑発的で社会を映す演出で時代を作った。2021年には1968年以来途絶えていたクチュールを再開した。2022年11月の広告の炎上で大きな批判を受けたが、その後も活動を続けた。\n2019年にVetementsを離れ、2025年7月からGucciのアーティスティックディレクター。2025年9月にルックブック「La Famiglia」と映画「The Tiger」でデビューし、2026年2月に初のランウェイ「Primavera」を発表した。",
    "mentors": [
      "wvb",
      "ghesquiere"
    ]
  },
  "blazy": {
    "en": "Matthieu Blazy",
    "ja": "マチュー・ブレイジー",
    "bio": "1984年、パリ生まれ。ブリュッセルの名門ラ・カンブルでファッションを学び、2007年に卒業した。\n卒業後すぐにラフ・シモンズのメンズのデザイナーとして働き、2011年からMaison Martin Margielaのアーティザナル（手仕事のクチュールライン）のデザインを担当した。匿名のブランドだったため名前は出なかったが、彼の手がけたコレクションは高く評価された。2014年にCéline（フィービー・ファイロのもと）、2016年からラフ・シモンズとともにCalvin Klein（シニア・バイス・プレジデント・オブ・デザイン）で働いた。\n2020年にBottega Venetaのプレタポルテのデザインディレクターとなり、2021年11月、ダニエル・リーの後任としてクリエイティブディレクターに就任した。2022-23年秋冬のデビューでは、ジーンズやネルシャツ、タンクトップに見えるものをすべて革で作るという驚きの手法で、イタリアの職人技術を見せた。カリメロ、サーディン、アンディアーモなどのバッグもヒットした。\n2024年12月にChanelのアーティスティックディレクターに指名され、2025年10月6日にグラン・パレでデビュー。ガブリエル・シャネルの歴史を3つの章で読み直すコレクションで、高い評価を得た。",
    "mentors": [
      "raf",
      "philo"
    ]
  },
  "hedi": {
    "en": "Hedi Slimane",
    "ja": "エディ・スリマン",
    "bio": "1968年、パリ生まれ。チュニジア人の父とイタリア人の母の間に生まれた。10代で写真を始め、エコール・デュ・ルーヴルで美術史を学んだ。\n1990年代初めに、ファッションコンサルタントのジャン＝ジャック・ピカールのもとで、Louis Vuittonのモノグラム・キャンバス100周年（1996年）の企画などに関わった。1996年にYves Saint Laurentに入り、1997年からRive Gauche Hommeのディレクターとして、サンローランの紳士服を若々しく細いシルエットに作り変えた。\n2000年にDior Hommeのクリエイティブディレクターに就任し、2001-02年秋冬「Solitaire」でデビューした。極端に細いスーツ、スキニーなパンツ、ロックバンドの若者を思わせるスタイルは、2000年代のメンズのシルエットを世界的に塗り替えた。カール・ラガーフェルドがこの服を着るために約40kgの減量をしたという逸話も残る。ショーの音楽にはザ・リバティーンズ、フランツ・フェルディナンドなど若いロックバンドを起用し、その世界観を写真集でも発表した。\n2007年にDiorを離れ、ベルリンやロサンゼルスで写真家として活動した。2012年にSaint Laurentのクリエイティブディレクターとなり、表記を「Yves Saint Laurent」から「Saint Laurent」に変え、スタジオをロサンゼルスに移した。グランジやロックを打ち出したコレクションで売上を大きく伸ばし、2016年に退任。2018年から2024年まではCelineを率い、アクサンを外した「Celine」でロックな服とメンズを打ち出した。\n古着では、Dior Homme期（2001〜2007）、Saint Laurent期（2012〜2016）、Celine期のメンズ・ウィメンズのジャケットやデニム、ブーツが高く評価されている。"
  },
  "ghesquiere": {
    "en": "Nicolas Ghesquière",
    "ja": "ニコラ・ジェスキエール",
    "bio": "1971年、フランス北部のコミーヌ生まれ。ロワール地方のルーダンで育ち、ファッションの専門学校には通わず、14歳の頃からアニエスベーのもとでインターンを経験した。のちにジャン＝ポール・ゴルチエのアシスタントを務めた。\n1995年頃にBalenciagaに入り、日本のライセンス向けの喪服などを担当した。1997年、25歳の若さでBalenciagaのクリエイティブディレクターに抜擢された。当時のBalenciagaはほぼ忘れられたメゾンだったが、ジェスキエールは創業者クリストバル・バレンシアガのアーカイブを研究しつつ、未来的なシルエット、スポーツ素材、ネオプレン、パッチワーク、ロボットのような金色のレギンス（2007年春夏）など、新しい時代の服を次々に発表した。2001年には、当初25個しか作らなかったモーターサイクルバッグ（City）がケイト・モスらに愛用されて大ヒットし、メゾンの経営を立て直した。\n2012年に15年在籍したBalenciagaを離れ、2013年11月にマーク・ジェイコブスの後任としてLouis Vuittonのウィメンズのアーティスティックディレクターに就任。2014年3月、ルーヴル美術館のクール・カレでデビューした。以後、プティット・マルなどのバッグ、SF的なシルエットと歴史的な衣装を混ぜた服、世界各地の建築物でのクルーズ・ショーで10年以上ブランドを率いている。\n古着では、Balenciaga期（1997〜2012）の服やモーターサイクルバッグ、2000年代の靴が再評価されている。",
    "mentors": [
      "gaultier"
    ]
  },
  "gaultier": {
    "en": "Jean Paul Gaultier",
    "ja": "ジャン＝ポール・ゴルチエ",
    "bio": "1952年、パリ郊外のアルクイユ生まれ。会計士の父と事務員の母のもと、祖母の美容室で過ごす時間が長く、祖母のコルセットや、テレビで見たフォリー・ベルジェールのショー、映画『偽れる装い』に強く影響を受けた。ファッションの学校には通わず、スケッチをクチュリエたちに送り続けた。\n1970年、18歳の誕生日にピエール・カルダンに採用され、ジャック・エステレル、ジャン・パトゥ（ミシェル・ゴマのもと）でも経験を積んだ。1976年に自身のブランドを始め、1980年代に「アンファン・テリブル（恐るべき子ども）」と呼ばれるようになった。\nゴルチエの服は、性や美の常識を軽やかにひっくり返すことに特徴がある。マリンボーダーのセーター、円錐形のブラ（1990年のマドンナの「ブロンド・アンビション」ツアーの衣装が有名）、男性のスカート（1985年「Et Dieu créa l'homme」）、タトゥー柄のメッシュのトップス、コルセット、胴体の形をした香水「Classique」（1993年）のボトルなど。モデルに年配の女性、太った人、タトゥーの入った人、街で見つけた人を起用し、多様性の先駆けとなった。ペドロ・アルモドバル、リュック・ベッソン（『フィフス・エレメント』）、ピーター・グリーナウェイの映画衣装も手がけた。\n1997年にオートクチュールを始め、2003年から2010年まではHermèsのウィメンズのクリエイティブディレクターも兼任し、馬具のディテールを生かした服を作った。2011年から2015年にかけて世界各地を巡回した大回顧展「The Fashion World of Jean Paul Gaultier」も開かれた。\n2014年にプレタポルテを終了し、2020年1月のクチュールのショーで引退した。以後は毎シーズン別のデザイナー（sacaiの阿部千登勢、Y/Projectのグレン・マーティンス、オリヴィエ・ルスタン、ハイダー・アッカーマン、シモーン・ロシャなど）がクチュールを手がけている。古着では1990年代のメッシュやタトゥー柄、ボーダー、デニムが非常に人気。"
  },
  "lemaire": {
    "en": "Christophe Lemaire",
    "ja": "クリストフ・ルメール",
    "bio": "1965年、フランスのベサンソン生まれ。10代でパリに出て、イヴ・サンローラン、ティエリー・ミュグレー、ジャン・パトゥ（クリスチャン・ラクロワのもと）で経験を積んだ。1991年に自身のブランド「Christophe Lemaire」を始めた。\nルメールの服は、派手さを避け、日常の中で長く着られる上質な服を目指している。ゆったりとしたシルエット、柔らかい素材、アジアやアフリカの民族衣装、ワークウェア、ユニフォームから着想した静かなデザインが特徴。\n2001年から2010年まではLacosteのクリエイティブディレクターとしてポロシャツのブランドを洗練させ、2010年から2014年まではHermèsのウィメンズのクリエイティブディレクターを務めた。Hermès時代も、素材と仕立ての良さを生かした落ち着いた服で評価された。\n2014年からはパートナーのサラ＝リン・トランとともに自身のブランドに専念し、ブランド名を「LEMAIRE」とした。2016年からはユニクロと「Uniqlo U」も手がけている。クロワッサンの形をしたバッグなどもヒットしている。"
  },
  "vanhee": {
    "en": "Nadège Vanhée",
    "ja": "ナデージュ・ヴァネ",
    "bio": "1978年、フランス北部生まれ。アントワープ王立芸術アカデミーのファッション科を2002年に卒業した。卒業後はマルタン・マルジェラのアシスタントとして働き、匿名的で知的な服づくりを学んだ。\nその後、Céline（フィービー・ファイロのもとでデザインディレクター）、The Row（デザインディレクター）で、上質な素材と端正な仕立ての「静かなラグジュアリー」の服づくりに携わった。\n2014年、クリストフ・ルメールの後任としてHermèsのウィメンズのアーティスティックディレクターに就任した。2015年3月のデビュー・コレクションでは乗馬をテーマに、馬具の革、深い色、無駄のないシルエットを使い、ブランドの原点を現代の女性の服にした。以後もレザーの扱いと素材の良さを中心に、主張しすぎない強さのある服を作り続けている。",
    "mentors": [
      "margiela",
      "philo"
    ]
  },
  "nichanian": {
    "en": "Véronique Nichanian",
    "ja": "ヴェロニク・ニシャニアン",
    "bio": "1954年、パリ近郊のブーローニュ＝ビヤンクール生まれ。アルメニア系の家族に育ち、パリ・クチュール組合の学校で学んだ。\n卒業後、イタリアのメンズの名門ニノ・チェルッティのもとで約12年間、メンズのデザインを担当した。1988年、Hermèsのジャン＝ルイ・デュマに招かれ、Hermèsのメンズのアーティスティックディレクターに就任した。\nニシャニアンは、ロゴや派手な装飾に頼らず、上質な素材、深い色、手仕事の革製品、着心地の良さでHermèsのメンズを築いた。ニットのような軽いジャケット、リバーシブルのコート、革のブルゾン、オレンジやテラコッタなどの色彩の使い方で知られる。37年間で70回以上のショーを行い、ファッション業界で最も長く同じメゾンのメンズを率いたデザイナーの一人となった。\n2026年1月24日、パリのパレ・ブロンニャールで最後のショーを行い、スタンディングオベーションで送られた。後任はグレース・ウェールズ・ボナー。古着では、ニシャニアン期のHermèsのメンズのレザーやニットは、ロゴがなく上質で、長く評価されている。"
  },
  "walesbonner": {
    "en": "Grace Wales Bonner",
    "ja": "グレース・ウェールズ・ボナー",
    "bio": "1990年、ロンドン生まれ。ジャマイカ人の父と英国人の母を持ち、南ロンドンで育った。セントラル・セント・マーチンズで学び、2014年の卒業コレクション「Afrique」が評価されて、同年自身のブランド「Wales Bonner」を立ち上げた。\nウェールズ・ボナーの服は、黒人のアイデンティティやアフリカ系ディアスポラの歴史、音楽（ジャズやレゲエ）、文学、宗教、アートをテーマにしたコレクションで知られる。英国のテーラリングと、1970年代のスポーツウェア、クロシェや手刺繍などの手仕事を組み合わせ、知的で優雅な男性像を作る。\n2015年にLVMHプライズの新人賞を受賞し、2016年にLVMHプライズのグランプリを受賞した。adidas Originalsとの協業ではサンバやガゼルなどのスニーカーが大ヒットし、2020年代のスニーカーの流行を作った。2019年にはロンドンのサーペンタイン・ギャラリーで展覧会も企画した。\n2025年10月、37年間続いたヴェロニク・ニシャニアンの後任として、Hermèsのメンズのクリエイティブディレクターに就任した。主要なメゾンを率いる初の黒人女性の一人で、2027年1月にデビュー予定。"
  },
  "ysl": {
    "en": "Yves Saint Laurent",
    "ja": "イヴ・サンローラン",
    "bio": "1936年、当時フランス領だったアルジェリアのオランで生まれる。裕福な家庭に育ったが、学校ではいじめに苦しみ、紙の人形の服や母や妹の服をデザインして過ごした。\n17歳でパリに出て、1954年に国際羊毛事務局のデザインコンテストのドレス部門で優勝（コート部門の優勝者はカール・ラガーフェルド）。ヴォーグ編集長ミシェル・ド・ブリュノフの紹介でクリスチャン・ディオールのアシスタントとなり、1957年のディオールの急死を受けて、21歳でDiorのアーティスティックディレクターに就任した。1958年の最初のコレクション「トラペーズ・ライン」は大成功し、メゾンを救ったと称賛された。\n1960年にアルジェリア戦争のための徴兵で入隊したが、精神的に崩れて入院し、その間にDiorを解雇された。1961年、パートナーのピエール・ベルジェとともに自身のメゾンを設立し、1962年1月に最初のコレクションを発表した。\nサンローランは、男性の服を女性の服に取り入れることで、女性の服を自由にした。1965年のモンドリアン・ドレス、1966年の女性のタキシード「ル・スモーキング」、1968年のサファリ・ジャケットとシースルーのブラウス、パンツスーツなど。1966年にはクチュールのメゾンとして初めてプレタポルテのブティック「Saint Laurent Rive Gauche」を開いた。1971年には1940年代の占領期を引用したコレクションが「スキャンダル」と呼ばれ、1976年のバレエ・リュス、1977年の中国（香水「オピウム」）、1979年のピカソへのオマージュなど、歴史や芸術への壮大なオマージュでも知られる。黒人やアジア人のモデルを積極的に起用したことでも先駆的だった。\n1983年にはメトロポリタン美術館で存命のデザイナーとして初めて個展が開かれた。1999年にGucciグループがブランドを買収し、2002年1月のポンピドゥー・センターでの回顧ショーを最後に引退した。2008年6月1日、パリで死去。マラケシュのマジョレル庭園の再生にも尽くし、パリとマラケシュに美術館がある。",
    "mentors": [
      "dior"
    ]
  },
  "pilati": {
    "en": "Stefano Pilati",
    "ja": "ステファノ・ピラーティ",
    "bio": "1965年、ミラノ生まれ。ファッションの学校には通わず、10代でチェルッティのアシスタントとして働き始めた。ジョルジオ・アルマーニのメンズ、PradaとMiu Miuでの素材研究（1990年代後半）で経験を積んだ。\n2000年、トム・フォードに招かれてYves Saint Laurentに参加し、ウィメンズのデザインディレクターとしてフォードを支えた。2004年、フォードの退任を受けてYves Saint Laurentのクリエイティブディレクターに就任した。最初の2005年春夏で、幅広のベルトで絞ったチューリップスカートを発表してシルエットを一変させ、ル・スモーキングを短いコートドレスにするなど、創業者のアーカイブを知的に再解釈した。メンズでは2008-09年秋冬をショーではなくファッションフィルムで発表した。ミューズ・バッグ、トリビュート・サンダルなども人気になった。\n2012年にSaint Laurentを離れ、2012〜2016年はErmenegildo Zegnaのヘッド・オブ・デザインとしてメンズを率いた。2017年には自身のブランド「Random Identities」を始め、ジェンダーを越えた服を発表している。",
    "mentors": [
      "tomford"
    ]
  },
  "vaccarello": {
    "en": "Anthony Vaccarello",
    "ja": "アンソニー・ヴァカレロ",
    "bio": "1982年、ブリュッセル生まれ。イタリア系の家庭に育つ。最初は法律を学ぶつもりだったが、ブリュッセルのラ・カンブルでファッションを学んだ。2006年にイエール国際モード&写真フェスティバルでグランプリを受賞し、カール・ラガーフェルドの目に留まった。\nFendiでラガーフェルドのもと約2年、毛皮のデザインを担当したのち、2009年に自身のブランドを始めた。深いスリットのドレス、ボディを強調した黒い服で、2011年にANDAM賞を受賞。アンソニー・ヴァカレロのセクシーで鋭い服は、ジジ・ハディッドらに愛用された。2015年にはVersaceのセカンドライン「Versus」のクリエイティブディレクターも務めた。\n2016年4月、エディ・スリマンの後任としてSaint Laurentのクリエイティブディレクターに就任した。1980年代風の大きな肩、極端に短いドレス、レザーとレース、YSLのロゴを使ったOpyumのヒール、エッフェル塔の前でのショーなどで、イヴ・サンローランの官能性とパリの夜の空気を受け継いだ。2023年にはSaint Laurent Productionsを立ち上げ、ペドロ・アルモドバルやデヴィッド・クローネンバーグの映画の製作にも関わった。\n約10年率いたのち、2026年9月29日の金色のショーを最後に、10月9日に退任が発表された。",
    "mentors": [
      "lagerfeld"
    ]
  },
  "dior": {
    "en": "Christian Dior",
    "ja": "クリスチャン・ディオール",
    "bio": "1905年、ノルマンディー地方の海辺の町グランヴィルで、肥料工場を営む裕福な家に生まれた。両親は外交官になることを望み、パリの政治学院で学んだが、本人は芸術に惹かれた。\n1928年、父の援助で友人とパリに画廊を開き、ピカソ、ダリ、ジャコメッティなどを扱ったが、世界恐慌で家業が破産し、画廊も閉じた。生活のためにファッションのイラストを描いて売るようになり、1938年にロベール・ピゲ、1941年にリュシアン・ルロンのもとでデザイナーとして働いた（ルロンではピエール・バルマンと同僚だった）。\n1946年、繊維業の実業家マルセル・ブサックの出資でメゾンを設立した。1947年2月12日の最初のコレクション「コロール（花冠）ライン」は、絞ったウエストとたっぷりした長いスカートで、戦時中の質素な服に疲れた女性たちに熱狂的に迎えられ、ハーパーズ・バザーの編集長カーメル・スノーが「なんて新しいルック（New Look）！」と言ったことから「ニュールック」と呼ばれた。一方で、布を大量に使う服は物資不足の時代に批判も受けた。\nその後も毎シーズン、H・A・Yなどアルファベットの「ライン」で新しいシルエットを打ち出し、香水「ミス・ディオール」、ライセンス事業、世界的な販売網など、現代のファッションビジネスの仕組みを作った。迷信深く、占い師の助言を大事にしたことでも知られる。1957年10月、イタリアの温泉地モンテカティーニで心臓発作で急死した。後継者は21歳のイヴ・サンローランだった。"
  },
  "bohan": {
    "en": "Marc Bohan",
    "ja": "マルク・ボアン",
    "bio": "1926年、パリ生まれ。帽子職人の母の影響で服に興味を持ち、ロベール・ピゲ、エドワード・モリヌー、ジャン・パトゥで経験を積んだ。1958年からDiorのロンドンの店の服を担当した。\n1960年（1961年とする資料もある）、兵役で離れたイヴ・サンローランの後任としてDiorのアーティスティックディレクターに就任し、1989年まで約30年間率いた。最初のコレクション「スリム・ルック」（1961年）で、ゆったりした細身の服を打ち出し、時代の変化に合わせた着やすく優雅な服でメゾンを安定させた。1967年には斜めのロゴを総柄にした「ディオール・オブリーク」を考案し、のちにガリアーノのサドルバッグなどで復活する。グレース・ケリーやエリザベス・テイラーらを顧客にした。\nDiorを離れたのち、1990年から英国王室御用達のNorman Hartnellのデザインを手がけた。2023年9月に97歳で死去した。"
  },
  "ferre": {
    "en": "Gianfranco Ferré",
    "ja": "ジャンフランコ・フェレ",
    "bio": "1944年、ミラノ近郊のレニャーノ生まれ。ミラノ工科大学で建築を学び、1969年に卒業した。その後、アクセサリーやジュエリーのデザイン、インドでの仕事などを経て、1978年に自身のブランド「Gianfranco Ferré」を設立した。\nフェレは建築の知識を服に生かし、白いシャツを構造的に組み立てる作風で「ファッションの建築家」と呼ばれた。白いシャツは彼の代名詞となり、さまざまな形の白いシャツを発表した。\n1989年、マルク・ボアンの後任としてDiorのアーティスティックディレクターに就任した。イタリア人がフランスのメゾンを率いることは当時大きな話題になったが、豪華で構築的なクチュールで評価された。1996年にDiorを離れ、自身のブランドに専念した。2007年6月、ミラノで脳出血のため死去した。"
  },
  "galliano": {
    "en": "John Galliano",
    "ja": "ジョン・ガリアーノ",
    "bio": "1960年、イギリス領ジブラルタル生まれ。父はジブラルタル人、母はスペイン人で、6歳のときに家族でロンドンへ移った。セントラル・セント・マーチンズで学び、1984年の卒業コレクション「Les Incroyables」はフランス革命期の若者の装いに着想したもので、ロンドンのブティック「Browns」がそのまま買い取り、ウィンドウに飾った。\n自身のブランドを始めたが、資金難が続き、1990年にパリへ拠点を移した。1994年、出資者を失いかけた時期に、アンドレ・レオン・タリーとアナ・ウィンターの支援で、貴族の邸宅を借りて行ったショーが伝説になった。\n1995年にGivenchyのクリエイティブディレクター、1996年にDiorのクリエイティブディレクターに就任した。ガリアーノのDiorは、歴史、民族衣装、映画、旅を大胆に組み合わせた演劇的なショーで知られ、マサイ族に着想した最初のクチュール（1997年）、ホームレスに着想したクチュール（2000年）、エジプト（2004年）、ヴェルサイユでの60周年（2007年）などは今も語られる。サドルバッグ、新聞柄、オブリークの復活などでブランドを若い世代に広げた。バイアスカットの名手でもあった。\n2011年2月、パリのバーでの反ユダヤ的な発言が動画で広まり、Diorを解任され、フランスの裁判で有罪判決を受けた。依存症の治療を経て、2013年にOscar de la Rentaのアトリエに短期間滞在したのち、2014年10月にMaison Margielaのクリエイティブディレクターに就任した。アーティザナルを中心に、マルジェラの手法とガリアーノの演劇性を融合させ、2024年1月の「月の光の中の」アーティザナルのショーは近年最高のショーの一つと絶賛された。2024年12月に退任した。2023年にはドキュメンタリー『High & Low – John Galliano』も公開された。"
  },
  "chiuri": {
    "en": "Maria Grazia Chiuri",
    "ja": "マリア・グラツィア・キウリ",
    "bio": "1964年、ローマ生まれ。母は洋装店を営んでいた。ローマのIstituto Europeo di Designでファッションを学び、1989年にFendiに入社。そこでピエールパオロ・ピッチョーリと出会い、二人でアクセサリーのデザインを担当し、バゲット・バッグの時代のFendiを支えた。\n1999年、ピッチョーリとともにValentinoに移り、ヴァレンティノ・ガラヴァーニのもとでアクセサリーを担当した。2008年、創業者の引退とアレッサンドラ・ファッキネッティの短い在任を経て、ピッチョーリとともにValentinoの共同クリエイティブディレクターに就任した。二人のValentinoは、ロックスタッズのシューズ、ロマンティックで繊細なドレスでブランドを再生させ、売上を大きく伸ばした。\n2016年、Dior初の女性アーティスティックディレクターに就任した。デビューの2017年春夏で、チママンダ・ンゴズィ・アディーチェのエッセイの題名「We Should All Be Feminists」をプリントしたTシャツを発表し、フェミニズムをテーマにしたコレクションで知られるようになった。ブックトート、サドルバッグの復活、J'Adiorのスリングバックなどのヒットでも売上を大きく伸ばした。女性のアーティストとの協業も多かった。\n2025年5月にDiorを離れ、同年Fendiのチーフ・クリエイティブ・オフィサーに就任し、キャリアを始めたメゾンに戻った。"
  },
  "kimjones": {
    "en": "Kim Jones",
    "ja": "キム・ジョーンズ",
    "bio": "1973年、ロンドン生まれ。水文地質学者の父の仕事で、幼少期をエクアドル、ケニア、タンザニア、ボツワナなどで過ごし、アフリカの自然や文化が後の作品の大きな着想源になった。セントラル・セント・マーチンズでメンズを学び、2002年に卒業。卒業コレクションはジョン・ガリアーノに買われた。\n2003年に自身のブランドを始め、ロンドンのストリートとクラブカルチャーを取り入れたメンズで注目された。Umbro、Topman、Mulberryとの協業を経て、2008〜2011年にAlfred Dunhillのクリエイティブディレクターを務めた。\n2011年、Louis Vuittonのメンズのスタイルディレクターに就任し、旅やアフリカ、日本のストリートカルチャー、藤原ヒロシ（fragment design）との協業などで、メンズを大きく成長させた。2017年のSupremeとの協業は、ラグジュアリーとストリートの融合の象徴となった。\n2018年、Diorのメンズのアーティスティックディレクターとなり、名前を「Dior Homme」から「Dior Men」に変えた。KAWS、空山基、レイモンド・ペティボン、ダニエル・アーシャム、ケニー・シャーフらアーティストとの協業、NIKEとのAir Jordan 1 Dior（2020年）、Stüssyとの協業などで人気を集めた。2020〜2024年はFendiのウィメンズとクチュールのアーティスティックディレクターも兼任した。2025年1月にDiorを退任した。\nストリートカルチャーと古着、ヴィンテージの熱心なコレクターとしても知られる。"
  },
  "anderson": {
    "en": "Jonathan Anderson",
    "ja": "ジョナサン・アンダーソン",
    "bio": "1984年、北アイルランドのマヘラフェルト生まれ。父はラグビーのアイルランド代表選手だった。俳優を目指してワシントンD.C.で演劇を学んだが、衣装に興味を持ち、ロンドン・カレッジ・オブ・ファッションでメンズを学んだ。在学中から、ロンドンのPradaの店でビジュアル・マーチャンダイザーとして働き、ミウッチャ・プラダの仕事に強い影響を受けた。\n2008年に自身のブランド「JW Anderson」を始め、フリルのショーツやスカートをはいた男性、男女の境界を越えるデザインで注目された。2010年にウィメンズも始め、Topshop、Uniqlo、Converseなどとの協業でも知られる。2013年にLVMHがJW Andersonに出資し、同時にLoeweのクリエイティブディレクターに就任した。\nアンダーソンのLoeweは、パズル・バッグ、ハンモック・バッグ、陶芸やバスケットなど世界の工芸とのつながり、「ロエベ クラフト プライズ」の創設、現実離れしたシルエットや素材のトロンプ・ルイユ（だまし絵）のショーなどで、スペインの老舗を世界的に最も注目されるブランドの一つにした。映画『チャレンジャーズ』『クィア』（ルカ・グァダニーノ監督）の衣装も手がけた。\n2025年4月にDiorのメンズ、6月にウィメンズとクチュールのクリエイティブディレクターに就任し、創業者以来初めてDiorのすべてのコレクションを統括することになった。2025年6月にメンズ、10月にウィメンズ、2026年1月にクチュールでデビューした。"
  },
  "philo": {
    "en": "Phoebe Philo",
    "ja": "フィービー・ファイロ",
    "bio": "1973年、パリで英国人の両親のもとに生まれ、ロンドン郊外で育った。セントラル・セント・マーチンズで学び、1996年に卒業。在学中に知り合った同級生ステラ・マッカートニーが1997年にChloéのクリエイティブディレクターに就任すると、そのアシスタントとしてパリへ渡った。\n2001年、ステラが自身のブランドを始めるために去ると、27歳でChloéのクリエイティブディレクターに就任した。ファイロのChloéは、フリルのブラウス、ハイウエストのジーンズ、ウェッジソールのサンダル、大きな南京錠をつけた「パディントン・バッグ」（2005年）などで、若い女性の「ボーホー・シック」の流行を作った。2006年、家族と過ごす時間を優先して退任した。\n2008年、LVMHに招かれてCélineのクリエイティブディレクターに就任した。ファイロのCélineは、上質な素材、無駄のない形、ゆったりしたパンツ、大きなコート、フラットな靴など、自分の人生を生きる知的な大人の女性のための服で、2010年代のファッションの女性像を定義した。顔のように見える「ラゲージ・トート」、トラペーズ、ベルト・バッグ、毛皮のついたサンダル（通称「ファーキンストック」）などがヒットした。広告では作家ジョーン・ディディオンを起用したことも話題になった。熱心なファンは「Philophiles」と呼ばれた。\n2017年に退任したのち長い沈黙を経て、2023年10月、LVMHの少数出資を受けて自身のブランド「Phoebe Philo」をオンライン販売で始めた。古着では、Céline期（2008〜2017）の服やバッグが「Old Céline」として非常に人気がある。",
    "mentors": [
      "stellamccartney"
    ]
  },
  "kors": {
    "en": "Michael Kors",
    "ja": "マイケル・コース",
    "bio": "1959年、ニューヨーク州ロングアイランド生まれ。本名はカール・アンダーソン・ジュニア。母は元モデル。ファッション工科大学（FIT）に入学したが9か月で中退し、マンハッタンのブティック「Lothar's」で働きながら服をデザインした。\n1981年に自身のブランド「Michael Kors」を始め、アメリカらしいスポーティーで実用的なラグジュアリーの服を作った。1990年代にはディフュージョンラインも展開した。\n1997年、LVMHが買収したCélineの初代レディ・トゥ・ウェアのクリエイティブディレクターに就任し、2004年まで、ヨットやリゾートを思わせるアメリカ的な明るい服をパリのメゾンに持ち込んだ。2004年からはテレビのリアリティ番組『プロジェクト・ランウェイ』の審査員として一般にも有名になった。\nその後、手頃な価格のバッグを中心に自身のブランドを世界的な企業に成長させ、2018年にVersace、2017年にジミー・チュウを買収した（グループは「Capri Holdings」となり、Versaceは2025年にPradaへ売却）。"
  },
  "rider": {
    "en": "Michael Rider",
    "ja": "マイケル・ライダー",
    "bio": "アメリカ出身。ブラウン大学で学んだのち、ファッションの道に進んだ。Balenciagaでニコラ・ジェスキエールのもとで働いたのち、2008年からCéline（フィービー・ファイロのもと）で約10年間働き、デザインディレクターとしてファイロの右腕を務めた。ファイロのCélineの知的なミニマリズムを内側から支えた一人とされる。\n2019年、Polo Ralph Laurenのクリエイティブディレクターに就任し、アメリカの定番の服を新しく見せる仕事をした。2024年10月、エディ・スリマンの後任としてCelineのクリエイティブディレクターに就任し、2025年7月にデビューした。ファイロ期の大人の女性像と、Celineの歴史的なアーカイブ（1970年代のブルジョワ的なスタイル）を組み合わせたコレクションで評価されている。",
    "mentors": [
      "ghesquiere",
      "philo"
    ]
  },
  "balenciaga": {
    "en": "Cristóbal Balenciaga",
    "ja": "クリストバル・バレンシアガ",
    "bio": "1895年、スペイン・バスク地方の漁村ゲタリアに生まれた。父は漁師で村長も務めたが、早くに亡くなり、母はお針子として家計を支えた。少年時代、避暑に来ていたカーサ・トーレス侯爵夫人のスーツを見事に再現して才能を見いだされ、彼女の支援でサン・セバスティアンの仕立て屋で修業した。\n1917年（1919年とする資料もある）、サン・セバスティアンに最初の店を開き、のちにマドリード、バルセロナにも店を構えて、スペイン王室や貴族を顧客にした。スペイン内戦を避けて1937年にパリへ移り、ジョルジュ・サンク通りにメゾンを開いた。\nバレンシアガは、生地の裁断から縫製まですべての工程を自分でこなせる数少ないクチュリエで、ココ・シャネルに「本物のクチュリエは彼だけ」、クリスチャン・ディオールに「私たち全員の師」と言われた。肩や背中の線を立体的に操作し、身体から少し離れた服を作ることで、20世紀の女性のシルエットを変えた。1950年代のバルーン・スカート、チュニック（1955年）、サック・ドレス（1957年）、ベビードール（1958年）、「四次元」と呼ばれた張りのあるガザール素材のドレスやコート（1967年）などが代表作。スペインの闘牛士の衣装、宗教画、民族衣装も重要な着想源だった。\n弟子にはユベール・ド・ジバンシィ、アンドレ・クレージュ、エマニュエル・ウンガロ、オスカー・デ・ラ・レンタらがいる。プレタポルテの時代の到来を受け入れられず、1968年にメゾンを閉じた。1972年に死去。2011年、故郷ゲタリアに「クリストバル・バレンシアガ美術館」が開館した。"
  },
  "thimister": {
    "en": "Josephus Thimister",
    "ja": "ジョセフス・ティミスター",
    "bio": "1962年、オランダのマーストリヒト生まれ。アントワープ王立芸術アカデミーのファッション科で学び、1986年に卒業した。卒業後、カール・ラガーフェルドのブランドやジャン・パトゥでアシスタントとして経験を積んだ。\n1992年、長く眠っていたBalenciagaのクリエイティブディレクターに就任した。クリストバル・バレンシアガの構築的な服の精神を、1990年代らしいミニマルでモダンな服として再解釈し、メゾンをファッションの表舞台に戻す最初の一歩を作った。1997年に退任し、後任はアシスタントだったニコラ・ジェスキエールだった。\n退任後は自身のブランド「Josephus Thimister」をパリで発表し、ダークで構築的な服、のちにクチュール的な作品を作った。2019年に死去した。",
    "mentors": [
      "lagerfeld"
    ]
  },
  "wang": {
    "en": "Alexander Wang",
    "ja": "アレキサンダー・ワン",
    "bio": "1983年、サンフランシスコ生まれ。台湾系アメリカ人の家庭に育った。10代でファッションに強い関心を持ち、ニューヨークのパーソンズ美術大学に入学したが、2年で中退した。在学中から雑誌『Teen Vogue』やマーク・ジェイコブスのもとでインターンを経験した。\n2005年頃、ニットのコレクションから自身のブランドを始め、2007年にウィメンズのフルコレクションを発表した。ニューヨークのダウンタウンらしい、黒を中心にしたリラックスした服、ゆったりしたTシャツ、レザー、スポーツウェアの要素で若い世代に大人気となり、2009年にはセカンドラインの「T by Alexander Wang」を始めた。\n2012年12月、ニコラ・ジェスキエールの後任としてBalenciagaのクリエイティブディレクターに就任し、2015年まで務めた。2014年にはH&Mとのスポーツウェアの協業が話題になった。Balenciaga退任後は自身のブランドに専念している。"
  },
  "piccioli": {
    "en": "Pierpaolo Piccioli",
    "ja": "ピエールパオロ・ピッチョーリ",
    "bio": "1967年、ローマ近郊のネットゥーノ生まれ。ローマのIstituto Europeo di Designでファッションを学び、1990年にFendiに入社した。そこでマリア・グラツィア・キウリと出会い、二人でアクセサリーのデザインを担当し、バゲット・バッグの時代を支えた。\n1999年、キウリとともにValentinoに移り、ヴァレンティノ・ガラヴァーニのもとでアクセサリーを担当した。2008年、キウリとともにValentinoの共同クリエイティブディレクターに就任し、ロックスタッズのシューズ、ロマンティックで繊細なドレスでブランドを再生させた。2016年にキウリがDiorへ移ると、単独のクリエイティブディレクターとなった。\nピッチョーリのValentinoは、大胆な色彩、多様なモデルの起用、クチュールの職人の名前をショーで紹介するなど、人間味のあるラグジュアリーで知られた。2022年にはパントーンと開発した蛍光ピンク「ピンクPP」の一色のコレクションで大きな話題を呼んだ。2024年3月にValentinoを退任した。\n2025年5月、Gucciへ移ったデムナの後任としてBalenciagaのクリエイティブディレクターに就任し、10月にデビューしたが、2026年11月に退任が発表された。"
  },
  "givenchy": {
    "en": "Hubert de Givenchy",
    "ja": "ユベール・ド・ジバンシィ",
    "bio": "1927年、フランス北部のボーヴェで、貴族の家に生まれた。父は早くに亡くなり、母と祖父に育てられた。10歳のときにパリ万博のファッション館を見てクチュリエを志した。\n17歳でパリに出て、エコール・デ・ボザールで学びながら、ジャック・ファット、ロベール・ピゲ、リュシアン・ルロンのもとで働き、1947年からエルザ・スキャパレリのもとでブティックを担当した。\n1952年、24歳で自身のメゾンを開いた。最初のコレクション「Les Séparables」は、組み合わせて着るセパレーツを提案するもので、モデルのベッティーナ・グラツィアーニの名を取ったフリル袖の白いコットンのブラウス「ベッティーナ・ブラウス」が大評判になった。\n1953年、映画『麗しのサブリナ』の衣装のために訪ねてきたオードリー・ヘプバーンと出会い、以後40年以上にわたって彼女の私服と、『パリの恋人』『ティファニーで朝食を』『シャレード』などの映画衣装を手がけた。『ティファニーで朝食を』の黒いドレスは映画史上最も有名な服の一つとなった。ジャクリーン・ケネディ、グレース・ケリーらも顧客だった。\n敬愛するクリストバル・バレンシアガとは生涯親しく、彼が引退する際には顧客を託された。1988年にメゾンをLVMHへ売却し、1995年に引退した。晩年は美術品や家具の収集家としても知られ、2018年3月に91歳で死去した。"
  },
  "mcqueen": {
    "en": "Alexander McQueen",
    "ja": "アレキサンダー・マックイーン",
    "bio": "1969年、ロンドンのイーストエンドで、タクシー運転手の父と教師の母の6人きょうだいの末っ子として生まれた。幼い頃から姉たちの服をデザインしていた。16歳で学校を離れ、サヴィル・ロウの老舗テーラー、アンダーソン&シェパード、続いてギーヴズ&ホークスで紳士服の仕立てを学んだ（チャールズ皇太子のスーツの裏地に落書きをしたという伝説がある）。その後、舞台衣装のエンジェルズ&バーマンズ、日本人デザイナーの立野浩二のもと、ミラノのロメオ・ジリでも働いた。\nロンドンに戻ってセントラル・セント・マーチンズの修士課程で学び、1992年の卒業コレクション「Jack the Ripper Stalks His Victims」を、スタイリストのイザベラ・ブロウがすべて買い取った。同年自身のブランドを始め、腰骨より下まで下げた「ボムスター」パンツで注目された。\nマックイーンのショーは、美しさと暴力、死、自然、歴史を同時に描く演劇的なもので、「Highland Rape」（1995年秋冬）、ロボットがドレスにスプレーで色を塗る「No.13」（1999年春夏）、精神病院のような鏡の箱の中の「VOSS」（2001年春夏）、ケイト・モスのホログラムが現れる「Widows of Culloden」（2006年秋冬）、アルマジロの靴が登場した「Plato's Atlantis」（2010年春夏）などが伝説となった。テーラリングの技術の確かさと、スコットランドの家系への誇り（タータン）も特徴。\n1996年から2001年までGivenchyのクリエイティブディレクターも務め、British Designer of the Yearを4回受賞した。2001年にGucciグループと組み、自身のブランドに専念した。2010年2月、母の死の直後に40歳で自ら命を絶った。2011年にメトロポリタン美術館で開かれた回顧展「Savage Beauty」は記録的な来場者を集めた。古着では、スカル柄のスカーフ、2000年代のテーラリングやニットが人気。",
    "mentors": [
      "gigli"
    ]
  },
  "macdonald": {
    "en": "Julien Macdonald",
    "ja": "ジュリアン・マクドナルド",
    "bio": "1971年、ウェールズのマーサー・ティドヴィル生まれ。母が編み物をする姿を見て育ち、ブライトン大学、ロイヤル・カレッジ・オブ・アートでニットを学んだ。在学中から、カール・ラガーフェルドのもとでChanelのニットのデザインに関わり、Koji Tatsunoやアレキサンダー・マックイーンのショーのニットも手がけた。\n1997年に自身のブランドを始め、蜘蛛の巣のように繊細なニットや、きらびやかな装飾のドレスで知られるようになった。2001年、British Designer of the Yearを受賞。同年、マックイーンの後任としてGivenchyのクリエイティブディレクターに就任し、2004年まで務めた（2005年とする資料もある）。華やかで女性らしい服を作ったが、批評家からの評価は分かれた。\nその後は自身のブランドに戻り、セレブリティのドレスやテレビ番組の審査員としても活動している。",
    "mentors": [
      "lagerfeld"
    ]
  },
  "tisci": {
    "en": "Riccardo Tisci",
    "ja": "リカルド・ティッシ",
    "bio": "1974年、イタリア南部のターラントで生まれ、8人きょうだいの末っ子（姉が8人）として貧しい家庭で育った。4歳のときに父を亡くした。17歳でロンドンに渡り、アルバイトをしながらセントラル・セント・マーチンズで学び、1999年に卒業した。\nイタリアに戻ってAntonio Berardi、Puma、Coccapaniなどで働いたのち、2004年に自身の名前でコレクションを発表した。2005年、ジュリアン・マクドナルドの後任としてGivenchyのクリエイティブディレクター（クチュール、プレタポルテ、アクセサリー）に就任した。\nティッシのGivenchyは、カトリックの宗教的なイメージ、ゴシック、ロマ、ストリートやヒップホップを融合させた作風で、ロットワイラー（2011年）やバンビ（2013年）のプリントのスウェット、ナイチンゲールやアンティゴナのバッグで大ヒットを生み、ブランドの売上を大きく伸ばした。カニエ・ウェストやマドンナ、ビヨンセらとの親交でも知られ、トランスジェンダーのモデルを起用するなど多様性の先駆けともなった。2015年9月11日にはニューヨークで、マリーナ・アブラモヴィッチの演出によるショーを行った。\n2017年にGivenchyを離れ、2018年から2022年までBurberryのチーフ・クリエイティブ・オフィサーを務め、新しいTBモノグラムを導入した。"
  },
  "waightkeller": {
    "en": "Clare Waight Keller",
    "ja": "クレア・ワイト・ケラー",
    "bio": "1970年、イングランドのバーミンガムで生まれ、ケント州で育った。ラヴェンズボーン大学、ロイヤル・カレッジ・オブ・アートでニットを学んだ。卒業後、ニューヨークのCalvin Kleinでメンズのデザインを担当し、Ralph Lauren（Purple Label）、Gucci（トム・フォードのもとでウィメンズのシニアデザイナー）で経験を積んだ。\n2005年から2011年まではスコットランドのニットの老舗Pringle of Scotlandのクリエイティブディレクターとしてブランドを現代化し、2011年から2017年まではChloéのクリエイティブディレクターとして、ボヘミアンで女性らしいChloéを洗練させ、ドリュー・バッグなどをヒットさせた。\n2017年、Givenchy初の女性アーティスティックディレクターに就任した。2018年5月、メーガン・マークルとハリー王子の結婚式のウェディングドレスを手がけ、世界的に注目された。2020年にGivenchyを退任し、2023年からはユニクロのグローバル・クリエイティブディレクターを務めている。",
    "mentors": [
      "tomford"
    ]
  },
  "mwilliams": {
    "en": "Matthew M. Williams",
    "ja": "マシュー・M・ウィリアムズ",
    "bio": "1985年、アメリカ・イリノイ州エバンストン生まれ、カリフォルニア州ピズモビーチで育った。ファッションの正式な教育は受けず、ロサンゼルスでレディー・ガガのクリエイティブチーム「Haus of Gaga」の一員として衣装を手がけ、カニエ・ウェストのクリエイティブディレクションにも関わった。ヴァージル・アブローやヘロン・プレストンとともにDJとアートの集団「Been Trill」を結成した。\n2015年、ブランド「1017 ALYX 9SM」（名前は娘の名前や自身の誕生日などから）を始めた。ジェットコースターの安全バーからヒントを得た金属の「ローラーコースター・バックル」、テクニカル素材、ミリタリーとストリートを融合した服で注目され、LVMHプライズのファイナリストにも選ばれた。NIKE、Moncler、Dior（キム・ジョーンズ期）との協業も多い。\n2020年、クレア・ワイト・ケラーの後任としてGivenchyのクリエイティブディレクターに就任し、2023年まで務めた。ハードウェアのディテールやストリートの感覚をGivenchyに持ち込んだ。"
  },
  "burton": {
    "en": "Sarah Burton",
    "ja": "サラ・バートン",
    "bio": "1974年、イングランドのマックルズフィールド生まれ。5人きょうだいの一人。マンチェスターで美術の基礎を学んだのち、セントラル・セント・マーチンズでプリントを学んだ。在学中の1996年、教員の紹介でアレキサンダー・マックイーンのインターンとなり、卒業後の1997年に正式に入社した。\n2000年からマックイーンのウィメンズのデザインの責任者を務め、彼のもっとも身近な協力者として、テーラリングと装飾の技術を支えた。2010年のマックイーンの死後、ブランドのクリエイティブディレクターに就任し、彼の遺したアーカイブを受け継ぎながら、より女性らしく繊細な表現でブランドを続けた。2011年4月には、キャサリン妃（ケンブリッジ公爵夫人）のウェディングドレスを手がけ、世界的に知られるようになった。2012年にOBE、2019年にCBEを受けた。\n2023年に26年在籍したAlexander McQueenを離れ、2024年9月にGivenchyのクリエイティブディレクターに就任した。2025年3月のデビューでは、創業者ユベール・ド・ジバンシィの時代のアーカイブを学び直した、知的で洗練された服で高く評価された。",
    "mentors": [
      "mcqueen"
    ]
  },
  "jacobs": {
    "en": "Marc Jacobs",
    "ja": "マーク・ジェイコブス",
    "bio": "1963年、ニューヨーク生まれ。7歳で父を亡くし、のちに祖母のもとで育った。ハイスクール・オブ・アート・アンド・デザインを経てパーソンズ美術大学に進み、1984年に卒業。卒業コレクションの手編みのセーターが評判となり、在学中からブティックで働きながらデザイナーとしての道を開いた。\n1986年、ビジネスパートナーのロバート・ダフィーとともに自身のブランド「Marc Jacobs」を始めた。1987年に若くしてCFDAのペリー・エリス賞（新人賞）を受賞。1988年、アメリカの老舗Perry Ellisのデザイナーとなったが、1992年春夏、シアトルの若者のネルシャツや古着をそのまま高級素材で作った「グランジ」コレクションを発表し、高く評価された一方で売れず、解雇された。このコレクションは今では伝説となっている。\n1997年、LVMHに招かれてLouis Vuittonのアーティスティックディレクターに就任し、ブランド初のプレタポルテを立ち上げた。ジェイコブスは、スティーヴン・スプラウスのグラフィティ・モノグラム（2001年）、村上隆のマルチカラー・モノグラム（2003年）、リチャード・プリンスのナースのコレクション（2008年）、草間彌生の水玉（2012年）などアーティストとの協業で、バッグの会社だったLouis Vuittonを世界的なファッションブランドに変えた。ショーでは駅、エレベーター、メリーゴーラウンドなどの大がかりなセットも話題になった。\n2013年10月の最後のショーでLouis Vuittonを離れ、自身のブランドに専念した。2001年に始めたセカンドライン「Marc by Marc Jacobs」は2000年代の若者に大人気だった（2015年に統合）。2020年代には1990年代のグランジのコレクションの復刻「Redux Grunge」や、「The Tote Bag」の大ヒットで再び注目されている。"
  },
  "abloh": {
    "en": "Virgil Abloh",
    "ja": "ヴァージル・アブロー",
    "bio": "1980年、アメリカ・イリノイ州ロックフォードで、ガーナから移民した両親のもとに生まれた。母は裁縫師だった。ウィスコンシン大学マディソン校で土木工学を学び、イリノイ工科大学で建築の修士号を取った。ミース・ファン・デル・ローエが設計したキャンパスで学んだことが、のちのデザインに影響を与えた。\n2002年頃からカニエ・ウェストのクリエイティブディレクションに関わり、ジャケットのデザインやステージを手がけた。2009年にはカニエとともにFendiでインターンを経験した。2012年、古着のラルフ・ローレンのフランネルシャツに「PYREX 23」とプリントした「Pyrex Vision」を始め、2013年にミラノで「Off-White」を立ち上げた。\nアブローは、既存のものを3%だけ変える「3%ルール」、引用符で囲んだ言葉（\"SCULPTURE\"、\"FOR WALKING\"など）、斜めのストライプ、結束バンドのようなタグなど、ストリートウェアにアートとデザインの文脈を持ち込む手法で、2010年代後半の最も影響力のあるデザイナーの一人となった。2017年のNIKEとの協業「THE TEN」はスニーカーの歴史に残る。IKEA、Evian、Moncler、Mercedes-Benzなどとの協業も多く、DJとしても活動した。\n2018年、Louis Vuittonのメンズのアーティスティックディレクターに就任し、黒人として初めてフランスのメゾンのこの地位に就いた。パレ・ロワイヤルの虹色のランウェイでのデビュー（2019年春夏）、多様な人種と文化を祝うコレクションで高く評価された。2019年にはシカゴ現代美術館で回顧展「Figures of Speech」が開かれた。2019年に心臓の血管肉腫と診断されたことを公にしないまま仕事を続け、2021年11月28日に41歳で死去した。"
  },
  "pharrell": {
    "en": "Pharrell Williams",
    "ja": "ファレル・ウィリアムス",
    "bio": "1973年、アメリカ・バージニア州バージニアビーチ生まれ。高校時代に知り合ったチャド・ヒューゴと音楽制作ユニット「ザ・ネプチューンズ」を結成し、ブリトニー・スピアーズ、ジャスティン・ティンバーレイク、ジェイ・Z、スヌープ・ドッグらのヒット曲を数多くプロデュースした。バンドN.E.R.D.でも活動し、ソロでは2013年の「Happy」が世界的なヒットとなった。グラミー賞を何度も受賞している。\nファッションへの関心も早く、2003年にNIGOとともにストリートブランド「Billionaire Boys Club」と「ICECREAM」を始めた。2004年にはLouis Vuittonのサングラス「Millionaire」、2008年にはジュエリーのデザインに参加した。adidasとの「Hu」シリーズ、Chanel、Moncler、G-Starなど多くのブランドと協業し、2014年のグラミー賞でかぶったヴィヴィアン・ウエストウッドの大きな帽子も話題になった。2015年にはCFDAのファッション・アイコン賞を受賞した。\n2023年2月、ヴァージル・アブローの死後空席だったLouis Vuittonのメンズのクリエイティブディレクターに就任した。2023年6月、パリのポン・ヌフを金色に染めたデビューショーで、ダミエ柄と迷彩を組み合わせた「ダモフラージュ」を発表し、以後、アメリカ西部、香港、インドなどをテーマにしたコレクションを発表している。"
  },
  "chanel": {
    "en": "Gabrielle Chanel",
    "ja": "ガブリエル・シャネル",
    "bio": "1883年、フランス西部のソミュールで、行商人の父と洗濯婦の母のもとに生まれた。12歳のときに母を亡くし、父に捨てられ、オバジーヌの修道院の孤児院で育った。そこで裁縫を覚え、修道院の白と黒の色、簡素な美しさがのちのデザインに影響したといわれる。\n18歳で修道院を出て、ムーランでお針子として働くかたわら、ナイトクラブで歌った。持ち歌の「Qui qu'a vu Coco」から「ココ」と呼ばれるようになった。騎兵将校エティエンヌ・バルサンの館で暮らし、上流社会の人々に出会ったのち、英国人の実業家アーサー・“ボーイ”・カペルの支援で、1910年、パリのカンボン通り21番地に帽子店を開いた。1913年にドーヴィル、1915年にビアリッツにブティックを開き、当時は下着用の素材だったジャージーで、コルセットのない、動きやすい服を作った。\n1921年、調香師エルネスト・ボーとともに香水「No.5」を発表。1926年のリトル・ブラック・ドレスはアメリカ版ヴォーグで「シャネルのフォード（T型フォードのように誰もが持つもの）」と紹介された。コスチューム・ジュエリー、パールの重ね付け、ツイード、男性の服からの借用（カーディガン、パンツ）など、女性の服を軽く自由にした数々の発明で、20世紀の女性の装いを変えた。カペルの事故死後も、作曲家ストラヴィンスキー、詩人ジャン・コクトー、ウェストミンスター公爵らとの交流が知られる。\n1939年、第二次世界大戦の開戦とともに店を閉じた。占領下ではドイツ人の将校とホテル・リッツで暮らし、戦後はスイスに移った。戦時中の行動は今も議論の的になっている。1954年、71歳でパリに戻って復帰コレクションを発表した。フランスでは冷ややかに迎えられたが、アメリカで大成功し、ツイードのスーツ、キルティングとチェーンの2.55バッグ（1955年）、つま先の黒いバイカラーのパンプスで再び時代の顔となった。1971年1月10日、住まいだったホテル・リッツで87歳で死去した。"
  },
  "lagerfeld": {
    "en": "Karl Lagerfeld",
    "ja": "カール・ラガーフェルド",
    "bio": "1933年、ドイツ・ハンブルク生まれ（本人は年齢を若く公表していた）。父は練乳の会社を経営する実業家で、裕福な家庭に育った。少年時代から絵とファッションに強い関心を持ち、10代でパリに移った。\n1954年、国際羊毛事務局のデザインコンテストのコート部門で優勝した（同じ年、ドレス部門ではイヴ・サンローランが優勝）。ピエール・バルマンのアシスタント、ジャン・パトゥのアーティスティックディレクターを経て、1960年代からは自分のブランドを持たず、複数のブランドを同時に手がけるフリーランスのデザイナーとして活躍した。1964年頃からChloé（1983年まで、1992〜1997年にも再び）、1965年からはFendiの毛皮とウィメンズを担当し、亡くなるまで54年間Fendiに関わった。FendiのFFロゴも彼のデザインとされる。\n1983年、創業者の死後に低迷していたChanelのアーティスティックディレクターに就任した。ラガーフェルドは、CCロゴ、チェーン、ツイード、パール、カメリアなどシャネルの記号を大胆に使い、ヒップホップやサーフ、パンクまで取り込んで、古臭いと思われていたメゾンを世界で最も成功したブランドの一つにした。クラシック・フラップ（1983年）を生み、2005年には2.55の復刻も行った。グラン・パレにスーパーマーケット、ロケット、氷山、ビーチなどを作るショーも名物になった。\n自身のブランド「Karl Lagerfeld」も展開し、写真家として広告やカレンダーを撮影し、書店を経営し、白いポニーテール、黒いサングラス、高い襟のシャツ、指なしの手袋という姿で世界的なアイコンとなった。2001年にはエディ・スリマンのDior Hommeを着るために約40kg減量したことも有名。愛猫シュペットも有名になった。2019年2月19日、パリで死去した。",
    "mentors": [
      "pbalmain"
    ]
  },
  "viard": {
    "en": "Virginie Viard",
    "ja": "ヴィルジニー・ヴィアール",
    "bio": "1962年、フランス・リヨン生まれ。祖父母は絹織物の仕事に携わっていた。舞台や映画の衣装の仕事を経て、1987年、Chanelのオートクチュールの刺繍のインターンとしてカール・ラガーフェルドのもとで働き始めた。\n1992年、ラガーフェルドとともにChloéに移り、1997年にChanelに戻ってオートクチュールとプレタポルテのスタジオ・ディレクターに就任した。30年以上にわたってラガーフェルドの右腕として、彼のスケッチを服にする作業や、職人や工房との調整を担い、「ラガーフェルドの右手であり左手」と呼ばれた。\n2019年2月、ラガーフェルドの死去を受けてChanelのアーティスティックディレクターに就任した。ヴィアールのChanelは、ラガーフェルドの壮大なセットのショーから離れ、より実際に着やすい服、柔らかいツイード、ロマンティックで少女的な要素を打ち出した。在任中にChanelの売上は大きく伸びたが、批評家からの評価は分かれた。最後の3つのコレクションはダカール、マンチェスター、マルセイユで発表し、2024年6月に退任した。",
    "mentors": [
      "lagerfeld"
    ]
  },
  "duran": {
    "en": "Duran Lantink",
    "ja": "デュラン・ランティンク",
    "bio": "1987年、オランダ生まれ。アムステルダムのヘリット・リートフェルト・アカデミーで学び、修士課程はサンドベルグ研究所で修了した。\nランティンクは、売れ残った服や古着、既製品を切り貼りして新しい服にするアップサイクルの手法と、肩や腰を極端に誇張した、身体をデフォルメするシルエットで注目された。ユーモアと批評性のある作風で、ジャネール・モネイらにも着用された。2024年にLVMHプライズの特別賞を受賞した。\n2025年4月、Jean Paul Gaultierのプレタポルテのクリエイティブディレクターに就任した。ゴルチエのブランドが2014年にプレタポルテを終了して以来の、本格的なプレタポルテの再始動を任された。"
  },
  "tomford": {
    "en": "Tom Ford",
    "ja": "トム・フォード",
    "bio": "1961年、アメリカ・テキサス州オースティン生まれ。両親は不動産業者で、ニューメキシコ州サンタフェで育った。ニューヨーク大学で美術史を学んだが中退し、テレビCMの俳優をしながらパーソンズ美術大学でインテリア建築を学んだ。在学中にパリのChloéのプレス部門で働いたことがファッションへ進むきっかけになった。\nキャシー・ハードウィック、ペリー・エリス（マーク・ジェイコブスのもと）で働いたのち、1990年、ドーン・メロに招かれてGucciのウィメンズのデザイナーとして入社した。当時のGucciは一族の争いで倒産寸前だった。1994年にクリエイティブディレクターとなり、服、香水、広告、店舗のすべてを統括した。1995年秋冬のベルベットのヒップハンガーとサテンのシャツのショーで大成功を収め、性的な魅力を前面に出した服とマリオ・テスティーノ撮影の広告で、Gucciを1990年代で最もセクシーなブランドにした。1999年にGucciグループがYves Saint Laurentを買収すると、そのクリエイティブディレクターも兼任した。\n2004年、親会社PPRとの対立から、CEOドメニコ・デ・ソーレとともにGucciとYSLを去った。2005年頃に自身のブランド「Tom Ford」を始め、アイウェア、香水（「Black Orchid」など）、メンズ、2010年からウィメンズを展開した。映画監督としても活動し、『シングルマン』（2009年）、『ノクターナル・アニマルズ』（2016年）を発表した。2019〜2022年にはCFDA（アメリカファッション協議会）の会長も務めた。2023年、ブランドをEstée Lauderに約28億ドルで売却し、ファッションから退いた。"
  },
  "giannini": {
    "en": "Frida Giannini",
    "ja": "フリーダ・ジャンニーニ",
    "bio": "1972年、ローマ生まれ。ローマのファッション・アカデミーで服飾を学んだ。1997年にFendiに入社し、バゲット・バッグの時代のレザーグッズのデザイナーとして働いた。\n2002年、トム・フォードのもとでGucciに入社し、ハンドバッグのデザインディレクターとなった。2004年にフォードが去ると、アクセサリーのクリエイティブディレクターに就任し、1960年代にグレース・ケリーのために作られたとされる花柄「フローラ」をバッグや靴に復活させて大ヒットさせた。2005年にウィメンズ、2006年にメンズを含むブランド全体のクリエイティブディレクターとなった。\nジャンニーニのGucciは、1970年代風のボヘミアン、乗馬、ジャッキー・バッグやバンブーの復刻など、ブランドのアーカイブを生かした商業的に成功した服で知られ、2011年にはフィレンツェにGucci博物館を開いた。一方で、後半には売上の伸び悩みと批評家からの評価の低さに苦しんだ。2014年12月、CEOのパトリツィオ・ディ・マルコ（私生活のパートナー）とともに退任が発表され、2015年1月に予定より早く去った。後任は彼女の右腕だったアレッサンドロ・ミケーレだった。",
    "mentors": [
      "tomford"
    ]
  },
  "michele": {
    "en": "Alessandro Michele",
    "ja": "アレッサンドロ・ミケーレ",
    "bio": "1972年、ローマ生まれ。父はアリタリア航空の技術者で、彫刻家でもあった。母は映画会社で働いていた。ローマの衣装学校「Accademia di Costume e di Moda」で舞台衣装を学び、ニットのブランドLes Copainsでデザイナーとして働き始めた。\n1990年代後半、Fendiでシルヴィア・フェンディのもとアクセサリーのシニアデザイナーとして働き、2002年にトム・フォードに招かれてGucciのロンドンのデザインスタジオに加わった。フリーダ・ジャンニーニのもとでアクセサリーのデザインを長く担当し、2011年には彼女の右腕（アソシエイト）となった。陶磁器ブランドRichard Ginoriのクリエイティブディレクターも兼任した。\n2015年1月、ジャンニーニの突然の退任を受けて、わずか5日間でメンズのコレクションを作り直し、Gucciのクリエイティブディレクターに抜擢された。ミケーレのGucciは、ルネサンスの絵画、1970年代のヴィンテージ、オタクやギーク、ジェンダーレス、昆虫や花、蛇や虎のモチーフ、メガネの男の子と長髪の女の子など、あらゆる時代と文化を混ぜた「マキシマリズム」で、2010年代後半のファッションを塗り替え、売上を数年で倍以上に伸ばした。ファーつきのローファー「Princetown」、Dionysus、GG Marmontがヒットし、ウェストミンスター寺院やアルルの古代墓地でのショー、生首を抱えたCyborgのショー、Balenciagaとの「ハッカー・プロジェクト」なども話題になった。\n2022年11月に退任し、2024年3月にValentinoのクリエイティブディレクターに就任した。古着では、ミケーレ期（2015〜2022）のGucciの服やバッグが近年再評価されている。",
    "mentors": [
      "giannini",
      "tomford"
    ]
  },
  "desarno": {
    "en": "Sabato De Sarno",
    "ja": "サバト・デ・サルノ",
    "bio": "1983年、イタリアのナポリ近郊生まれ。ファッションの道に進み、2005年頃にPradaでパターンなどを担当、その後Dolce & Gabbanaで働いた。\n2009年、Valentinoに入社し、マリア・グラツィア・キウリとピエールパオロ・ピッチョーリのもとでニットやウィメンズを担当した。のちにメンズとウィメンズのファッション・ディレクターとなり、ピッチョーリの右腕として約14年間ブランドを支えた。\n2023年1月、アレッサンドロ・ミケーレの後任としてGucciのクリエイティブディレクターに就任した。同年9月のデビュー・コレクション「Ancora（イタリア語で「もう一度」）」では、ミケーレのマキシマリズムから一転し、深い赤「ロッソ・アンコーラ」、短いスカート、厚底のホースビットローファーなど、シンプルで官能的な服を打ち出した。しかし売上の回復には至らず、2025年2月、約2年で退任した。",
    "mentors": [
      "piccioli",
      "chiuri"
    ]
  },
  "mprada": {
    "en": "Miuccia Prada",
    "ja": "ミウッチャ・プラダ",
    "bio": "1949年、ミラノ生まれ。祖父マリオ・プラダが1913年に始めた革製品店の孫娘として、裕福な家庭に育った。ミラノ大学で政治学を学んで博士号を取り、ミラノのピッコロ・テアトロでパントマイムを5年間学んだ。1970年代にはイタリア共産党に入党し、女性の権利運動にも関わった。本人は「ファッションの仕事をすることに長く後ろめたさを感じていた」と語っている。\n1978年、母から家業を継ぎ、のちに夫となる実業家パトリツィオ・ベルテッリと出会って事業を拡大した。1984年、軍用テントなどに使われていた工業用ナイロン「ポコノ」で作ったバックパックを発表し、高級品は革で作るものという常識を覆した。1988年に初のウィメンズのプレタポルテを発表し、1993年にMiu Miuとメンズを始めた。\nプラダの服は、知的で、少し奇妙で、ときに「醜い」とまで言われる美意識で知られる。1996年春夏の「アグリー・シック」では、1970年代の壁紙のような柄と濁った色を組み合わせ、美しさの基準そのものを問い直した。以後も、オタク的な要素、制服、ユニフォーム、主婦の服などを高級な服に変え、毎シーズン業界の予想を裏切ってきた。1997年にはPrada Sport（Linea Rossa）を始め、テクニカルなスポーツウェアを高級ブランドに持ち込んだ。\n1993年に夫とともに現代美術の財団「フォンダツィオーネ・プラダ」を設立し、2015年にはレム・コールハースのOMAの設計でミラノに美術館を開いた。建築家レム・コールハースやヘルツォーク&ド・ムーロンとの店づくり（エピセンター）でも知られる。2020年からはラフ・シモンズと共同クリエイティブディレクターとしてPradaを率いている。2025年にはPradaグループとしてVersaceを買収した。"
  },
  "maier": {
    "en": "Tomas Maier",
    "ja": "トーマス・マイヤー",
    "bio": "1957年、ドイツ南西部のプフォルツハイム生まれ。父は建築家。シュタイナー教育の学校で学び、パリのクチュール組合の学校でファッションを学んだ。\n卒業後、Guy Laroche、Sonia Rykiel（ニット）、毛皮のRevillon、Hermès（約9年、ウィメンズのプレタポルテと革小物）で経験を積んだ。1997年、パートナーとともにフロリダで自身のブランド「Tomas Maier」を始め、リゾートウェアや水着を発表した。\n2001年、Gucciグループに買収されたBottega Venetaのクリエイティブディレクターに就任した。当時のBottega Venetaはロゴを多用した商品で迷走していたが、マイヤーはロゴを廃し、細い革を編む「イントレチャート」を前面に出し、「自分のイニシャルだけで十分なとき」という古い広告の言葉を掲げて、上質な素材と職人技を重んじる「静かなラグジュアリー」のブランドとして立て直した。イントレチャートのトート「カバ」（2001年）、結び目の形のクラッチ「ノット」などがヒットし、プレタポルテ、家具、ホテルの内装まで手がけ、17年間で売上を大きく伸ばした。2018年6月に退任した。"
  },
  "dlee": {
    "en": "Daniel Lee",
    "ja": "ダニエル・リー",
    "bio": "1986年、イングランドのブラッドフォードで、労働者階級の家庭に生まれた。セントラル・セント・マーチンズで学び、在学中にMaison Martin Margiela、Balenciaga（ニコラ・ジェスキエールのもと）でインターンを経験した。2011年に修士課程を修了したのち、ニューヨークのDonna Karanで働いた。\n2012年、Céline（フィービー・ファイロのもと）に入り、プレタポルテのディレクターを務めた。ファイロの知的なミニマリズムを内側から支え、その経験がのちの作風の土台になった。\n2018年7月、トーマス・マイヤーの後任としてBottega Venetaのクリエイティブディレクターに就任した。リーは、大きなイントレチャートの編み目、柔らかい革の巾着のようなクラッチ「ザ・ポーチ」（2019年）、ゴムのブーツ「パドル・ブーツ」、四角いトゥのサンダル、鮮やかな「ボッテガ・グリーン」などで、ブランドを一気に若い世代の憧れのブランドにした。2019年のブリティッシュ・ファッション・アワードで4部門を受賞した。2021年にはSNSのアカウントを削除し、ロンドンやデトロイトでの「Salon」と呼ぶショーを行った。\n2021年11月に突然退任し、2022年10月からBurberryのチーフ・クリエイティブ・オフィサーとして、英国の伝統（トレンチコート、チェック、騎士のロゴ）を再解釈している。",
    "mentors": [
      "philo",
      "ghesquiere"
    ]
  },
  "trotter": {
    "en": "Louise Trotter",
    "ja": "ルイーズ・トロッター",
    "bio": "1969年、イングランドのリーズ生まれ。ニューカッスルのノーサンブリア大学でファッションを学んだ。\n卒業後、アメリカでCalvin Klein、Tommy Hilfiger、Gapなどのデザインチームで経験を積み、イギリスに戻ってWhistles、Jaeger（クリエイティブディレクター）、ロンドンのJoseph（2014〜2018年、クリエイティブディレクター）などで活躍した。\n2018年、Lacoste初の女性クリエイティブディレクターに就任し、テニスのブランドを洗練された日常着として現代化した。2023年、フランスのCarvenのクリエイティブディレクターに就任した。\n2024年12月、Chanelへ移ったマチュー・ブレイジーの後任としてBottega Venetaのクリエイティブディレクターに指名され、2025年9月にミラノでデビューした。素材と職人技を重んじる、実用的で静かな服づくりで知られる。"
  },
  "osti": {
    "en": "Massimo Osti",
    "ja": "マッシモ・オスティ",
    "bio": "1944年、イタリアのボローニャ生まれ。グラフィックデザイナーとして広告の仕事をしていたが、Tシャツのプリントの仕事をきっかけに服の世界へ入った。\n1971年、C.P. Companyの前身となる「Chester Perry」を始めた（名前が商標の問題で「C.P. Company」に変わる）。オスティは、世界中の軍服やワークウェアを集めて研究し、その機能や構造を街の服に取り入れた。縫製後の服を染める「製品染め（ガーメントダイ）」の技術を発展させ、1988年には、自動車レース「ミッレミリア」のドライバーのために、フードにゴーグルを付けた「ミッレミリア・ジャケット（ゴーグル・ジャケット）」を作った。\n1982年、光の当たり方で色が変わる素材「タン・ドラーゴ」を使ったジャケットのシリーズとして「Stone Island」を生んだ。左腕のコンパスのバッジ、素材と加工の実験は、のちにイギリスのフットボールのサポーター文化（カジュアルズ）の象徴となった。\n1990年代にC.P. CompanyとStone Islandを離れ、Massimo Osti Productions、Left Hand、ST95などで素材の研究を続けた。2005年に死去。約5万点に及ぶ衣類と素材のアーカイブを残し、現在は息子のロレンツォらによって「Massimo Osti Studio」として公開・研究されている。"
  },
  "harvey": {
    "en": "Paul Harvey",
    "ja": "ポール・ハーヴェイ",
    "bio": "1960年頃、イングランド生まれ。セントラル・セント・マーチンズでファッションを学び、1980年代からミラノを拠点に、Enrico Coveriなどイタリアのブランドでデザイナーとして働いた。\n1996年、創設者マッシモ・オスティの後を継いでStone Islandのデザインを担当した。ハーヴェイは、オスティの素材研究の精神を受け継ぎ、温度によって色が変わる「アイス・ジャケット」、光を反射する素材、金属を織り込んだ素材、ラバーを塗った素材など、テクノロジーを使った実験的なアウターを次々に発表した。この時期のStone Islandは、ストリートやフットボールのファンだけでなくファッションの世界でも高く評価された。2008年に退任した。"
  },
  "rivetti": {
    "en": "Carlo Rivetti",
    "ja": "カルロ・リヴェッティ",
    "bio": "1956年、イタリア北部の繊維の町ビエッラで、繊維業を営む家に生まれた。1983年、家族の会社GFT（グルッポ・フィナンツィアリオ・テッシーレ）がC.P. CompanyとStone Islandの株式を取得し、リヴェッティはマッシモ・オスティとともにブランドを率いた。\n1993年、妹とともにStone Islandを引き継ぎ、オスティ退任後は、ポール・ハーヴェイのデザインを支えた。2008年以降は、外部のデザイナーではなく社内のデザインチームを自らが率いる体制で、クリエイティブ・ディレクションも担当した。素材と加工の研究開発を重視する姿勢を守り、Supreme、NikeLab、New Balanceとの協業などで若い世代にもブランドを広げた。2020年、Stone IslandをMonclerに売却し、その後もブランドに関わっている。"
  },
  "rowens": {
    "en": "Rick Owens",
    "ja": "リック・オウエンス",
    "bio": "1962年、カリフォルニア州の農業の町ポーターヴィル生まれ。父は社会福祉の仕事をする厳格なカトリック教徒で、保守的な家庭に育った。ロサンゼルスのオーティス美術大学で絵画を学んだが中退し、職業訓練校でパターンを学んだ。その後、量産服のブランドで高級ブランドの模倣品（ノックオフ）を作るパタンナーとして働いた。\n1994年、ロサンゼルスで自身のブランドを始めた。ハリウッドの古いホテルの部屋をアトリエにし、パートナーのミシェル・ラミー（のちに結婚）のレストラン兼ナイトクラブの周辺でボヘミアンな生活を送った。2002年、ヴォーグのアナ・ウィンターの支援を受けてニューヨーク・ファッションウィークでデビューした。\n2003年、フランスの毛皮の老舗Revillonのアーティスティックディレクターに就任してパリへ移り、以後パリを拠点にしている。オウエンスの服は、ゴシックでミニマル、グランジでありながら彫刻的なドレープ、長いシルエット、ラムレザーのライダースジャケット、大きく厚いスニーカー「ジオバスケット」などが特徴。自身では「グランジ」と「グラマー」を合わせて「グラウンジ（glunge）」と呼んだ。\nショーの演出も話題で、アメリカのステップダンスのチームを起用したショー（2014年春夏）、モデルが別のモデルを背負って歩くショー（2016年春夏）などが知られる。DRKSHDW、Lilies、家具（ミシェル・ラミーと）、adidasやVeja、Birkenstock、Moncler、Converseとの協業も多い。2017年にはミラノのトリエンナーレで回顧展が開かれた。"
  },
  "sander": {
    "en": "Jil Sander",
    "ja": "ジル・サンダー",
    "bio": "1943年、ドイツ北部のヴェッセルブレン生まれ（本名はハイデマリー・イリーネ・ザンダー）。クレーフェルトの繊維工学の学校で学び、アメリカのUCLAに交換留学生として渡った。その後、ハンブルクの女性誌『Constanze』『Petra』でファッションエディターとして働いた。\n1968年、24歳でハンブルクに自身のブティックを開き、他のブランドの服を売りながら、1973年に最初のウィメンズのコレクションを発表した。1975年のパリでのショーは不評に終わったが、1980年代にミラノで評価を高め、1989年に会社を株式上場した。1997年にはメンズも始めた。\nサンダーの服は、上質な素材（イタリアの機屋と開発したウールやカシミア）、無駄のない仕立て、白、黒、ネイビー、キャメルの静かな色で、仕事をする女性のための服として「ミニマリズムの女王」と呼ばれ、1990年代のファッションを代表した。香水やコスメでも成功した。\n1999年、Pradaグループが株式の75%を取得した。経営方針の違いから2000年に退任、2003年に復帰して2004年に再び退任、2012年に再び復帰して2013年に3度目の退任をした。2009年から2011年には、ユニクロとの協業「+J」でデザインを手がけ、上質なダウンジャケットやシャツが大ヒットした（2020年に再開）。2017年にはフランクフルトの応用美術館で大規模な展覧会が開かれた。"
  },
  "vukmirovic": {
    "en": "Milan Vukmirovic",
    "ja": "ミラン・ヴクミロヴィッチ",
    "bio": "1970年、パリ生まれのセルビア系フランス人。パリでファッションを学び、トム・フォードのもとでGucciのデザインチームに参加した。1997年には、パリで伝説的なセレクトショップ「colette」の共同創業者となり、バイヤーとしても知られた。\n2000年、創業者ジル・サンダーの退任を受けて、Jil Sanderのクリエイティブディレクターに就任し、2002年まで務めた。ミニマリズムの精神を受け継ぎながら、より若い感覚のデザインを試みた。\nその後は、雑誌『L'Officiel Hommes』の編集長、イタリアのTrussardiのクリエイティブディレクター（2008〜2010年頃）などを務め、雑誌『Fashion For Men』を創刊した。",
    "mentors": [
      "tomford"
    ]
  },
  "paglialunga": {
    "en": "Rodolfo Paglialunga",
    "ja": "ロドルフォ・パリアルンガ",
    "bio": "1960年頃、イタリア生まれ。Romeo Gigliのデザインチームで経験を積み、Pradaでウィメンズのデザインディレクターを務めた。\n2000年代後半、1930年代のバイアスカットで知られる老舗Vionnetのクリエイティブディレクターとして、ブランドの復活に関わり、マドレーヌ・ヴィオネのドレープの技術を現代的なドレスで再解釈した。\n2014年、ラフ・シモンズ、創業者ジル・サンダーの後を受けてJil Sanderのクリエイティブディレクターに就任した。ブランドのミニマリズムを守りつつ、より女性らしく柔らかなシルエットを加えたが、2017年に退任した。",
    "mentors": [
      "mprada"
    ]
  },
  "meier": {
    "en": "Lucie & Luke Meier",
    "ja": "ルーシー&ルーク・メイヤー",
    "bio": "ルーク・メイヤーは1977年カナダ生まれ。ニューヨークでスケートボードとストリートのカルチャーに親しみ、Supremeのヘッドデザイナーとして約8年働いた。2011年にはスイスのブランド「OAMC」を共同で始め、ミリタリーやワークウェアを上質な素材で作り直すメンズで評価された。\nルーシー・メイヤーは1982年スイス生まれ。ロンドンとパリでファッションを学び、Louis Vuitton、Balenciaga（ニコラ・ジェスキエールのもと）、Dior（ラフ・シモンズのもとでヘッド・オブ・デザイン）で経験を積んだ。\n夫婦は2017年、Jil Sanderの共同クリエイティブディレクターに就任した。ミニマリズムの静けさを保ちながら、手仕事のディテール、彫刻的なシルエット、詩的な雰囲気を加え、ブランドを再び評価の高いブランドにした。Arc'teryxとの協業なども話題になった。2025年2月のショーを最後に退任した。",
    "mentors": [
      "raf",
      "ghesquiere"
    ]
  },
  "bellotti": {
    "en": "Simone Bellotti",
    "ja": "シモーネ・ベロッティ",
    "bio": "1978年頃、イタリア生まれ。Dolce & Gabbanaで経験を積んだのち、Gucciで約9年間（アレッサンドロ・ミケーレの時代を含む）ウィメンズのデザインに関わった。\n2018年頃からBottega Venetaに移り、マチュー・ブレイジーの右腕としてデザインを支えた。2024年、スイスの靴と革の老舗Ballyのクリエイティブディレクターに就任し、ブランドを洗練させた。\n2025年3月、ルーシー&ルーク・メイヤーの後任としてJil Sanderのクリエイティブディレクターに就任した。同年9月のデビュー・コレクションでは、ラフ・シモンズの時代（2005〜2012）を思わせるグラフィックで純粋なミニマリズムを打ち出し、評価された。",
    "mentors": [
      "blazy"
    ]
  },
  "lang": {
    "en": "Helmut Lang",
    "ja": "ヘルムート・ラング",
    "bio": "1956年、オーストリアのウィーン生まれ。幼少期をアルプスの山村で祖父母と過ごし、のちにウィーンで父と継母のもとで育った。ファッションの専門教育は受けておらず、満足できるジャケットやTシャツが見つからないことから自分で服を作るようになった。\n1977年頃、ウィーンにブティックを開き、オーダーメイドの服を作り始めた。1986年、パリのポンピドゥー・センターでの「ウィーン1880〜1938」展に合わせてパリでデビューした。\nラングの服は、黒、白、グレーの無駄のない形に、工業的な素材（ゴム引きの生地、反射材、ビニール、プラスチック）、ボンデージを思わせるストラップ、絵の具を散らしたペインテッド・デニム、透ける素材などを持ち込み、「ミニマルだが冷たくない」と評された。1990年代のミニマリズムの象徴として、カルヴィン・クライン、ジル・サンダーと並び称され、多くのデザイナーに影響を与えた。\n1998年、拠点をニューヨークに移し、パリ・コレクションより前にショーを行ったことで、ニューヨーク・ファッションウィークの日程を変えるきっかけを作った。同年、ショーの代わりにコレクションをインターネットで配信し、CD-ROMで配布した先駆者でもある。タクシーの屋根に広告を出すなど、広告の手法も斬新だった。アーティストのジェニー・ホルツァー、ルイーズ・ブルジョワとの協働でも知られる。\n1999年、Pradaグループに株式の過半数を売却し、2005年にブランドを完全に離れた。その後は美術家として活動し、2010年頃には、保管していた約6,000点の自身の服のアーカイブを裁断して彫刻作品の素材にした。古着では、1990年代後半〜2005年のラング本人の時代（通称「ラング期」）のデニム、ボンデージ・ストラップ、ペイントのピース、ジャケットが非常に人気で、高値で取引される。"
  },
  "colovos": {
    "en": "Michael & Nicole Colovos",
    "ja": "マイケル&ニコール・コロヴォス",
    "bio": "マイケル・コロヴォスとニコール・コロヴォスは夫婦のデザイナー。マイケルはRalph LaurenやTommy Hilfigerなどで経験を積み、デニムブランド「Seven for All Mankind」の共同創業者となった。夫婦でカジュアルブランド「XCVI」なども手がけた。\n2006年、日本の会社リンク・セオリーがHelmut Langを買収したのち、2人がHelmut Langのクリエイティブディレクターに就任し、2014年まで務めた。ラングの時代の過激さよりも、上質な素材のシンプルなベーシック、レザー、ドレープのあるジャージーなど、日常的に着られるミニマルな服へと整えた。"
  },
  "peterdo": {
    "en": "Peter Do",
    "ja": "ピーター・ドゥ",
    "bio": "1990年、ベトナム生まれ。14歳のときに家族でアメリカのフィラデルフィアに移住した。ファッション工科大学（FIT）で学び、2014年にLVMHグラデュエイト・プライズを受賞した。\n卒業後、Céline（フィービー・ファイロのもと）でジュニアデザイナーとして働き、Derek Lamでも経験を積んだ。2018年、自身のブランド「Peter Do」を始め、テーラリングとドレープを組み合わせた知的でミニマルな服で注目された。2021年にはLVMHプライズのファイナリストに選ばれた。\n2023年、Helmut Langのクリエイティブディレクターに就任し、ニューヨーク・ファッションウィークでデビューした。ラングの時代を参照したシャープなテーラリングやテキストを使った服を発表したが、2024年に退任した。",
    "mentors": [
      "philo"
    ]
  },
  "thomascawson": {
    "en": "Mark Thomas & Thomas Cawson",
    "ja": "マーク・トーマス&トーマス・カウソン",
    "bio": "マーク・トーマスとトーマス・カウソンは、ロンドンを拠点にするデザイナー。2017年、Helmut Langはエディター・イン・レジデンスに雑誌『Dazed』の元編集長イザベラ・バーリーを迎え、ゲストデザイナーにHood By Airのシェイン・オリバーを起用するなど、新しい体制でブランドを立て直そうとした。\nその中で2018年頃、トーマスとカウソンがHelmut Langのクリエイティブチームとしてメンズとウィメンズのデザインを担当した。ラングのアーカイブを参照しつつ、より若い世代の感覚を取り入れた服を発表したが、ブランドは2020年代に入って体制を何度か変えた。"
  },
  "westwood": {
    "en": "Vivienne Westwood",
    "ja": "ヴィヴィアン・ウエストウッド",
    "bio": "1941年、イングランドのダービーシャー州ティンタウィッスル生まれ（本名ヴィヴィアン・イザベル・スワイヤー）。工場で働く労働者階級の家庭に育った。17歳で家族とロンドン郊外へ移り、ハーロウの美術学校で金細工を1学期学んだのち、小学校の教師となった。最初の夫デレク・ウエストウッドとの間に息子をもうけた。\n1965年頃、美術学生のマルコム・マクラーレンと出会い、1971年、2人でロンドンのキングス・ロード430番地に店「Let It Rock」を開き、1950年代のテディ・ボーイの服を売った。店名を「Too Fast to Live Too Young to Die」、1974年に「SEX」、1976年に「Seditionaries」と変えながら、ボンデージ・パンツ、安全ピンや破れたTシャツ、ナチスや反体制のスローガンをプリントしたTシャツなどでパンク・ファッションを作った。マクラーレンがマネージャーを務めたセックス・ピストルズの衣装も手がけた。\n1981年、ロンドンで最初の本格的なコレクション「Pirates」を発表し、海賊の服を着た新しいロマンティックなスタイルを作った。以後、ミニ・クリニ（短いクリノリン、1985年）、コルセット、ハリスツイード、タータン、18世紀の肖像画など、英国の歴史と伝統を引用し、皮肉とユーモアを込めて再解釈した。オーブ（宝珠と土星の輪）のロゴ、ロッキンホース・バレリーナ（厚底の靴）、アーマー・リング、ナオミ・キャンベルが転んだスーパー・エレベーテッド・ギリー（1993年）などが知られる。\n1992年にOBE、2006年にDBE（デイム）を受けた。夫のアンドレアス・クロンターラーとともに、晩年は気候変動や環境問題、言論の自由のための活動家としても知られた。2022年12月29日、ロンドンで81歳で死去した。古着では1980〜90年代のコルセット、ジャケット、オーブのジュエリー、Seditionaries期の服が非常に人気。"
  },
  "kronthaler": {
    "en": "Andreas Kronthaler",
    "ja": "アンドレアス・クロンターラー",
    "bio": "1966年、オーストリアのチロル州生まれ。ウィーン応用美術大学でファッションを学び、1989年、客員教授として教えていたヴィヴィアン・ウエストウッドと出会った。25歳の年の差を越えて1993年に結婚し、以来ヴィヴィアンのもっとも近い協力者として、デザインに深く関わった。\n2016年、ヴィヴィアンのメインラインを「Andreas Kronthaler for Vivienne Westwood」として引き継ぎ、パリで発表した。クロンターラーの服は、ヴィヴィアンの歴史の引用とパンクの精神を受け継ぎながら、より演劇的で、ジェンダーにとらわれない大胆なスタイルを打ち出している。2022年のヴィヴィアンの死後もブランドを率いている。",
    "mentors": [
      "westwood"
    ]
  },
  "mcgirr": {
    "en": "Seán McGirr",
    "ja": "ショーン・マクガー",
    "bio": "1988年、アイルランドのダブリン生まれ。ダブリンで学んだのち、ロンドンのセントラル・セント・マーチンズでメンズを学んだ。\n卒業後、Uniqlo（J.W. Andersonとの協業ライン）、Dries Van Noten、Burberryで経験を積み、2020年頃からJW Andersonのヘッド・オブ・プレタポルテとして、ジョナサン・アンダーソンのもとでメンズとウィメンズのデザインを担当した。\n2023年10月、サラ・バートンの後任としてAlexander McQueenのクリエイティブディレクターに就任した。マックイーンの暗いロマンティシズムとテーラリングを、若い世代のロンドンの感覚で再解釈しようとしたが、批評家の評価は分かれた。2026年10月に退任した。",
    "mentors": [
      "anderson"
    ]
  },
  "bailey": {
    "en": "Christopher Bailey",
    "ja": "クリストファー・ベイリー",
    "bio": "1971年、イングランドのヨークシャー州ハリファックス生まれ。父は大工、母はデパートのウィンドウ・ディスプレイの仕事をしていた。ウェストミンスター大学で学んだのち、ロイヤル・カレッジ・オブ・アートの修士課程を1994年に修了した。\n卒業後、ニューヨークのDonna Karanで働き、1996年からGucciでトム・フォードのもと、ウィメンズのシニアデザイナーを務めた。2001年、Burberryのデザインディレクターに就任した。\n当時のBurberryは、チェック柄が偽物とともに街にあふれ、品のないブランドというイメージに悩んでいた。ベイリーは、ブランドの原点であるトレンチコートを中心に、英国の伝統、音楽、若い俳優やモデル（エマ・ワトソン、カーラ・デルヴィーニュなど）の起用で、Burberryを英国を代表するラグジュアリーブランドとして再生させた。2009年にチーフ・クリエイティブ・オフィサー、2014年から2017年まではCEOも兼任した。ショーのライブ配信、見たらすぐ買える「See now, buy now」の導入など、デジタルの活用でも先駆的だった。2018年に退任した。",
    "mentors": [
      "tomford"
    ]
  },
  "vevers": {
    "en": "Stuart Vevers",
    "ja": "スチュアート・ヴィヴァース",
    "bio": "1973年、イングランドのドンカスター生まれ。ウェストミンスター大学でファッションを学んだ。\n卒業後、Calvin Klein、Givenchy、Bottega Veneta、Louis Vuitton（マーク・ジェイコブスのもとアクセサリー）で経験を積み、特にバッグや革小物のデザインで評価された。2005年頃、英国のレザーブランドMulberryのクリエイティブディレクターとして、大ヒットした「ベイズウォーター」などのバッグを手がけた。\n2007年から2013年までLoeweのクリエイティブディレクターを務め、スペインの革の老舗に若々しさを加えた。2013年、アメリカのCoachのエグゼクティブ・クリエイティブディレクターに就任し、ニューヨークの若者文化やアメリカの古き良き服を取り入れて、手頃なラグジュアリーとして再生させた。2020年代のCoachの「タビー」バッグの人気も彼の時代のもの。",
    "mentors": [
      "jacobs"
    ]
  },
  "mccollough": {
    "en": "Jack McCollough & Lazaro Hernandez",
    "ja": "ジャック・マッコロー&ラザロ・ヘルナンデス",
    "bio": "ジャック・マッコロー（1978年、東京で生まれ、ニュージャージー州で育つ）とラザロ・ヘルナンデス（1978年、マイアミでキューバ系の家庭に生まれる）は、ニューヨークのパーソンズ美術大学で出会った。在学中、マッコローはマーク・ジェイコブス、ヘルナンデスはマイケル・コースのもとでインターンを経験した。\n2002年、2人は卒業コレクションを共同で制作し、それぞれの母の旧姓（プロエンザとスクーラー）を組み合わせて「Proenza Schouler」と名付けた。このコレクションをニューヨークの百貨店Barneysが全点買い取り、同年ブランドを立ち上げた。2004年にCFDAのスワロフスキー新人賞を受賞し、その後もCFDAのウィメンズウェア・デザイナー・オブ・ザ・イヤーを何度も受賞した。\nProenza Schoulerは、アメリカらしいスポーティーさと、テクニカルな素材、アートやクラフトの要素を融合した服で知られ、2008年に発表した「PS1」バッグは大ヒットした。2018年には投資家とともに株式を買い戻し、経営の自由を取り戻した。\n2025年、ジョナサン・アンダーソンの後任としてLoeweのクリエイティブディレクターに就任し、2人で共同で率いている。Proenza Schoulerはレイチェル・スコットに託した。"
  },
  "nemeth": {
    "en": "Christopher Nemeth",
    "ja": "クリストファー・ネメス",
    "bio": "1959年、イングランドのバーミンガム生まれ。ロンドンのキャンバーウェル美術学校で絵画を学んだ。画家を目指していたが、画材を買う余裕がなく、郵便局の古い郵便袋のキャンバス地を使って服を作り始めた。手縫いの大きなステッチ、ロープ、ペンキで描いた模様、パズルのようなパターンの服は、1980年代のロンドンのクラブシーンで注目され、ケンジントン・マーケットや雑誌『i-D』、『The Face』で紹介された。\n1986年、東京で個展を開いたのをきっかけに、妻のケイコとともに東京に移住し、以後東京を拠点に活動した。東京・神宮前などに店を構え、日本のファンに長く支持された。ネメスの服は、工業製品の大量生産とは対極にある、一着ずつの手作りの温かさと、パンク以降のロンドンの反骨精神を持つ。ロープのモチーフ、手縫いのステッチ、一枚の布から作るパターンは、のちの多くの日本やアルチザン系のデザイナーに影響を与えた。\n2010年8月、東京で死去した。その後は妻と娘たちがブランドを引き継いでいる。古着では1990年代〜2000年代の手縫いの服やロープのジュエリーが国内外で高く評価されている。"
  },
  "poell": {
    "en": "Carol Christian Poell",
    "ja": "キャロル・クリスチャン・ポエル",
    "bio": "1966年、オーストリアのリンツ生まれ。祖父母が営む革なめし（タンナー）の家業の中で育ち、なめし職人の資格（Gerberlehre）を取った。ミラノのドムス・アカデミーでファッションデザインの修士課程を修了した。\n1995年、ミラノで自身のブランド「Carol Christian Poell」を始め、まずメンズを発表した。ポエルの服づくりは、素材と工程の徹底的な研究にある。縫い上げた服や靴を丸ごと染める製品染め（オブジェクトダイ）、服をゴムの液に浸して固める「ラバーディップ」、靴を一枚の革からつなぎ目なしで作る技術、腕や脚の動きを前提にした曲がったパターン、手術の縫合のような縫い目など、職人技術を極限まで追求する。カンガルー、馬、ヘラジカなど珍しい革も使う。\nショーをほとんど行わず、展示会や、モデルが川を流れていくパフォーマンス（2003年頃）など、謎めいた発表方法でも知られる。表舞台に出ないデザイナーで、写真もほとんど公開されていない。こうした姿勢と技術は、のちに「アルチザン系」と呼ばれる一群のブランドの始祖的な存在とされる。\n古着では、オブジェクトダイの靴、レザーのジャケット、ラバーディップのパンツなどが非常に高値で取引される。"
  },
  "rguidi": {
    "en": "Guidi family",
    "ja": "グイディ家",
    "bio": "Guidiは、1896年にイタリア・トスカーナ州のペスチャで、グイド・グイディとその仲間たちが始めたなめし革の工房（タンナー）を起源とする。トスカーナは昔から皮革産業が盛んな地域で、Guidiは植物タンニン（木の皮などから取る渋）で時間をかけてなめす伝統的な方法を守ってきた。\n20世紀後半からは、馬革、カンガルー革、牛革などを、一度なめしたあと製品にしてから染める「オブジェクトダイ」で、一点ごとに異なる色の濃淡や表情を生み出す技術で知られるようになった。1990年代以降、Carol Christian Poell、Carpe Diem、m.a+などアルチザン系ブランドに革を供給し、その素材の質の高さが評価された。\n2000年代からは、自社の靴とバッグのコレクションも展開し、背中にジッパーのある「988」のブーツ、ダービーシューズなどは、履き込むほど深い皺が刻まれ、アルチザン系の定番になった。創業家の血を引くルッジェーロ・グイディらが経営を続けている。"
  },
  "skelton": {
    "en": "John Alexander Skelton",
    "ja": "ジョン・アレクサンダー・スケルトン",
    "bio": "1980年代、イングランドのヨーク生まれ。ロンドンのセントラル・セント・マーチンズで学び、在学中にロレアルのプロフェッショナル賞を受賞した。\n卒業後、2012年頃からロンドンでメンズのブランドを始め、2016年に自身の名前を冠した「John Alexander Skelton」を立ち上げた。スケルトンの服は、19世紀の英国の労働者、農民、救貧院の人々の服、アイルランドの民族衣装、宗教的な衣服などを研究し、手縫い、天然染め（植物や泥）、古い布地、ホームスパンの生地を使って、ゆっくりと少量で作られる。ボタンや金具も古いものを探して使う。\nコレクションは毎回、詩や歴史、個人的な記憶にもとづいた物語を持ち、ロンドンの古い教会や建物で発表される。ファストファッションと対極にある、時間をかけた服づくりは、アルチザン系の新しい世代を代表するものとして、日本を含む世界のファンに支持されている。"
  },
  "kumagai": {
    "en": "Kazuyuki Kumagai",
    "ja": "熊谷和幸",
    "bio": "1960年代生まれ。ファッションの専門学校を卒業後、イッセイ ミヤケに入社し、5年間在籍してパターンと素材の研究を学んだ。\n1999年、自身のブランド「ATTACHMENT（アタッチメント）」を設立した。日本の産地（尾州のウール、遠州の綿、児島のデニムなど）の機屋と開発したオリジナルの素材を使い、細身で緻密なパターン、黒やグレー、ネイビーを中心にした静かな色のメンズで評価された。2005年からは本人の名前を冠した「KAZUYUKI KUMAGAI」も展開し、より実験的でアルチザン系に近い、製品染めや加工を施した服を発表した。\n2022年春夏を最後にATTACHMENTのデザイナーを退任し、ブランドはVEINの榎本光希に引き継がれた。熊谷は2023年秋冬から新しいブランド「calmlence（カームレンス）」を始めている。古着では、2000年代のKAZUYUKI KUMAGAIのレザーやジャケットが人気。",
    "mentors": [
      "miyake"
    ]
  },
  "enomoto": {
    "en": "Koki Enomoto",
    "ja": "榎本光希",
    "bio": "1980年代生まれ。日本でファッションを学び、熊谷和幸が率いるATTACHMENTのデザインチームで経験を積んだ。ATTACHMENTの、日本の産地の素材と緻密なパターンを重んじる服づくりを内側から学んだデザイナーの一人。\n自身のブランド「VEIN（ヴェイン）」のデザイナーとして、上質な素材と落ち着いた色、細部にこだわったメンズを発表していた。2022年、熊谷の退任を受けて、2022-23年秋冬からATTACHMENTのデザイナーを引き継いだ。ブランドの静かなミニマリズムを守りつつ、新しい世代の感覚を加えている。",
    "mentors": [
      "kumagai"
    ]
  },
  "bikkembergs": {
    "en": "Dirk Bikkembergs",
    "ja": "ダーク・ビッケンバーグ",
    "bio": "1959年、ドイツのケルン近郊でベルギー人の家庭に生まれ、ドイツで育った。アントワープ王立芸術アカデミーのファッション科で学び、1982年に卒業した。\n1985年、メンズの靴のコレクションから自身のブランドを始め、1986年には服も発表した。同年、ロンドンのブリティッシュ・デザイナー・ショーで「アントワープ・シックス」の一人として注目された。ビッケンバーグの服は、軍隊式の重いブーツ、筋肉質でたくましい男性像、スポーツの要素で知られた。靴の底に穴をあけ、ひもを靴底に通す独特のブーツは、1980〜90年代のアントワープの象徴だった。\n1990年代後半からはサッカーとハイファッションを結びつける試みを進め、2000年代にはスタジアムでショーを行い、イタリアのサッカーチームのインテル・ミラノのユニフォームのデザインも手がけた。サッカー選手をモデルにした広告でも知られた。2000年代末にブランドを売却し、現在はファッションの世界から引退している。古着では1990年代のブーツとメンズの服が人気。"
  },
  "amadei": {
    "en": "Maurizio Amadei",
    "ja": "マウリツィオ・アマデイ",
    "bio": "1960年代、イタリア生まれ。若い頃から革の仕事に携わり、職人としての技術を身につけた。1990年代後半、マウリツィオ・アルティエリが始めたCarpe Diemに参加し、レザーのジャケットや靴、バッグのデザインと制作を担当した。\n2006年、自身のブランド「m.a+（Maurizio Amadei）」を設立した。アマデイの服と小物は、一枚の革から最小限の縫い目で作る構造、Guidiなどの上質な馬革やカンガルー革、製品染めによる深い色、鍵やジッパーなど金具の独自のデザインが特徴。特に、つなぎ目の少ないバックパックやバッグ、ストイックな靴は高く評価されている。\nCarol Christian PoellやCarpe Diemと並び、アルチザン系を代表するブランドの一つとして、日本を含む世界のファンに長く支持されている。",
    "mentors": [
      "altieri"
    ]
  },
  "altieri": {
    "en": "Maurizio Altieri",
    "ja": "マウリツィオ・アルティエリ",
    "bio": "1960年代、イタリア生まれ。若い頃からロックや革の文化に親しみ、アメリカのChrome Heartsのイタリアでの仕事などに関わったとされる。\n1996年、イタリアで「Carpe Diem（ラテン語で「その日をつかめ」）」を設立した。アルティエリは、縫い上げた服を染める製品染め、手作業の縫製、継ぎ目や縫い代を見せる構造、重くて頑丈なレザーのブーツなどで、職人的で無骨な美しさを打ち出した。Carol Christian Poellと並び、1990年代末から2000年代の「アルチザン系」と呼ばれる流れを作った重要人物の一人。のちにm.a+を始めるマウリツィオ・アマデイもCarpe Diemでレザーを担当していた。\n2006年頃にCarpe Diemを離れ、新しいブランド「m_moria」を始めた。古着では、アルティエリ期のCarpe Diemのブーツやレザーのジャケットが非常に高値で取引される。"
  },
  "saberi": {
    "en": "Boris Bidjan Saberi",
    "ja": "ボリス・ビジャン・サベリ",
    "bio": "1978年、スペインのバルセロナで、ドイツ人の母とペルシャ（イラン）人の父のもとに生まれた。若い頃はヒップホップやスケートボード、武道に親しんだ。ドイツでテーラリングを学び、ベルリンでの修業ののち、2006年にバルセロナで服飾の学業を修了した。\n2007年、自身のブランド「Boris Bidjan Saberi」を始め、2010年代からはパリで発表した。サベリの服は、テーラリングの技術、製品染めや手作業の加工、立体的なパターン、ストリートや武道の動きやすさを融合させたテクニカルな服で知られる。バルセロナの自社工房で、染めや加工を含めて多くの工程を行う。\n「11 by Boris Bidjan Saberi」というセカンドラインや、Salomonとの協業スニーカーでも人気を集めた。アルチザン系の新しい世代を代表するデザイナーとして評価されたが、2025年に活動の区切りを発表した。"
  },
  "harnden": {
    "en": "Paul Harnden",
    "ja": "ポール・ハーンデン",
    "bio": "1960年代、カナダのトロント生まれ。若い頃にイギリスへ渡り、1985年頃にイングランド南部のブライトンに移って、伝統的な手縫いの靴づくりを職人から学んだ。\n1987年、ブライトン近郊に自身の工房「Paul Harnden Shoemakers」を開き、手縫いの靴を作り始めた。のちに、19世紀の作業着や農民の服、古い軍服をもとにした服も作るようになった。ハーンデンの服と靴は、ウールやリネン、革などの素材を、ほとんど手作業でゆっくりと仕立て、古びたような、使い込まれたような風合いを持つ。\nハーンデンは、広告を出さず、ウェブサイトも持たず、インタビューにもほとんど応じない。ごく限られた店（日本の一部のセレクトショップなど）でしか扱われず、その存在自体が神秘的な、アルチザン系の中でも特別なブランドとされる。ポール・トーマス・アンダーソン監督の映画『ゼア・ウィル・ビー・ブラッド』（2007年）では、主演のダニエル・デイ＝ルイスのためのブーツを手がけた。"
  },
  "blanck": {
    "en": "Leon Emanuel Blanck",
    "ja": "レオン・エマニュエル・ブランク",
    "bio": "1990年代、ドイツ生まれ。10代の頃からファッションに強い関心を持ち、ほぼ独学で服づくりとパターンを学んだ。\n2012年、ドイツのハイデルベルクで自身のブランド「Leon Emanuel Blanck」を始めた。ブランクの服は、いったん服を分解して組み立て直したような構造、製品染めや加工による深い色と質感、手作業の縫製、身体に沿う立体的なパターンで知られ、Carol Christian Poellの流れを汲むアルチザン系の若い世代の代表とされる。\nコレクションは「Distortion」などのテーマでまとめられ、パリで展示会を行っている。日本や海外のアルチザン系のファンから高い評価を受けている。"
  },
  "cecchetto": {
    "en": "Simone Cecchetto",
    "ja": "シモーネ・チェケット",
    "bio": "イタリア出身。ほぼ独学で靴づくりを学び、職人のもとで技術を身につけた。リック・オウエンスの靴の仕事にも関わった経験があるとされる。\n2006年、ローマで靴のブランド「A Diciannoveventitre（A1923）」を始めた。名前は「1923」を意味するイタリア語。チェケットの靴は、手縫いで継ぎ目の少ない構造、なめし革の質感を生かした造形、製品染めの深い色が特徴で、アルチザン系の靴として知られる。のちに「Augusta」などのラインも展開した。",
    "mentors": [
      "rowens"
    ]
  },
  "martinerose": {
    "en": "Martine Rose",
    "ja": "マーティン・ローズ",
    "bio": "1980年、ロンドン生まれ。ジャマイカ系の家庭に育ち、南ロンドンのクラブカルチャー、レイヴ、レゲエやヒップホップ、グライムなどの音楽に強く影響を受けた。レイヴンズボーン大学でファッションを学んだ。\n2007年、友人とともにシャツのブランド「LEGEND」を始め、その後自身の名前を冠した「Martine Rose」を立ち上げた。ローズの服は、ロンドンのクラブ、サブカルチャー、サッカーのファン、ありふれた中年男性の服（くたびれたスーツ、ウインドブレーカー、ポロシャツ）を、肩を極端に大きくしたり、丈をずらしたりする誇張したサイズ感と、少しずれた着方で表現する。ロンドンの市場や郊外の駐車場などでショーを行うことでも知られる。\n2015年頃から2018年頃まで、デムナのもとでBalenciagaのメンズのコンサルタントを務め、Balenciagaの大きなシルエットにも影響を与えたとされる。NIKEとの協業（Shox MRなど）、Napapijriとの協業でも人気を集めた。\n2026年11月、ピエールパオロ・ピッチョーリの後任としてBalenciagaのクリエイティブディレクターに就任した。"
  },
  "gianniversace": {
    "en": "Gianni Versace",
    "ja": "ジャンニ・ヴェルサーチ",
    "bio": "1946年、イタリア南部カラブリア州のレッジョ・カラブリア生まれ。母フランチェスカは仕立て屋を営み、ジャンニは幼い頃から母の工房で布や型紙に囲まれて育った。建築を学んだのち、母の仕事を手伝った。\n1972年、ミラノに移り、Complice、Genny、Callaghanなどのブランドでデザイナーとして成功した。1978年、兄のサントとともに自身のブランド「Versace」を設立した。妹のドナテラも若い頃から協力した。\nヴェルサーチの服は、ギリシャ神話のメドゥーサのロゴ、バロックの金の柄、鮮やかなプリント、金属を織り込んだメタルメッシュ、身体を強調するボディコンシャスなシルエットで、1980〜90年代の華やかさと官能を象徴した。1991年秋冬のショーで、ナオミ・キャンベル、シンディ・クロフォード、リンダ・エヴァンジェリスタ、クリスティ・ターリントンらを並べて歩かせ、「スーパーモデル」の時代を作った。エリザベス・ハーレーの安全ピンのドレス（1994年）、ダイアナ妃、エルトン・ジョン、マドンナら有名人との親交でも知られる。オペラやバレエの衣装も数多く手がけた。\n1997年7月15日、マイアミの自宅の前で連続殺人犯に射殺された。50歳だった。古着では1990年代のバロック柄のシャツ、デニム、メタルメッシュの服が非常に人気。"
  },
  "donatella": {
    "en": "Donatella Versace",
    "ja": "ドナテラ・ヴェルサーチ",
    "bio": "1955年、イタリアのレッジョ・カラブリア生まれ。兄ジャンニより9歳年下で、兄に可愛がられて育った。フィレンツェ大学で外国語を学んだのち、兄のブランドに加わり、ミューズとして、またアクセサリーや広告、若い世代向けのセカンドライン「Versus」を担当した。\n1997年、ジャンニが殺害されたあと、Versaceのクリエイティブディレクターに就任した。悲しみの中で大きな責任を負い、最初は批評家から厳しい評価も受けたが、兄の官能的で華やかなスタイルを自分なりに受け継ぎ、約28年間ブランドを率いた。2000年のグラミー賞でジェニファー・ロペスが着たジャングル・プリントのドレスは、Googleの画像検索を作るきっかけになったといわれる。2017年には兄の没後20年のトリビュート・ショーで、1990年代のスーパーモデルたちを再び集めて話題になった。\n2018年、VersaceはMichael Kors（のちのCapri Holdings）に売却された。2025年3月、クリエイティブディレクターを退き、チーフ・ブランド・アンバサダーに就任した。同年、VersaceはPradaグループに売却された。トレードマークのプラチナブロンドの髪と日焼けした肌でも知られる。"
  },
  "vitale": {
    "en": "Dario Vitale",
    "ja": "ダリオ・ヴィターレ",
    "bio": "1983年頃、イタリアのナポリ生まれ。Dolce & Gabbana、Bottega Venetaで経験を積んだ。\n2010年頃からMiu Miuに参加し、約14年間、デザインとイメージのディレクターとしてミウッチャ・プラダのもとで働いた。2022年春夏のマイクロミニのスカートなど、Miu Miuが「最も話題のブランド」となった時期を支えた一人とされる。\n2025年3月、ドナテラ・ヴェルサーチの後任として、Versaceのチーフクリエイティブオフィサーに就任し、2025年9月にデビューした。しかし、PradaグループによるVersaceの買収が完了した直後の2025年12月に退任した。2026年9月、Emporio Armaniのクリエイティブディレクターに就任した。",
    "mentors": [
      "mprada"
    ]
  },
  "mulier": {
    "en": "Pieter Mulier",
    "ja": "ピーター・ミュリエ",
    "bio": "1978年、ベルギーのブルージュ生まれ。ブリュッセルのサン・リュック建築学校で建築を学んだ。卒業後、ラフ・シモンズのメンズのチームに加わり、以後約20年間、ラフの右腕として働いた。\nラフがJil Sander（2005〜2012）、Dior（2012〜2015）、Calvin Klein（2016〜2018）のクリエイティブディレクターを務めた際には、それぞれのブランドでデザインディレクターやクリエイティブディレクター補佐として、ラフの考えを形にする中心的な役割を担った。映画『ディオールと私』にも登場する。\n2021年、創業者アズディン・アライアの死後に空席だったAlaïaのクリエイティブディレクターに就任した。ミュリエは、身体に沿うニットやレザー、構築的なシルエットというアライアの技術を受け継ぎながら、より現代的で彫刻的な服を作り、ブランドを再び最も注目されるブランドの一つにした。バレエシューズや「ル・クール」バッグなどのヒットも生んだ。\n2026年7月、Versaceのチーフクリエイティブオフィサーに就任した。",
    "mentors": [
      "raf"
    ]
  },
  "alaia": {
    "en": "Azzedine Alaïa",
    "ja": "アズディン・アライア",
    "bio": "1935年（1939年とする資料もある）、チュニジアのチュニスで、小麦農家の家に生まれた。双子の姉がいた。チュニスの美術学校で彫刻を学び、学費を稼ぐために洋裁店で働いた。\n1957年、パリに移り、Christian Diorで5日間だけ働いた（アルジェリア戦争の影響で解雇されたという）。その後、ギ・ラロッシュのもとで2年間働き、ティエリー・ミュグレーのもとでも働いた。ブレジエ伯爵夫人の家に住み込み、上流の女性たちのために服を仕立てた。\n1980年、自身のプレタポルテのコレクションを発表した。アライアの服は、伸縮するニットやジャージーで身体にぴったり沿わせる「ボディコン」、レーザーカットで穴をあけたレザー、身体の線を美しく見せる精密なパターンで、1980年代に「キング・オブ・クリング（ぴったりの王様）」と呼ばれた。グレース・ジョーンズ、ナオミ・キャンベル（「娘」と呼んだ）、マドンナらを顧客に持った。\nアライアはファッションウィークの日程に縛られず、服の準備ができたときにだけ発表し、パリの自宅兼アトリエで少人数に見せた。2007年にリシュモンの傘下に入った。2017年11月、パリで死去した。死後、パリに「アズディン・アライア財団」が設立された。"
  },
  "valentinog": {
    "en": "Valentino Garavani",
    "ja": "ヴァレンティノ・ガラヴァーニ",
    "bio": "1932年、イタリア北部のヴォゲーラで生まれた。父は電気資材の商売をしていた。10代でファッションに興味を持ち、17歳でパリに渡ってパリ・クチュール組合の学校とエコール・デ・ボザールで学んだ。\nパリでジャン・デセのもとで約5年、ギ・ラロッシュのもとで約2年働いたのち、1959年、ローマのコンドッティ通りに自身のアトリエを開いた。1960年、建築学生だったジャンカルロ・ジャンメッティと出会い、以後50年近く、公私にわたるパートナーとして、ジャンメッティが経営を、ヴァレンティノがデザインを担った。\n1962年、フィレンツェのピッティ宮殿での発表で大成功を収め、国際的に知られるようになった。ヴァレンティノの服は、深く鮮やかな赤「ヴァレンティノ・レッド」、繊細な刺繍、レース、リボン、ドレープのドレスで知られ、イタリアのエレガンスを代表した。1968年の白一色の「ホワイト・コレクション」では、Vの金具を初めて使った。ジャクリーン・ケネディ（オナシスとの結婚式のドレスを担当）、エリザベス・テイラー、オードリー・ヘプバーン、ジュリア・ロバーツ（2001年のアカデミー賞のドレス）ら数多くの著名人に愛された。\n2008年1月、パリでのクチュールのショーを最後に引退した。同年、ドキュメンタリー『ヴァレンティノ：ザ・ラスト・エンペラー』が公開された。2026年1月19日、ローマの自宅で93歳で死去した。"
  },
  "silviafendi": {
    "en": "Silvia Venturini Fendi",
    "ja": "シルヴィア・ヴェントゥリーニ・フェンディ",
    "bio": "1960年、ローマ生まれ。1925年にFendiを創業したアデーレとエドアルド・フェンディの孫で、5人姉妹の一人アンナ・フェンディの娘。子どもの頃からFendiのアトリエで、カール・ラガーフェルドの仕事を間近に見て育った。\n1987年頃からFendiの若い世代向けのライン「Fendissime」を手がけ、1994年からはアクセサリーとメンズのアーティスティックディレクターを務めた。1997年、小脇に抱えるフランスパンのような小さなバッグ「バゲット」をデザインし、ドラマ『セックス・アンド・ザ・シティ』で主人公キャリーが持ったことで世界的なヒットとなり、最初の「イットバッグ」と呼ばれた。モンスターの顔のバッグ「バッグ・バグズ」（2013年）なども生んだ。\n2019年のラガーフェルドの死後はウィメンズも担当し、2020年から2024年まではキム・ジョーンズとともにFendiを率いた。その後も創業家の一員としてブランドに関わっている。"
  },
  "pbalmain": {
    "en": "Pierre Balmain",
    "ja": "ピエール・バルマン",
    "bio": "1914年、フランス南東部のサン＝ジャン＝ド＝モーリエンヌ生まれ。父は服地の卸売業を営んでいたが早くに亡くなり、母とおばが営むブティックで育った。パリのエコール・デ・ボザールで建築を学んだが、ファッションのスケッチを描くうちにエドワード・モリヌーに見いだされ、その店で働いた。\n1939年からリュシアン・ルロンのもとで働き、同僚のクリスチャン・ディオールとともに、いつか2人で店を開こうと語り合ったという。1945年、パリのフランソワ1世通りに自身のメゾンを開いた。\nバルマンの服は、細いウエストと豊かなスカート、上質な素材と刺繍で、「ジョリー・マダム（可愛い淑女）」と呼ばれる優雅な女らしさを打ち出した。1947年のディオールのニュールックに先立つシルエットを示したともいわれる。女優のキャサリン・ヘプバーン、ブリジット・バルドー、ソフィア・ローレン、タイ王妃シリキットなど、王族や映画スターを顧客にし、舞台や映画の衣装も数多く手がけた。1982年に死去した。"
  },
  "decarnin": {
    "en": "Christophe Decarnin",
    "ja": "クリストフ・デカルナン",
    "bio": "1964年、フランス生まれ。パリのファッションの学校で学んだのち、Paco Rabanneで約10年、デザイナーとして働いた。\n2005年、Balmainのクリエイティブディレクターに就任した。当時のBalmainは低迷していたが、デカルナンは、肩を極端に強調したジャケット、軍服のような金ボタンのジャケット、スパンコールや刺繍の短いドレス、破れたデニムやスタッズなど、ロックで攻撃的な女性像を打ち出した。2009年頃の「パワーショルダー」の流行はBalmainから始まったとされ、ブランドの人気は一気に回復した。一方で、ダメージ加工のジーンズやジャケットは非常に高価で、議論も呼んだ。\n2011年、体調を崩して退任し、後任は彼のチームにいた25歳のオリヴィエ・ルスタンだった。"
  },
  "rousteing": {
    "en": "Olivier Rousteing",
    "ja": "オリヴィエ・ルスタン",
    "bio": "1985年、フランスのボルドー生まれ。生まれてすぐに孤児院に預けられ、1歳のときに白人の夫婦に養子として迎えられた。のちに、実の母がソマリアとエチオピアにルーツを持つ10代の少女だったことを知った。ボルドーで法律を学んだのち、パリのファッションの学校ESMODに進んだが、短期間で中退した。\nイタリアに渡り、Roberto Cavalliで約5年間、ウィメンズのデザインを担当した。2009年、クリストフ・デカルナンのもとでBalmainに入り、2011年、デカルナンの退任を受けて25歳でBalmainのクリエイティブディレクターに抜擢された。\nルスタンは、デカルナンの強い肩とビーズ刺繍の装飾を受け継ぎながら、カーダシアン家、ビヨンセ、リアーナ、ジジ・ハディッドら有名人を起用した「Balmain Army」、インスタグラムを使った発信で、SNS時代の新しいラグジュアリーのあり方を示した。多様な人種のモデルの起用、2015年のH&Mとの協業（発売日に行列と混乱）でも知られる。2020年には、自宅の暖炉の事故で大やけどを負ったことを公表した。\n2025年に約14年率いたBalmainを退任し、2026年7月からRabanneのクリエイティブディレクターを務めている。",
    "mentors": [
      "decarnin"
    ]
  },
  "tron": {
    "en": "Antonin Tron",
    "ja": "アントナン・トロン",
    "bio": "1980年代、フランス生まれ。ベルギーのアントワープ王立芸術アカデミーでファッションを学んだ。\n卒業後、Louis Vuitton、Balenciaga（ニコラ・ジェスキエール、アレキサンダー・ワンのもと）で、ウィメンズのデザインを担当した。2016年、自身のレーベル「Atlein（アトライン）」を始めた。名前は大西洋（Atlantic）にちなむとされる。トロンは、ジャージー素材のドレープ、身体の動きに沿う流れるようなシルエット、余った生地の活用など、エレガントで実用的な服を作り、のちにANDAM賞を受賞し、LVMHプライズのファイナリストにも選ばれた。\n2025年、オリヴィエ・ルスタンの後任としてBalmainのクリエイティブディレクターに就任した。",
    "mentors": [
      "ghesquiere"
    ]
  },
  "jlanvin": {
    "en": "Jeanne Lanvin",
    "ja": "ジャンヌ・ランバン",
    "bio": "1867年、パリで11人きょうだいの長女として生まれた。家は貧しく、13歳で帽子屋の見習いとして働き始め、仕立ての技術も身につけた。\n1889年、パリのフォーブル・サントノレ通りで自身の帽子店を開いた。1897年に一人娘マルグリットを産み、彼女のために作った美しい子ども服が上流の女性たちの評判になり、子ども服、そして母と娘の服へと事業が広がった。Lanvinのロゴの、母と娘が手を取り合うイラストは、この関係を描いたもの（イラストはポール・イリーブ）。\nランバンは、ルネサンスの絵画から着想した青「ランバン・ブルー」、ビーズや刺繍の繊細な装飾、ゆったりした「ローブ・ド・スティル」のドレスで、1920年代のパリを代表するクチュリエの一人となった。1920年代には、インテリア、メンズ、スポーツウェア、香水「アルページュ」（1927年、娘の30歳の誕生日に捧げた）まで手がけ、ライフスタイル全体を提案した先駆けでもあった。1946年に死去した。Lanvinは、現存するパリのクチュールのメゾンの中で最も古いものの一つとされる。"
  },
  "elbaz": {
    "en": "Alber Elbaz",
    "ja": "アルベール・エルバス",
    "bio": "1961年、モロッコのカサブランカで、ユダヤ系の家庭に生まれた。10歳のときに家族でイスラエルに移住し、テルアビブで育った。父は理容師で、早くに亡くなった。テルアビブのシェンカー・カレッジでファッションを学んだ。\n1980年代半ばにニューヨークに渡り、アメリカのデザイナー、ジェフリー・ビーンのもとで約7年間働いた。1996年、パリのGuy Larocheのデザイナーとなり、1998年、イヴ・サンローランに見いだされてYves Saint Laurent Rive Gaucheのウィメンズのデザイナーに就任した。しかし翌年、GucciグループのYSL買収とトム・フォードの就任により、3シーズンで解任された。イタリアのKriziaを経て、2001年にLanvinのアーティスティックディレクターに就任した。\nエルバスのLanvinは、ドレープ、リボン、むき出しのファスナー、未処理の裾、柔らかいサテンやタフタで、女性を優しく包む美しいドレスを作り、低迷していた老舗を再生させた。眼鏡と蝶ネクタイ、丸い体型の愛らしい姿でも親しまれ、2010年にはH&Mとの協業も行った。2015年、経営陣との対立で解任された。\n2021年1月、リシュモンと組んで新しいブランド「AZ Factory」を立ち上げたが、同年4月、新型コロナウイルス感染症のため59歳で死去した。"
  },
  "sialelli": {
    "en": "Bruno Sialelli",
    "ja": "ブルーノ・シアレッリ",
    "bio": "フランス出身。パリでファッションを学び、Balenciaga（アレキサンダー・ワンのもと）、Paco Rabanne、Loewe（ジョナサン・アンダーソンのもとでメンズのデザイン）で経験を積んだ。\n2019年、Lanvinのクリエイティブディレクターに就任した。創業者ジャンヌ・ランバンのアーカイブや、漫画『タンタンの冒険』とのコラボレーションなど、遊び心のある服でブランドを若返らせようとしたが、2023年に退任した。",
    "mentors": [
      "anderson"
    ]
  },
  "copping": {
    "en": "Peter Copping",
    "ja": "ピーター・コッピング",
    "bio": "1967年、イングランド生まれ。セントラル・セント・マーチンズ、ロイヤル・カレッジ・オブ・アートで学んだ。\n卒業後、パリのSonia Rykielで経験を積み、1997年頃からLouis Vuittonでマーク・ジェイコブスのもと、ウィメンズのデザインを約12年間担当した。2009年、Nina Ricciのクリエイティブディレクターに就任し、繊細なレースや花柄の女性らしいドレスでブランドを洗練させた。2015年からはアメリカのOscar de la Rentaのクリエイティブディレクターを務めた。\n2023年、Balenciagaでデムナとともにオートクチュールのアドバイザーとして働いたのち、2024年、Lanvinのアーティスティックディレクターに就任した。クチュールの技術と英国的な品の良さで、Lanvinのエレガンスを取り戻そうとしている。",
    "mentors": [
      "jacobs"
    ]
  },
  "kenzotakada": {
    "en": "Kenzo Takada",
    "ja": "高田賢三",
    "bio": "1939年、兵庫県姫路市で、待合（料亭）を営む家に生まれた。姉たちの読む少女雑誌で服に興味を持ち、神戸市外国語大学を中退して、1958年に文化服装学院に男子学生の第一期生として入学した。同級生にはコシノジュンコ、松田光弘らがいた。1961年に新人デザイナーの登竜門である装苑賞を受賞し、百貨店の三愛で働いた。\n1964年、東京オリンピックのための再開発でアパートを立ち退くことになり、その補償金で船でパリへ渡った。デザイン画を売りながら働き、1970年、パリのギャラリー・ヴィヴィエンヌに小さなブティック「ジャングル・ジャップ」を開いた。資金がなかったため、市場で買った安い布を組み合わせた服を作り、壁にはアンリ・ルソーの絵のようなジャングルを描いた。\n高田の服は、色と柄を大胆に重ね、民族衣装（日本の着物、中国、インド、北欧、南米）を自由に混ぜた、ゆったりと動きやすいシルエットで、当時の窮屈なパリのモードに新しい風を吹き込み、雑誌『ELLE』の表紙を飾った。日本人デザイナーがパリで成功する道を最初に切り開いた人物の一人とされる。1976年にブランド名を「KENZO」に変え、1983年にメンズ、1988年に香水を始めた。\n1993年にブランドをLVMHに売却し、1999年に引退した。その後は画家や、インテリアブランド「K-3」などで活動した。2020年10月4日、新型コロナウイルス感染症のためパリ近郊で81歳で死去した。"
  },
  "marras": {
    "en": "Antonio Marras",
    "ja": "アントニオ・マラス",
    "bio": "1961年、イタリア・サルデーニャ島のアルゲーロ生まれ。父は服地店を営んでいた。ファッションの正式な教育は受けず、独学で服づくりを学んだ。\n1988年頃からローマの会社でデザイナーとして働き、1996年、ローマで自身の名前でオートクチュールのようなコレクションを発表し、1999年からミラノでプレタポルテを発表した。マラスの服は、故郷サルデーニャの伝統、古い布や刺繍、レースを重ね合わせ、詩的で手仕事の温かさのある作風で知られる。\n2003年、高田賢三の引退後のKenzoのウィメンズのアーティスティックディレクターに就任し、2008年からはメンズも含むブランド全体を率いて、2011年まで務めた。現在は自身のブランドに専念し、美術家としても活動している。"
  },
  "limleon": {
    "en": "Carol Lim & Humberto Leon",
    "ja": "キャロル・リム&ウンベルト・レオン",
    "bio": "キャロル・リム（1975年頃、カリフォルニア州生まれ、韓国系）とウンベルト・レオン（1975年頃、カリフォルニア州生まれ、中国系とペルー系）は、カリフォルニア大学バークレー校で出会った。卒業後、それぞれ小売やファッションの企業で働いた。\n2002年、2人はニューヨークのダウンタウンにセレクトショップ「Opening Ceremony」を開いた。毎年ひとつの国を選んでその国のデザイナーを紹介する方式、Chloë Sevigny、Spike Jonzeらとの協業、若手デザイナーの発掘で、2000年代のニューヨークのファッションの中心の一つになった。\n2011年、Kenzoのクリエイティブディレクターに就任した。虎の顔の刺繍のスウェット、目のモチーフ、カラフルなプリント、デヴィッド・リンチやスパイク・ジョーンズら映画監督との協業の映像で、Kenzoを若い世代の人気ブランドにした。2019年に退任した。Opening Ceremonyは2020年に店舗を閉じた。"
  },
  "baptista": {
    "en": "Felipe Oliveira Baptista",
    "ja": "フェリペ・オリヴェイラ・バプティスタ",
    "bio": "1975年、ポルトガルのリスボン近郊生まれ。ロンドンのキングストン大学でファッションを学んだ。卒業後、イタリアやパリでデザイナーとして働いた。\n2002年、パリで妻のセヴリーヌ・オリヴェイラ・バプティスタとともに自身のブランドを始め、2003年にイエール国際モード&写真フェスティバルでグランプリを受賞した。実用的で建築的な服で評価され、パリのオートクチュール連盟のゲストメンバーとしてクチュールも発表した。\n2010年から2018年まではLacosteのクリエイティブディレクターとして、テニスのポロシャツのブランドを洗練させた。2019年、Kenzoのクリエイティブディレクターに就任し、自然や環境への関心をテーマにしたコレクションを発表したが、2021年に退任した。"
  },
  "aghion": {
    "en": "Gaby Aghion",
    "ja": "ギャビー・アギョン",
    "bio": "1921年、エジプトのアレクサンドリアで、裕福なユダヤ系の家庭に生まれた（本名ガブリエル・アナカ）。幼なじみのレイモン・アギョンと結婚し、1945年、パリに移った。\n当時のパリでは、上質な服はオートクチュール（注文服）だけで、既製服は質の低いものとされていた。アギョンは、クチュールの技術と素材で作る上質な既製服が必要だと考え、1952年に「Chloé」を創業した。名前は友人の名前から取った。これは「高級プレタポルテ（リュクス・プレタポルテ）」の先駆けとされる。1956年には、パリのカフェ・ド・フロールで最初のショーを開いた。\nアギョンは、若いデザイナーを積極的に起用し、ジェラール・ピパール、カール・ラガーフェルド（1964年頃から）らに服をデザインさせた。この方針は、のちのステラ・マッカートニー、フィービー・ファイロらにも続く、Chloéの伝統となった。1985年にブランドを売却し、2014年に死去した。"
  },
  "stellamccartney": {
    "en": "Stella McCartney",
    "ja": "ステラ・マッカートニー",
    "bio": "1971年、ロンドン生まれ。ビートルズのポール・マッカートニーと写真家リンダ・マッカートニーの娘。両親の方針で菜食主義の家庭に育った。15歳でクリスチャン・ラクロワのもとで働き、サヴィル・ロウのテーラーで仕立てを学んだ。\nセントラル・セント・マーチンズを1995年に卒業し、卒業コレクションのショーには友人のナオミ・キャンベルやケイト・モスが出演した。1997年、25歳でカール・ラガーフェルドの後任としてChloéのクリエイティブディレクターに就任し、ランジェリーのような繊細な服、ヴィンテージ風のTシャツなどで若い女性に大人気となった。\n2001年、Gucciグループと共同で自身のブランド「Stella McCartney」を始めた。毛皮や革を一切使わず、環境への負荷の少ない素材を使う「サステナブルなラグジュアリー」をいち早く掲げ、業界に大きな影響を与えた。2004年からadidasとのスポーツウェアのラインを続け、オリンピックの英国代表のユニフォームもデザインした。2018年、メーガン・マークルの結婚式の夜のドレスも手がけた。2019年にはLVMHと提携した。"
  },
  "macgibbon": {
    "en": "Hannah MacGibbon",
    "ja": "ハンナ・マクギボン",
    "bio": "イングランド出身。セントラル・セント・マーチンズで学んだ。卒業後、ローマのValentinoで働き、2001年からChloéでフィービー・ファイロのもとでデザインディレクターを務めた。ファイロのボヘミアンで若々しいChloéを支えた一人。\n2008年、Chloéのクリエイティブディレクターに就任した。マクギボンは、ベージュやキャメル、白などの落ち着いた色、ゆったりしたパンツや大きなコートで、1970年代のChloéを思わせる、静かで大人っぽい服を作った。批評家からは評価されたが、2011年に退任した。",
    "mentors": [
      "philo"
    ]
  },
  "ramsaylevi": {
    "en": "Natacha Ramsay-Levi",
    "ja": "ナターシャ・ラムゼイ＝レヴィ",
    "bio": "1980年、パリ生まれ。パリのスタジオ・ベルソーでファッションを学んだ。\n2002年からBalenciagaでニコラ・ジェスキエールのもとで働き、2013年にはジェスキエールとともにLouis Vuittonに移って、ウィメンズのクリエイティブ・ディレクションを支えた。約15年にわたるジェスキエールの右腕だった。\n2017年、クレア・ワイト・ケラーの後任としてChloéのクリエイティブディレクターに就任した。ラムゼイ＝レヴィは、ボヘミアンなChloéに、より知的で力強い、ユニセックスな要素とアートの要素を持ち込んだ。2020年に退任した。",
    "mentors": [
      "ghesquiere"
    ]
  },
  "hearst": {
    "en": "Gabriela Hearst",
    "ja": "ガブリエラ・ハースト",
    "bio": "1976年、ウルグアイのパイサンドゥで、牧場を営む家に生まれた。牧場の暮らしの中で、羊毛や革など素材の大切さを学んだ。ニューヨークで演劇を学び、モデルとしても活動したのち、2004年頃にファッションの道へ進んだ。2011年、アメリカの新聞王ハーストの家系のオースティン・ハーストと結婚した。\n2015年、自身のブランド「Gabriela Hearst」を始めた。上質な素材、手仕事、長く着られる服、余った生地の再利用など、サステナブルなラグジュアリーを掲げ、ニット、テーラリング、バッグ（「ナイナ」バッグは予約待ちになった）で評価された。ショーの二酸化炭素排出量をゼロにする試みも行った。\n2020年、Chloéのクリエイティブディレクターに就任し、Chloéを「Bコープ」認証を受けた初のラグジュアリーブランドにするなど、環境への配慮を推し進めた。2023年に退任し、自身のブランドに専念している。"
  },
  "kamali": {
    "en": "Chemena Kamali",
    "ja": "シェメナ・カマリ",
    "bio": "1981年、ドイツ生まれ（イラン系の父とドイツ人の母）。ドイツのトリーア大学でファッションデザインを学んだ。在学中からChloéの1970年代の服に憧れていた。\n2007年にChloéのデザインチームに入り、のちにクレア・ワイト・ケラーのもとでデザインディレクターを務めた。その後、Saint Laurentでアンソニー・ヴァカレロのもと、ウィメンズのデザインディレクター（2016〜2023年）を務めた。\n2023年10月、ガブリエラ・ハーストの後任としてChloéのクリエイティブディレクターに就任し、2024年2月にデビューした。透けるブラウス、フリル、ブーツ、ゆったりしたシルエットなど、1970年代のボヘミアンで自由なChloéらしさを取り戻したと高く評価され、「ボーホー・シック」の再流行を作った。",
    "mentors": [
      "vaccarello",
      "waightkeller"
    ]
  },
  "dossena": {
    "en": "Julien Dossena",
    "ja": "ジュリアン・ドッセーナ",
    "bio": "1982年、フランス・ブルターニュ地方生まれ。スイスのジュネーブ造形芸術大学（HEAD）でファッションを学んだ。\n卒業後、Balenciagaでニコラ・ジェスキエールのもと、ウィメンズのデザインを担当し、未来的なシルエットと素材の実験を間近で学んだ。2013年、Paco Rabanneのクリエイティブディレクターに就任した。\n当時のPaco Rabanneは、1960年代の金属のディスクのドレスの記憶だけが残る、ほぼ忘れられたブランドだった。ドッセーナは、金属のメッシュやディスクのドレスを、1970年代風のプリントや、日常で着られるシャツやニットと組み合わせ、現代的なブランドとして再生させた。2019年、ブランド名を「Rabanne」に変えた。2022年にはH&Mとの協業も行い、2023年からはJean Paul Gaultierのクチュールのゲストも務めた。2026年に約13年率いたRabanneを退任した。",
    "mentors": [
      "ghesquiere"
    ]
  },
  "tmugler": {
    "en": "Thierry Mugler",
    "ja": "ティエリー・ミュグレー",
    "bio": "1948年、フランスのストラスブール生まれ。父は医師。14歳からストラスブールのオペラ座のバレエ団でダンサーとして踊りながら、ストラスブールの美術学校で学び、自分の服を作っていた。\n20歳でパリに出て、ショーウィンドウの装飾やフリーのデザイナーとして働いたのち、1973年に「Café de Paris」の名でコレクションを発表し、1974年に自身の名前のブランドを始めた（1973年とする資料もある）。\nミュグレーの服は、極端に強調した肩と絞ったウエスト、昆虫やロボット、車のボディを思わせる金属やビニールのボディースーツ、ハリウッドの女優やSFのヒロインのような力強い女性像で、1980〜90年代のファッションを代表した。ショーそのものも、数千人の観客を集めた1984年の10周年のショーなど、演劇やコンサートのような大スペクタクルだった。1992年の香水「エンジェル」は、甘いグルマン系の香りの先駆けとして大ヒットした。写真家としても自身の広告を撮影した。\n2002年に服づくりを離れ、その後は名前をマンフレッド・ティエリー・ミュグレーに改め、ボディビルで身体を作り変えた。ビヨンセのツアー衣装（2009年）などを手がけた。2019年からはモントリオールの美術館で大規模な回顧展「Thierry Mugler: Couturissime」が世界を巡回した。2022年1月、73歳で死去した。古着では1980〜90年代の構築的なジャケットやスーツが非常に人気。"
  },
  "formichetti": {
    "en": "Nicola Formichetti",
    "ja": "ニコラ・フォルミケッティ",
    "bio": "1977年、日本人の母とイタリア人の父のもとに生まれ、東京とローマで育った。建築を学ぶためにロンドンに渡ったが、ロンドンのセレクトショップ「The Pineal Eye」でバイヤーとして働き、ファッションの道に進んだ。\nスタイリストとして雑誌『Dazed & Confused』のファッション・ディレクター、日本の『Vogue Hommes Japan』などで活躍し、レディー・ガガのファッション・ディレクターとして、生肉のドレス（2010年）などの衣装で一躍有名になった。ユニクロのファッション・ディレクターも務めた。\n2010年、Muglerのクリエイティブディレクターに就任し、レディー・ガガや全身にタトゥーを入れたモデル「ゾンビボーイ」を起用した話題のショーで注目を集めたが、2013年に退任した。その後はDieselのアーティスティックディレクター（2013〜2018年頃）を務め、自身のブランド「Nicopanda」も手がけた。"
  },
  "cadwallader": {
    "en": "Casey Cadwallader",
    "ja": "ケイシー・キャドワラダー",
    "bio": "1980年頃、アメリカ生まれ。コーネル大学で建築を学んだのち、ファッションの道に進んだ。\nニューヨークのNarciso Rodriguezでデザインを担当したのち、Loewe（ジョナサン・アンダーソンが就任する前）、Acne Studiosのデザインディレクターなどで経験を積んだ。\n2017年、Muglerのクリエイティブディレクターに就任した。キャドワラダーは、創業者ティエリー・ミュグレーの身体を強調する構築的なシルエットを、伸縮するメッシュのボディースーツ、レギンス、カットアウトのドレスとして現代化した。ベラ・ハディッドやドージャ・キャット、ビヨンセらが着用し、コロナ禍にはショーの代わりに凝った映像作品でコレクションを発表して、SNS時代のMuglerを作った。2025年に退任した。"
  },
  "castrofreitas": {
    "en": "Miguel Castro Freitas",
    "ja": "ミゲル・カストロ・フレイタス",
    "bio": "ポルトガル出身。ロンドンのセントラル・セント・マーチンズでファッションを学んだ。\n卒業後、パリのメゾンでデザイナーとして経験を積み、DiorやSaint Laurent（アンソニー・ヴァカレロのもと）などで、デザインチームの重要な役割を担ったとされる。\n2025年、ケイシー・キャドワラダーの後任としてMuglerのクリエイティブディレクターに就任した。創業者の構築的で大胆な女性像を、新しい世代の感覚でどう引き継ぐかが注目されている。",
    "mentors": [
      "vaccarello"
    ]
  },
  "craiggreen": {
    "en": "Craig Green",
    "ja": "クレイグ・グリーン",
    "bio": "1986年、イングランド生まれ。セントラル・セント・マーチンズで学び、2012年に修士課程を修了した。\n同年、ロンドン・コレクションの新人育成の枠「Fashion East」でデビューした。最初のコレクションでは、モデルの顔を木の枠で覆う彫刻的な装飾が話題になり、観客の中には涙を流す人もいたという。\nクレイグ・グリーンの服は、キルティングされた作業着、ストラップやひもで身体に結びつける構造、旗や凧、帆のような大きな布、木枠の彫刻的な装飾などで、宗教的な儀式、制服、救命具を思わせる独特のメンズを作る。穏やかな色のワークジャケットやパンツは、日常着としても人気。\nブリティッシュ・ファッション・アワードのメンズウェア・デザイナー・オブ・ザ・イヤーを何度も受賞した。Moncler Geniusの一員としてのアウター、adidasとのスニーカー、Champion、Levi'sなどとの協業も知られる。"
  },
  "kiko": {
    "en": "Kiko Kostadinov",
    "ja": "キコ・コスタディノフ",
    "bio": "1988年、ブルガリアのソフィア生まれ。16歳でイギリスに移住し、ロンドンで暮らしながらファッションに興味を持った。セントラル・セント・マーチンズで学び、在学中の2014年、Stüssyとのカプセル・コレクションを手がけて注目された。\n2016年、修士課程を修了し、自身のブランド「Kiko Kostadinov」を始めた。コスタディノフの服は、作業着、制服、スポーツウェアのディテールを、何層にも切り替えた複雑なパターンで組み替え、機能的でありながら未来的なメンズを作る。2018年からは、双子のデザイナー、ローラとディアナ・フェルナーとともにウィメンズも手がけている。\nASICSとの協業スニーカー（GEL-KIRIGAMI、GEL-DELVA など）は大ヒットし、スニーカーのデザインの新しい流れを作った。2017年から約2年、Mackintoshの0001ラインのクリエイティブディレクターも務めた。Camperとの協業なども知られる。"
  },
  "guram": {
    "en": "Guram Gvasalia",
    "ja": "グラム・ヴァザリア",
    "bio": "1985年頃、ジョージア生まれ。デムナの弟。兄と同じく、アブハジア紛争で家族とともに難民となった経験を持つ。ビジネスと法律を学んだ。\n2014年、兄デムナや友人たちとパリで「Vetements」を共同で設立し、CEOとして経営を担った。ファッションウィークの日程にとらわれない発表や、生産量を絞る販売戦略など、Vetementsの型破りなビジネスモデルを作った。2019年、デムナがBalenciagaに専念するためにVetementsを離れたのちもブランドを率い、拠点をスイスのチューリッヒに移した。\n2021年12月、Vetementsのクリエイティブディレクターに就任し、デザインも自ら手がけるようになった。2020年代には、ロシアのウクライナ侵攻に抗議するメッセージなど、政治的な発信も続けている。"
  },
  "ibkamara": {
    "en": "Ib Kamara",
    "ja": "イブ・カマラ",
    "bio": "1990年、シエラレオネのフリータウン生まれ。内戦の中で育ち、10代のときにロンドンへ移住した。セントラル・セント・マーチンズでファッション・コミュニケーションを学んだ。\n在学中からスタイリストとして活動し、雑誌『i-D』『Dazed』『Arena Homme+』などで、アフリカの文化とストリート、ジェンダーの境界を越える大胆なスタイリングで注目された。Burberry、Off-Whiteなどのキャンペーンも手がけ、2021年には雑誌『Dazed』のエディター・イン・チーフに就任した。\nヴァージル・アブローとは親しい友人で、アブローの死後、2022年にOff-Whiteのアート&イメージディレクターに就任し、のちにクリエイティブディレクターとしてブランドを率いた。アブローの精神を受け継ぎながら、より身体的で彫刻的なコレクションを発表したが、2026年に退任した。"
  },
  "wvb": {
    "en": "Walter Van Beirendonck",
    "ja": "ウォルター・ヴァン・ベイレンドンク",
    "bio": "1957年、ベルギーのブレヘト生まれ。アントワープ王立芸術アカデミーのファッション科で学び、1980年に卒業した。在学中にダーク・ヴァン・セーヌと出会い、以後長年のパートナーとなった。\n1983年に自身のブランドを始め、1986年にロンドンのブリティッシュ・デザイナー・ショーで「アントワープ・シックス」の一人として注目された。ヴァン・ベイレンドンクの服は、鮮やかな色、ポップなプリント、ユーモアと性的・政治的なメッセージ、SFやサイバー、エイズの時代の安全な性、民族衣装やコミックの引用などで、アントワープ・シックスの中でも最もカラフルで過激な存在だった。\n1990年代にはドイツのジーンズの会社と組んで「W.&L.T.（Wild and Lethal Trash）」を展開し、未来的でポップな服が大ヒットした。U2の「PopMart」ツアー（1997年）の衣装も手がけた。\n1985年からアントワープ王立芸術アカデミーで教え、2007年から2022年まではファッション科の学科長として、デムナ、グレン・マーティンスら多くのデザイナーを育てた。古着では、1990年代のW.&L.T.の服が非常に人気。"
  },
  "chalayan": {
    "en": "Hussein Chalayan",
    "ja": "フセイン・チャラヤン",
    "bio": "1970年、キプロスのニコシアで、トルコ系キプロス人の家庭に生まれた。キプロス紛争の中で育ち、12歳のときに父とともにロンドンへ移住した。セントラル・セント・マーチンズで学び、1993年に卒業した。卒業コレクション「The Tangent Flows」では、鉄粉と一緒に庭に埋めて数週間後に掘り出した、錆びて朽ちた服を発表し、ロンドンのブティック「Browns」がそのまま買い取った。\n1994年、自身のブランドを始めた。チャラヤンの服は、建築、哲学、テクノロジー、移民や国境、宗教、身体をテーマにしたコンセプチュアルな作品で知られる。紙でできた封筒のようなドレス「エアメール・ドレス」（1999年）、リモコンで形が変わる樹脂のドレス（2000年春夏「Before Minus Now」）、居間の椅子のカバーがドレスになり、テーブルがスカートになる「Afterwords」（2000年秋冬、難民が家財を持って逃げる姿を表現）、LEDやレーザーを組み込んだドレス（2007年）などは、ファッションの境界を広げた作品として美術館に収蔵されている。\n1999年と2000年にBritish Designer of the Yearを受賞した。TSE（ニット、1998〜2001年）、Asprey、Pumaのクリエイティブディレクター、Vionnetのデミ・クチュールなども手がけた。映像作家・美術家としても活動し、2005年にはヴェネツィア・ビエンナーレのトルコ館代表となった。2006年にMBEを受けた。"
  },
  "jebbia": {
    "en": "James Jebbia",
    "ja": "ジェームス・ジェビア",
    "bio": "1963年、アメリカ生まれ。幼い頃にイギリスに移り、イングランドで育った。19歳でニューヨークに戻った。\n1983年頃、ソーホーの古着とストリートの店「Union NYC」で働き、のちに店の運営に関わった。1991年、ショーン・ステューシーの依頼でStüssyのニューヨーク店の立ち上げと運営を担当した。\n1994年4月、ニューヨークのラファイエット・ストリートに「Supreme」を開いた。スケートボーダーが店の中まで滑り込めるよう、売り場を広く開けた店づくりで、スケーターのための店として始まった。ロゴは、アーティストのバーバラ・クルーガーの作品から着想した赤い箱に白い文字（ボックスロゴ）。\nジェビアは、写真家、アーティスト（KAWS、村上隆、ジェフ・クーンズ）、ミュージシャン、ブランド（The North Face、NIKE、COMME des GARÇONS SHIRT、Louis Vuitton）との協業、少量生産と毎週木曜日の限定販売で、Supremeを世界的なストリートブランドに育てた。2017年のLouis Vuittonとの協業は、ストリートとラグジュアリーの融合の象徴となった。\n2020年にSupremeをVFコーポレーション（The North Faceなどの親会社）に約21億ドルで売却し、2024年にはEssilorLuxotticaに移ったが、引き続きブランドを率いている。"
  },
  "shawnstussy": {
    "en": "Shawn Stussy",
    "ja": "ショーン・ステューシー",
    "bio": "1954年、カリフォルニア州生まれ。カリフォルニアのラグーナビーチでサーフィンに親しみ、10代からサーフボードを削る職人として働いた。自分で削ったボードに、太いマーカーで書いた独特の手書きのサイン「Stüssy」を入れていた（このサインは、おじのサインをまねたものだという）。\n1980年頃、このサインをTシャツやショーツに刷って、サーフボードと一緒に売り始めたのがStüssyの始まり。1984年、会計士のフランク・シナトラJr.（歌手とは別人）とともに会社を設立した。\nステューシーは、サーフ、スケートボード、ヒップホップ、レゲエ、パンク、ニューウェーブなど、異なるストリートのカルチャーを一つのブランドの中に混ぜた。東京（藤原ヒロシ、NIGOら）、ロンドン、ニューヨークのDJやクリエイターの仲間たちを「International Stüssy Tribe（IST）」と呼び、彼らに限定のジャケットを配ったことで、世界中の街にネットワークを広げた。これは、今日のストリートウェアの原型とされる。\n1996年、ブランドを離れて引退し、家族と過ごした。その後、2000年代に日本で「S/Double」を始め、近年は自身の名前で、家具やサーフボードなども手がけている。古着では、1980〜90年代の「オールドステューシー」のTシャツやジャケットが非常に人気。"
  },
  "stark": {
    "en": "Richard Stark",
    "ja": "リチャード・スターク",
    "bio": "アメリカ出身。若い頃からバイクに乗り、バイク用のレザーウェアを作る仕事をしていた。\n1988年、友人のジョン・バウマン、レナード・カムホートとともにロサンゼルスで「Chrome Hearts」を創業した。最初は、バイク乗りのための丈夫なレザーのジャケットやパンツを作り、その金具として、銀で作ったゴシックな十字架や短剣、花のモチーフのパーツをつけた。この銀のパーツが評判を呼び、純銀（スターリングシルバー）のジュエリーのブランドとして世界的に知られるようになった。\nクロムハーツは、すべての製品をロサンゼルスの自社の工房で職人が手作業で作り、広告をほとんど出さず、限られた直営店でのみ販売する。この姿勢が、ロックスター（キース・リチャーズ、レニー・クラヴィッツら）やハリウッドの俳優、ヒップホップのアーティスト（カニエ・ウェスト、ドレイク）に愛される理由となった。1994年以降は妻のローリー・リン・スタークとともに経営し、家具やアイウェア、香水まで展開している。娘のジェシー・ジョー・スタークもブランドに関わる。\n古着では、1990年代〜2000年代のシルバーのリングやペンダント、レザーのパンツやジャケットが非常に高値で取引される。"
  },
  "kansai": {
    "en": "Kansai Yamamoto",
    "ja": "山本寛斎",
    "bio": "1944年、神奈川県横浜市生まれ。日本大学の英文科を中退し、服飾の道に進んだ。デザイナーのコシノジュンコ、細野久のもとでアシスタントとして修業した。\n1971年、日本人として初めてロンドンでファッションショーを開き、「KANSAI YAMAMOTO」として世界的に注目された。山本寛斎の服は、歌舞伎、浮世絵、武者絵、祭り、火消しの半纏など日本の伝統文化を、原色の強い色、大胆な柄、立体的でボリュームのあるシルエットで表現したもの。西洋のモードにはない「派手さ」と「力強さ」で、ロンドンやパリ、ニューヨークのコレクションでも発表した。\nデヴィッド・ボウイがジギー・スターダストのツアー（1972〜73年）で着た、縞模様のジャンプスーツや、歌舞伎の早変わりの手法を取り入れた衣装は、ロックの歴史に残る衣装となった。1974年には東京でもショーを始めた。\n1990年代以降は、服のコレクションよりも、数万人の観客を集める大規模なイベント「KANSAI SUPER SHOW」（モスクワの赤の広場、ベトナム、インドなど）のプロデューサーとして活躍し、「元気」を届けることをテーマにした。娘は女優の山本未來。2020年7月21日、急性骨髄性白血病のため76歳で死去した。近年、ボウイの衣装やアーカイブが海外で再評価され、美術館の展覧会でも紹介されている。"
  },
  "yamashita": {
    "en": "Takao Yamashita",
    "ja": "山下隆生",
    "bio": "1960年代生まれ。ファッションの専門学校には通わず、独学で服づくりとパターンを学んだ。\n1990年、東京で「beauty:beast」の前身となるブランドを始めた。山下の服は、日本のアニメやキャラクター、ポップカルチャー、SFのイメージを大胆にグラフィックとして使い、パッチワークや再構築、異素材の組み合わせと合わせた、1990年代の東京らしい自由で遊び心のあるもの。アニメとハイファッションを結びつけた先駆者とされる。\nbeauty:beastは、1990年代の東京のストリートとモードの境界で、雑誌や若者に熱心に支持され、パリでも展示会を行った。1990年代の日本のブランドへの関心が高まる中で、近年は海外のアーカイブ・コレクターからも再評価され、当時の服が高値で取引されている。"
  },
  "tsumura": {
    "en": "Kosuke Tsumura",
    "ja": "津村耕佑",
    "bio": "1959年生まれ。ファッションを学んだのち、1983年に三宅デザイン事務所に入社し、三宅一生のもとでISSEY MIYAKEのパリ・コレクションの服づくりを担当した。\n1994年、三宅デザイン事務所の中で、自身のブランド「FINAL HOME」を始めた。FINAL HOMEのコンセプトは、「家を失ったときに、最後に頼れる家としての服」。代表作のナイロンのコートは、全面にたくさんのポケットがあり、新聞紙や緩衝材を詰めると防寒具になり、食料や救急用品を入れればサバイバル用品になる。不要になったら、ポケットに詰め物を入れて寄付することも提案された。\n1995年の阪神・淡路大震災や、都市生活、ホームレスの問題を考えさせる社会的なメッセージと、透けるナイロンのポップで未来的な見た目で、1990年代の東京で大人気となった。津村は、ファッションを通じて社会や災害について考えさせる活動を続け、2015年に独立したのちは、文化学園大学などで教えている。古着では、1990年代のFINAL HOMEのナイロンのコートが国内外で人気。",
    "mentors": [
      "miyake"
    ]
  },
  "nakagawa": {
    "en": "Masahiro Nakagawa & LICA",
    "ja": "中川正博&LICA",
    "bio": "中川正博とLICAのデュオ。1992年、東京で「20471120（トゥエンティフォーセブンイレブントゥエンティ）」を始めた。ブランド名は「2047年11月20日」という未来の日付から取られ、未来に向けた服を作るという思いを込めたものといわれる。\n20471120は、1990年代の東京のストリートとモードの境界で、ポップでコンセプチュアルな服、遊び心のあるグラフィック、ユーモアのある演出で注目を集めた。東京のファッションウィークだけでなく、パリでもショーを行い、海外のプレスにも紹介された。\n1990年代の東京ファッションを代表するブランドの一つとして、近年、海外のアーカイブ・コレクターから再評価が進み、当時の服が高値で取引されている。"
  },
  "obana": {
    "en": "Daisuke Obana",
    "ja": "尾花大輔",
    "bio": "1974年生まれ。古着が好きで、1995年、東京の古着店「go-getter」の立ち上げに関わり、バイヤーとしてアメリカで古着の仕入れを担当した。この経験で、アメリカの軍服やワークウェア、古着の構造や縫製を深く学んだ。\n2000年、東京・原宿に自身の店「ミスターハリウッド」を開き、2001年、ブランド「N.HOOLYWOOD」を設立した。尾花の服は、古着や軍服、ワークウェアを徹底的に研究し、そのディテールや構造を現代的なサイズ感とシルエットに落とし込んだメンズで知られる。毎シーズン、アメリカの歴史や人物、風景をテーマにする。2002年から東京でショーを行い、2010年頃からニューヨーク・ファッションウィークで発表している。Champion、Wrangler、Wildthingsなどとの協業も多い。"
  },
  "shimizu": {
    "en": "Keizo Shimizu",
    "ja": "清水慶三",
    "bio": "1960年代生まれ。アメリカの古着やワークウェア、アウトドアの服に早くから魅了され、1988年、仲間とともに東京でセレクトショップ「NEPENTHES（ネペンテス）」を創業した。アメリカの古き良きワークウェアや、日本ではまだ知られていなかったブランドを紹介し、1990年代の東京のアメカジ、ワークウェアのブームに大きな影響を与えた。\n1995年、オリジナルのブランド「NEEDLES（ニードルズ）」を始めた。清水の服は、アメリカの古着やワークウェア、ミリタリーを独自に解釈し、刺繍やパッチワーク、民族的な要素を加えたもの。蝶（パピヨン）の刺繍のついたトラックパンツやトラックジャケットは、NEEDLESの代名詞となった。古着のフランネルシャツなどを7枚の布に切り分けて組み合わせ直すリメイク「Rebuild by Needles」も人気。\nネペンテスの系列には、ニューヨークで鈴木大器が始めたEngineered Garments、South2 West8などのブランドがある。古着好き、アメリカの服好きの間で長く支持されている。"
  },
  "mori": {
    "en": "Atsuhiko Mori",
    "ja": "森敦彦",
    "bio": "元Jリーガー。プロのサッカー選手として活躍したのち、引退してファッションの道へ進んだ。\n2005年、同じく元Jリーガーでガンバ大阪などで活躍した石塚啓次とともに「WACKO MARIA（ワコマリア）」を設立した。東京・中目黒の店「PARADISE TOKYO」を拠点にしている。\nWACKO MARIAの世界観は、アウトローで色気のある、大人の不良の服。ハワイアンシャツ（アロハシャツ）、レゲエやジャズ、ソウル、ロックなどの音楽、映画、裸の女性やタトゥー、宗教的なモチーフのグラフィックを、上質な素材で作る。特に、映画やアーティストとのコラボレーションのアロハシャツは毎シーズン人気を集める。\n音楽への愛も深く、ジャズや映画のレコードやポスターのアートワークとのコラボ、ミュージシャンとの協業も多い。国内外で人気を集め、海外にも店舗を広げている。"
  },
  "furuta": {
    "en": "Yasuko Furuta",
    "ja": "古田泰子",
    "bio": "1970年代生まれ。文化服装学院を卒業後、舞台などの衣装の仕事を経て、1997年に「TOGA（トーガ）」を始めた。\n古田の服は、異なる素材の組み合わせ、ウエスタンのディテール（ウエスタンブーツ、メタルのパーツ、フリンジ）、ヴィンテージの要素、透ける素材を、少しずらしたバランスで使い、強くて少し奇妙な女性像を作る。\n2006年からパリ・コレクションに参加し、2011年頃からはロンドン・コレクションで発表している。メンズの「TOGA VIRILIS」、セカンドラインの「TOGA PULLA」、靴やアクセサリーも人気。ウエスタンブーツやメタルのバックルのベルト、サンダルは定番となった。H&M、Dickiesなどとの協業でも知られる。"
  },
  "kurogouchi": {
    "en": "Maiko Kurogouchi",
    "ja": "黒河内真衣子",
    "bio": "1985年、長野県生まれ。文化ファッション大学院大学を修了し、三宅デザイン事務所に入社して、ISSEY MIYAKEのデザインに3年ほど携わった。\n2010年、自身のブランド「Mame Kurogouchi（マメ クロゴウチ）」を始めた。「Mame」は子どもの頃からのあだ名。黒河内の服は、日本の工芸や手仕事、竹籠や陶器、着物の文様、故郷の長野の自然、身近な風景や記憶から着想した、繊細で詩的なもの。レースや刺繍、透ける素材、立体的な織りを重ね、日本の産地の職人と開発した素材を多く使う。\n2016年に毎日ファッション大賞の新人賞・資生堂奨励賞を受賞した。2018年からパリ・コレクションで発表している。ユニクロとの協業（2022年頃〜）では、インナーやニットが大ヒットした。日本を代表する若手デザイナーの一人として国際的に評価されている。",
    "mentors": [
      "miyake"
    ]
  },
  "morinaga": {
    "en": "Kunihiko Morinaga",
    "ja": "森永邦彦",
    "bio": "1980年、東京生まれ。早稲田大学社会科学部在学中に、バンタンデザイン研究所の夜間部で服づくりを学び、師事した神田恵介の影響を受けた。2003年、「ANREALAGE（アンリアレイジ）」を始めた。名前は、「A REAL（日常）」「UN REAL（非日常）」「AGE（時代）」を組み合わせたもの。\n初期は、細かい布のパッチワークの服で知られたが、2010年代からは、テクノロジーと服の関係を問うコンセプチュアルなコレクションで注目された。人体ではなく球体や三角錐に合わせて服を作る「〇△□」（2009年）、極小と極大のサイズの服、光に当たると色が変わるフォトクロミック素材の服、カメラのフラッシュで模様が浮かぶ服、デジタルとファッションを結びつける試みなど。\n2014年からパリ・コレクションに参加し、2019年にLVMHプライズのファイナリストとなった。2021年にはFendiとの協業。ドラマや映画の衣装、アーティストとの協業も多い。"
  },
  "ino": {
    "en": "Masayuki Ino",
    "ja": "井野将之",
    "bio": "1980年、群馬県生まれ。専門学校でファッションを学んだのち、靴と服のデザイナー三原康裕のもとで、靴や服の企画・生産に携わった。\n2012年、パタンナーの村上高士とともに「doublet（ダブレット）」を設立した。井野の服は、日常の服にユーモアとひねりを加えたメンズで知られる。後ろ前に着るような刺繍のTシャツ、ぬいぐるみを詰めたブルゾン、お土産物のようなグラフィック、ゴミ袋のような素材の服など、見る人をくすっとさせながら、服の当たり前を問い直す。\n2018年、日本人として初めてLVMHプライズのグランプリを受賞し、世界的に注目された。その後、パリでショーや展示会を行い、PUMAなどとの協業も手がけている。",
    "mentors": [
      "mihara"
    ]
  },
  "iwai": {
    "en": "Ryota Iwai",
    "ja": "岩井良太",
    "bio": "日本でファッションを学び、いくつかのブランドで企画やデザインの経験を積んだ。\n2015年、「AURALEE（オーラリー）」を始めた。岩井の服づくりの特徴は、素材をゼロから作ること。オリジナルの糸を開発し、日本の機屋と生地を織り、軽くて柔らかく、上質な素材で、シャツ、ニット、コート、パンツなどのベーシックな服を作る。色の美しさ（淡い色、くすんだ色の繊細な組み合わせ）と、ゆったりとした着心地の良さで、国内外に熱心なファンを持つ。\n2019年からパリ・コレクションでショーを行っている。New Balanceとのスニーカーの協業も人気を集めた。「静かなラグジュアリー」の流れの中で、日本の素材の良さを世界に伝えるブランドとして評価されている。"
  },
  "leoni": {
    "en": "Veronica Leoni",
    "ja": "ヴェロニカ・レオーニ",
    "bio": "1984年頃、イタリアのローマ生まれ。ローマでファッションを学んだ。\nJil Sander（ラフ・シモンズのもと）、Céline（フィービー・ファイロのもと）、Moncler（「1 Moncler」のデザイン）、The Rowなどで、上質な素材と静かなミニマリズムの服づくりを学んだ。\n2022年、自身のブランド「QUIRA（クイラ）」を設立し、2023年にLVMHプライズのファイナリストとなった。\n2024年、Calvin Klein Collection（ラフ・シモンズが2018年に去って以来休止していたハイエンドのライン）のクリエイティブディレクターに就任し、2025年2月にニューヨークでデビューした。カルヴィン・クラインの1990年代のミニマリズムを現代的に再解釈したコレクションで評価されたが、2026年10月に退任した。",
    "mentors": [
      "raf",
      "philo"
    ]
  },
  "ackermann": {
    "en": "Haider Ackermann",
    "ja": "ハイダー・アッカーマン",
    "bio": "1971年、コロンビアのボゴタで生まれ、生後すぐにフランス人の夫婦に養子として迎えられた。地図製作者の父の仕事で、エチオピア、チャド、アルジェリア、フランス、オランダなど各地で育った。\nオランダで暮らしたのち、ベルギーのアントワープ王立芸術アカデミーで学んだが、学費が続かず中退した。在学中にジョン・ガリアーノのインターンを経験し、Bikkembergsなどで働いた。2001年、自身のブランドをパリで発表し始めた（本格的には2003年頃から）。\nアッカーマンの服は、ドレープ、深い色（紫、ボルドー、マスタード）のシルクやベルベットのレイヤード、身体を包むような柔らかいテーラリングで、詩的で官能的な美しさを持つ。女優のティルダ・スウィントン（長年のミューズ）、ティモシー・シャラメ（2022年ヴェネツィア映画祭のバックレスのホルターネックの衣装など）らに愛用されている。2010年にはカール・ラガーフェルドに後継者として名前を挙げられた。\n2016〜2018年にLVMHのメンズブランドBerlutiのクリエイティブディレクター、2023年春夏にJean Paul Gaultierのクチュールのゲストデザイナーを務めた。2024年、カナダのアウトドアブランドCanada Gooseのクリエイティブディレクター、同年9月からTom Fordのクリエイティブディレクターに就任した。",
    "mentors": [
      "galliano"
    ]
  },
  "hawkings": {
    "en": "Peter Hawkings",
    "ja": "ピーター・ホーキングス",
    "bio": "イングランド出身。ロンドンのセントラル・セント・マーチンズで学んだ。\n1990年代にGucciでトム・フォードのもとで働き始め、のちにYves Saint Laurent、そしてTom Fordのブランドに移り、約20年以上にわたってトム・フォードの右腕として、メンズのデザインを担当した。Tom Fordのメンズのデザイン・ディレクターとして、ベルベットのタキシードや、官能的なテーラリングを支えた。\n2023年、トム・フォードがブランドをEstée Lauderに売却して引退したのを受けて、Tom Fordのクリエイティブディレクターに就任し、メンズとウィメンズを率いた。フォードの官能的なスタイルを受け継いだが、2024年に退任し、後任はハイダー・アッカーマンだった。",
    "mentors": [
      "tomford"
    ]
  },
  "rosso": {
    "en": "Renzo Rosso",
    "ja": "レンツォ・ロッソ",
    "bio": "1955年、イタリア北東部のパドヴァ近郊のブルジーネで、農家の家に生まれた。工業専門学校で繊維の製造を学び、10代で母のミシンを使って自分のジーンズを作り始めた。\n1978年、仲間とともに「Diesel」を設立した。名前のディーゼルは、当時のガソリンに代わる燃料として注目されていたことから、「新しい選択肢」という意味を込めたという。1985年、ロッソは会社の株式をすべて買い取り、単独のオーナーとなった。\nDieselは、洗いやダメージ加工を施したヴィンテージ風のデニムと、社会や広告そのものを皮肉る挑発的な広告キャンペーン（「For Successful Living」）で、1990年代に世界的なブランドとなった。ロッソは「ジーンズの王様」と呼ばれた。\n2002年、持株会社「OTB（Only The Brave）」を設立し、Maison Martin Margiela（2002年）、Viktor & Rolf（2008年）、Marni（2012年）、Jil Sander（2021年）などを次々に買収し、イタリアを代表するファッショングループを築いた。2020年にはDieselのクリエイティブディレクターにグレン・マーティンスを起用し、ブランドを再び若い世代の人気ブランドにした。ワイナリーの経営や、慈善活動でも知られる。"
  },
  "okaniwa": {
    "en": "Tomoaki Okaniwa",
    "ja": "岡庭智明",
    "bio": "1963年、長野県生まれ。若い頃は絵画を学び、画家を目指していた。服づくりに興味を移し、独学でパターンや縫製を学んだ。\n1987年、自身の会社「キャタピラープロデュイ」を設立し、服づくりを始めた。岡庭は、デザインだけでなく、パターンから縫製まで自ら手がける職人的なデザイナーとして知られる。\n2001年春夏、「The Viridi-anne（ザ ヴィリディアン）」を始めた。岡庭の服は、黒やグレーを中心にした静かな色、製品染めや手作業による加工、立体的で緻密なパターン、丁寧な縫製で、日本のアルチザン系（職人的なブランド）を代表する一つとなった。メンズとウィメンズを展開し、レザーのジャケットや、加工したコットンのシャツ、ドレープのあるパンツなどで、国内外のアーカイブ好きに根強い人気がある。"
  },
  "horikawa": {
    "en": "Tatsuro Horikawa",
    "ja": "堀川達郎",
    "bio": "1970年代生まれ。音楽、特にインダストリアル、ノイズ、エレクトロニックの世界に深く影響を受けた。\n2001年、東京で「JULIUS（ユリウス）」を始めた。当初はアートやグラフィック、音楽を含むプロジェクトとして始まり、のちに服のブランド「JULIUS_7」として展開した。\n堀川の服は、黒を中心にしたダークな色、構築的でドレープのあるシルエット、レイヤードを前提にした長い丈、レザーやデニムの加工で、日本のアヴァンギャルド系、ゴシック系を代表するブランドの一つ。2006年頃からパリでも展示会やショーを行い、海外にもファンを持つ。服だけでなく、ブランドの世界観を表現する写真や映像、音楽にもこだわっている。"
  },
  "nishida": {
    "en": "Daisuke Nishida",
    "ja": "西田大介",
    "bio": "日本出身。若い頃はレスリングに打ち込み、その後医療の道を学んだという、ファッションデザイナーとしては異色の経歴を持つ。人体の構造や動き、筋肉や骨格についての知識は、のちの服づくりの土台となった。\n2008年頃、ブランド「DEVOA（デヴォア）」を始めた。西田の服は、人体の構造と動きの研究にもとづく立体的なパターン、身体に沿いながら動きを妨げないシルエット、製品染めや天然素材による深い色と質感で知られる。黒やグレーを中心にしたストイックな服は、日本のアルチザン系として、国内外のファンに支持されている。"
  },
  "fujiwara_h": {
    "en": "Hiroshi Fujiwara",
    "ja": "藤原ヒロシ",
    "bio": "1964年、三重県伊勢市生まれ。10代でロンドンに渡り、パンクの店「Seditionaries」でマルコム・マクラーレンやヴィヴィアン・ウエストウッドと出会い、ニューヨークではヒップホップのDJ文化に触れた。帰国後、日本で最初期のヒップホップのDJの一人として活動し、高木完とのユニット「タイニー・パンクス」でも知られた。音楽プロデューサーとしても、小泉今日子、UAなどの作品に関わった。\n1990年頃、「GOODENOUGH」を始めた。ロゴを入れたTシャツやスウェット、ナイロンジャケットなど、シンプルなアイテムを、ロンドンやニューヨークのストリートの感覚で作り、裏原宿の原点となった。高橋盾（UNDERCOVER）やNIGO（A BATHING APE）ら裏原宿の後輩たちに、ファッションと音楽の両面で大きな影響を与えた。\n2003年、「fragment design」を設立した。稲妻のロゴで知られ、NIKE（エアジョーダン1、HTMライン）、Louis Vuitton（2017年）、Moncler、Starbucks、ポケモン、ブルガリなど、数多くのブランドとの協業でデザインを提供する。「裏原宿のゴッドファーザー」と呼ばれ、日本のストリートカルチャーを世界に広めた最大の功労者の一人とされる。"
  },
  "kiyonaga": {
    "en": "Hirofumi Kiyonaga",
    "ja": "清永浩文",
    "bio": "1965年、大分県生まれ。文化服装学院を卒業後、フランスのブランドA.P.C.の東京で7年間働き、シンプルで上質な服づくりと、ブランドのあり方を学んだ。\n1998年、自身の会社「SOPH.（ソフ）」を設立し、「SOPHNET.（ソフネット）」を始めた。清永の服は、上質な素材のベーシックな服を、細身のシルエットと少しずらしたデザインで作るもので、2000年代の東京の大人のストリートを代表した。\nSOPH.では、uniform experiment（藤原ヒロシとの協業）、F.C.Real Bristol（サッカーを題材にしたブランド）なども手がけ、NIKE、Burberryなどとの協業も多い。2022年に代表を退任した。"
  },
  "vansaene": {
    "en": "Dirk Van Saene",
    "ja": "ダーク・ヴァン・セーヌ",
    "bio": "ベルギー出身。アントワープ王立芸術アカデミーのファッション科で学び、1981年に卒業した。在学中から、のちに長年のパートナーとなるウォルター・ヴァン・ベイレンドンクと親しかった。\n卒業した1981年、アントワープに自身の店「Beauties and Heroes」を開き、少量の服を発表した。1986年、ロンドンのブリティッシュ・デザイナー・ショーで「アントワープ・シックス」の一人として紹介された。\nヴァン・セーヌの服は、クラシックな仕立てや女性らしい服を、皮肉とユーモアでわずかにずらす作風で知られる。他のシックスのメンバーに比べて商業的な規模は小さく、ファッションの世界から距離を置いた時期も長い。ウォルター・ヴァン・ベイレンドンクとの共同の展示やプロジェクトも多い。現在は主に彫刻家・画家として活動している。"
  },
  "yee": {
    "en": "Marina Yee",
    "ja": "マリナ・イー",
    "bio": "1958年、ベルギー生まれ（中国系）。アントワープ王立芸術アカデミーのファッション科で学び、1981年に卒業した。\n卒業後すぐに、自身のブランド「Marie」を始め、アントワープ・シックスの一人として注目された。しかし、ファッションの世界の商業的なペースに違和感を抱き、1986年のロンドンでの発表の直後、1988年頃にグループを離れた。\nその後は、古着や中古の服をほどいて組み合わせ直す服づくり、舞台や映画の衣装、アントワープやゲントのアカデミーでの教育などを静かに続けた。2019年頃から、アントワープの若いブランドと組んで再び自身の名前でコレクションを発表し、再評価された。2026年のMoMuでのアントワープ・シックスの40周年の展覧会の準備が進む中、2025年11月にがんで死去した。"
  },
  "branquinho": {
    "en": "Veronique Branquinho",
    "ja": "ヴェロニク・ブランキーニョ",
    "bio": "1973年、ベルギーのフィルフォールデで、ポルトガル系の家庭に生まれた。アントワープ王立芸術アカデミーのファッション科を1995年に卒業した。\n1998年、パリで自身のブランドを発表し、アントワープ・シックスの次の世代を代表するデザイナーとなった。ブランキーニョの服は、メランコリックで少女的、しかしストイックで知的な女性像を持つ。くすんだ色、長いスカート、細身のジャケット、ニット、学校の制服のようなディテールで、1990年代末から2000年代の「アントワープの静かな美しさ」を体現した。2003年にはメンズも始め、Delvauxのバッグのデザインにも関わった。\n2009年にブランドを休止し、2012年に再開したが、2017年に再び休止した。古着では2000年代前半の服が根強い人気を持つ。"
  },
  "vandevorst": {
    "en": "An Vandevorst & Filip Arickx",
    "ja": "アン・ヴァンデヴォースト&フィリップ・アリックス",
    "bio": "アン・ヴァンデヴォースト（1968年生まれ）とフィリップ・アリックス（1971年生まれ）は、アントワープ王立芸術アカデミーで出会い、夫婦となった。アンはドリス・ヴァン・ノッテンのアシスタント、フィリップはダーク・ビッケンバーグのアシスタントを務めた。\n1997年、2人で「A.F. Vandevorst」を始め、1998年にパリでデビューした。ブランドのシンボルは赤十字の腕章。2人の服は、乗馬のジャケットやブーツ、医療や軍のディテール、ベッドや眠りをテーマにしたショー、ドイツの芸術家ヨーゼフ・ボイスへのオマージュなど、物語性のある、知的でロマンティックな作風で知られた。ベルギーの「アントワープ・シックス」の次の世代を代表するブランドの一つだった。\n2020年にブランドを終了した。古着では、乗馬のディテールのジャケットやブーツが人気。",
    "mentors": [
      "vannoten",
      "bikkembergs"
    ]
  },
  "serfaty": {
    "en": "Yohan Serfaty",
    "ja": "ヨハン・セルファティ",
    "bio": "フランス出身。2010年、パリでジル・エラルフとともに「Y/Project」を設立し、ダークで構築的なメンズを発表した。\nY/Projectは、黒を中心にしたレザーやジャージー、ドレープのある服で、パリの若いブランドとして注目を集め始めていた。\n2013年4月、セルファティはがんのため若くして亡くなった。その後、彼のアシスタントだったグレン・マーティンスがY/Projectのクリエイティブディレクターを引き継ぎ、ブランドを世界的に人気のブランドに育てた。"
  },
  "kikuchi": {
    "en": "Takeo Kikuchi",
    "ja": "菊池武夫",
    "bio": "1939年、東京生まれ。原のぶ子アカデミー洋裁で服づくりを学んだ。\n1970年、稲葉賀恵、大楠祐二らとともにアパレル会社「BIGI（ビギ）」を設立した。1975年、メンズの「MEN'S BIGI」を始め、英国のトラッドを日本の若者向けに再解釈した服で人気を集めた。1980年代、DC（デザイナーズ&キャラクターズ）ブランドのブームの中心にいたデザイナーの一人。\n1984年、大手アパレルのワールドに移り、自身の名前を冠した「TAKEO KIKUCHI」を始めた。英国的なトラッドに、ロックや古着、ミリタリーの要素を混ぜ、細身のスーツや革のジャケットなど、大人の男性のための洒落た服で人気を集めた。映画や音楽の世界の人々との交流も広く、俳優や歌手の衣装も手がけた。日本のメンズファッションの草分けの一人として長く活躍した。"
  },
  "fmoschino": {
    "en": "Franco Moschino",
    "ja": "フランコ・モスキーノ",
    "bio": "1950年、イタリアのミラノ近郊のアッビアーテグラッソで、鋳造工場を営む家に生まれた。ミラノのブレラ美術アカデミーで絵画を学び、画家を目指した。学費を稼ぐためにファッションのイラストを描くうちに、1971年から1977年まで、ジャンニ・ヴェルサーチのもとでイラストレーターとして働いた。その後、イタリアのブランド「Cadette」のデザイナーを務めた。\n1983年、自身のブランド「Moschino」を始めた。モスキーノは、ファッションの世界そのものを皮肉るユーモアとパロディで知られた。「Expensive jeans（高いジーンズ）」「Cheap and Chic（安くてシック）」「Stop the Fashion System（ファッション・システムを止めろ）」などのスローガン、シャネルのツイードのスーツのパロディ、ハートやピースマーク、テディベア、食べ物のモチーフ、目玉焼きの付いたドレスなどで、1980〜90年代の高級ブランドの権威や消費主義をからかった。1988年にはセカンドライン「Cheap and Chic」を始めた。環境保護や動物愛護、エイズ問題のメッセージも積極的に発信した。\n1994年9月、44歳で死去した。その後は長年のアシスタントだったロッセラ・ヤルディーニがブランドを率い、2013年からはジェレミー・スコットが引き継いだ。古着では、1980〜90年代のスローガン入りのジャケットやパロディの服が非常に人気。"
  },
  "jeremyscott": {
    "en": "Jeremy Scott",
    "ja": "ジェレミー・スコット",
    "bio": "1975年、アメリカ・ミズーリ州カンザスシティで生まれ、近郊の農場で育った。ニューヨークのプラット・インスティテュートでファッションを学んだ。\n1996年、パリで自身のブランド「Jeremy Scott」を始め、ゴミ袋や紙のドレスなど、挑発的でポップな作品で注目された。ハリウッドのセレブリティ、マドンナ、ビョーク、リアーナ、ケイティ・ペリーらの衣装も手がけた。\n2002年頃からadidas Originalsとの協業を始め、羽根のついたスニーカー「JS Wings」、テディベアのついたスニーカーなどで大人気となった。\n2013年10月、Moschinoのクリエイティブディレクターに就任し、10年間ブランドを率いた。最初のコレクションでは、マクドナルドのロゴを引用したバッグや服を発表し、その後もバービー人形、スポンジ・ボブ、ルーニー・テューンズ、ガソリンスタンド、紙人形など、ポップカルチャーの記号を大胆に引用した服で、フランコ・モスキーノのユーモアの精神を現代のSNS時代に受け継いだ。2023年3月に退任した。"
  },
  "renne": {
    "en": "Davide Renne",
    "ja": "ダヴィデ・レンネ",
    "bio": "1977年、イタリアのフィレンツェ生まれ。フィレンツェのファッションの学校ポリモーダで学んだ。\n卒業後、Gucciに入社し、約20年間ウィメンズのデザインに携わった。トム・フォード、フリーダ・ジャンニーニ、アレッサンドロ・ミケーレの3代のクリエイティブディレクターのもとで働き、ミケーレの時代にはヘッド・オブ・ウィメンズ・デザインとして、Gucciのマキシマリズムの服づくりを支えた。\n2023年10月、ジェレミー・スコットの後任としてMoschinoのクリエイティブディレクターに就任した。しかし、就任からわずか10日ほどの2023年11月、46歳で急逝した。最初のコレクションを発表することはなく、ファッション業界に大きな衝撃を与えた。",
    "mentors": [
      "michele"
    ]
  },
  "appiolaza": {
    "en": "Adrian Appiolaza",
    "ja": "アドリアン・アッピオラーザ",
    "bio": "1970年代、アルゼンチンのブエノスアイレス生まれ。ロンドンに渡り、ファッションを学んだ。\nパリのMartine Sitbonで経験を積んだのち、Chloé（フィービー・ファイロのもと）、Miu Miu、Louis Vuitton（マーク・ジェイコブスのもと）など、多くのメゾンでウィメンズのデザインを担当した。2013年からはLoeweでジョナサン・アンダーソンのもと、ウィメンズのデザインディレクターとして、Loeweの再生を内側から支えた。\n2024年1月、ダヴィデ・レンネの急逝を受けて、Moschinoのクリエイティブディレクターに就任した。同年2月のデビューでは、創業者フランコ・モスキーノのアーカイブの皮肉の効いたユーモアに立ち返ったコレクションを発表した。しかし、2026年6月に親会社Aeffeが契約の終了を発表し、約2年半で退任した。",
    "mentors": [
      "anderson"
    ]
  },
  "castiglioni": {
    "en": "Consuelo Castiglioni",
    "ja": "コンスエロ・カスティリオーニ",
    "bio": "1959年、スイスのルガーノ生まれ。イタリア人の実業家ジャンニ・カスティリオーニと結婚した。夫の家業はイタリアの毛皮会社「CIWI Furs」で、カスティリオーニはそのコンサルタントとして、毛皮をもっと軽く現代的に見せる服づくりを始めた。\n1994年、毛皮を使った小さなコレクションから「Marni」を創業した。カスティリオーニの服は、独特の色合わせ（くすんだ色と鮮やかな色の組み合わせ）、手描きのような花や幾何学のプリント、大きなアクセサリー（樹脂やビーズのネックレス）、少しずれたバランスのシルエットで、知的で遊び心のある、トレンドに流されない女性像を作った。\nMarniは2000年代、ニューヨークやロンドンの知的な女性たちに熱心に支持され、2012年にH&Mとの協業も行った。2012年にOTBグループが株式を取得し、2016年に創業者は退任した。古着では、2000年代のプリントのドレスやスカート、ニット、ネックレスが人気。"
  },
  "risso": {
    "en": "Francesco Risso",
    "ja": "フランチェスコ・リッソ",
    "bio": "1983年、イタリアのジェノヴァで生まれ、家族とともにサルデーニャ島で育った（ヨットで暮らしていた時期もあるという）。フィレンツェのポリモーダ、ニューヨークのファッション工科大学（FIT）、ロンドンのセントラル・セント・マーチンズで学んだ。\nAlessandro Dell'Acquaのもとで働いたのち、Pradaで約8年間、ミウッチャ・プラダのもとでウィメンズのデザインを担当した。\n2016年、創業者コンスエロ・カスティリオーニの後任としてMarniのクリエイティブディレクターに就任した。リッソのMarniは、手作業の染めや絵付け、ニットの手編み、アーティストとの協業、型破りなシルエットで、より自由で実験的な、時に荒々しいブランドになった。ショーの会場で観客をソファや段ボールに座らせる演出、Uniqloとの協業、2023年のニューヨークでのショーなども話題になった。2025年6月に約9年率いたMarniを退任した。",
    "mentors": [
      "mprada"
    ]
  },
  "rogge": {
    "en": "Meryll Rogge",
    "ja": "メリル・ロッゲ",
    "bio": "ベルギー出身。アントワープ王立芸術アカデミーのファッション科で学んだ。\n卒業後、2008年から2015年までニューヨークのMarc Jacobsで働き、その後ベルギーに戻ってDries Van Notenでウィメンズのデザインの責任者を務めた。プリントと色彩、素材を重ねるドリス・ヴァン・ノッテンの服づくりを内側から支えた。\n2020年、自身のレーベル「Meryll Rogge」を始め、日常的な服に夜のパーティーの華やかさを混ぜた服で注目された。\n2025年7月、フランチェスコ・リッソの後任としてMarniのクリエイティブディレクターに就任し、2026年2月にミラノでデビューした。",
    "mentors": [
      "jacobs",
      "vannoten"
    ]
  },
  "thombrowne": {
    "en": "Thom Browne",
    "ja": "トム・ブラウン",
    "bio": "1965年、アメリカ・ペンシルベニア州アレンタウンで、7人きょうだいの一人として弁護士の家庭に生まれた。インディアナ州のノートルダム大学で経済学を学び、水泳部に所属した。卒業後、俳優を目指してロサンゼルスに移り、テレビのCMなどに出演した。\n1990年代後半にニューヨークに移り、Giorgio Armaniの店で販売員として働き、その後Ralph Laurenの傘下にあったClub Monacoのデザインチームに加わった。\n2001年、ニューヨークのウエスト・ヴィレッジで、わずか5着のスーツから自身のブランドを始めた。トム・ブラウンの代名詞は、丈を短くし、身体にぴったり沿わせて縮めたように見えるグレーのスーツ。くるぶしが見える短いパンツ、ジャケットの短い丈、白いシャツとネクタイの組み合わせは、ゆったりしたスーツが主流だった時代のメンズのテーラリングの常識を変え、2000年代以降の細身のスーツの流行を作った。赤・白・青のタブ（グログランのリボン）と、袖の4本線は、ブランドのシンボルとなった。\nショーは演劇的で、全員が同じ顔のマスクをつけたり、オフィスや教室、雪景色を再現したりする。2006年にCFDAのメンズウェア・デザイナー・オブ・ザ・イヤー、2018年にZegnaグループが85%を取得した。2023年から2025年まではCFDA（アメリカファッション協議会）の会長を務めた。"
  },
  "rachelscott": {
    "en": "Rachel Scott",
    "ja": "レイチェル・スコット",
    "bio": "1980年代、ジャマイカのキングストン生まれ。ジャマイカで育ち、アメリカに渡ってニューヨークのスクール・オブ・ヴィジュアル・アーツで学んだ。\nニューヨークのファッション業界で約10年間、デザイナーとして経験を積んだのち、2021年、自身のブランド「Diotima（ディオティマ）」を始めた。名前は古代ギリシャの哲学者プラトンの『饗宴』に登場する女性から。スコットの服は、ジャマイカのかぎ針編み（クロシェ）や手仕事、カリブの文化、黒人女性の身体と美しさをテーマに、ニューヨークのテーラリングと組み合わせたもので、ジャマイカの職人と協働して作られる。\n2024年にCFDAのウィメンズウェア・デザイナー・オブ・ザ・イヤーを受賞した。2025年、Loeweへ移ったジャック・マッコローとラザロ・ヘルナンデスの後任として、Proenza Schoulerのクリエイティブディレクターに就任した。"
  },
  "olsens": {
    "en": "Mary-Kate & Ashley Olsen",
    "ja": "メアリー＝ケイト&アシュレー・オルセン",
    "bio": "メアリー＝ケイト・オルセンとアシュレー・オルセンは、1986年、カリフォルニア州シャーマンオークス生まれの双子（二卵性）。生後9か月で、テレビドラマ『フルハウス』（1987〜1995年）の末っ子ミシェル役を2人で交代で演じ、アメリカで最も有名な子役となった。10代では自分たちの名前のビデオやゲーム、ウォルマートで売られた衣料品のブランドで巨額の収入を得た。\n2004年頃に俳優業から離れ、ニューヨーク大学で学んだのち、ファッションの道に進んだ。2006年、完璧な白いTシャツを作ることから「The Row」を始めた。名前は、ロンドンの仕立て屋街サヴィル・ロウ（Savile Row）から。最初のコレクションは、Tシャツ、レギンス、カシミアのタンクドレスなどわずか7点だった。\nThe Rowは、最高級の素材、端正な仕立て、ロゴや装飾を排したシンプルな形、広告やSNSをほとんど使わない姿勢で、「静かなラグジュアリー（クワイエット・ラグジュアリー）」を代表するブランドとなった。マルゴー・バッグ、パーク・トート、靴などのヒットも多い。2012年にCFDAのウィメンズウェア・デザイナー・オブ・ザ・イヤー（2014年、2018年も受賞）を受賞し、ファッション・デザイナーとして高い評価を得た。2024年頃には、ショーの写真撮影を禁止し、観客にノートとペンを配ったことも話題になった。"
  },
  "suzuki": {
    "en": "Daiki Suzuki",
    "ja": "鈴木大器",
    "bio": "1962年、青森県生まれ。文化服装学院を卒業後、セレクトショップのNEPENTHESに入り、1989年にアメリカに渡って現地でバイヤーとして働いた。アメリカの古いワークウェア、ミリタリー、アウトドアの服、ハンティングの服を集めて研究し、それらを作っていたアメリカの古い縫製工場を訪ね歩いた。\n1999年、ニューヨークで「Engineered Garments（エンジニアド ガーメンツ）」を始めた。名前は、機能から「設計された服」という意味。鈴木の服は、アメリカの古着の型やディテール（ポケット、フラップ、ステッチ）を研究し、それらを重ねたり切り替えたりして、機能的でありながら独特の遊び心のあるデザインにしたもの。生産のほとんどをニューヨークの工場で行い、アメリカの服づくりの伝統を守ってきた。\n2008年、日本人として初めてCFDAの新人賞（ベスト・ニュー・メンズウェア・デザイナー・イン・アメリカ）を受賞した。Woolrich Woolen Millsのデザイン、Barbour、NIKE、Hokaなど多くの協業も手がけた。2025年、長年の協力者たちにデザインを引き継いだ。"
  },
  "neilbarrett": {
    "en": "Neil Barrett",
    "ja": "ニール・バレット",
    "bio": "1965年、イングランドのデヴォン州で、テーラーの家系に生まれた。ロンドンのセントラル・セント・マーチンズでファッションを学び、ロイヤル・カレッジ・オブ・アートで修士号を取った。\n1989年、Gucciのメンズのシニアデザイナーとして、トム・フォードの就任前後のGucciで働いた。1995年、Pradaのメンズのデザインディレクターとして移り、Pradaのメンズのコレクションと、1997年に始まったテクニカルなスポーツウェア「Prada Sport（Linea Rossa）」の立ち上げ期に関わった。\n1999年、自身のブランド「Neil Barrett」を始めた。バレットの服は、英国のテーラリングとスポーツウェア、ミリタリーを融合した、細身で現代的なメンズで知られ、稲妻のボルトのモチーフも人気になった。",
    "mentors": [
      "mprada"
    ]
  },
  "mello": {
    "en": "Dawn Mello",
    "ja": "ドーン・メロ",
    "bio": "1931年、アメリカ・マサチューセッツ州リン生まれ。アメリカの百貨店業界で長く活躍し、メイ・カンパニーのファッション・ディレクター、B.アルトマンなどを経て、1970年代にニューヨークの高級百貨店Bergdorf Goodmanの社長となり、店を高級ブランドの集まる場所として再生させた。\n1989年、一族の争いで経営が傾いていたGucciに、マウリツィオ・グッチに招かれて、エグゼクティブ・バイス・プレジデント兼クリエイティブディレクターとして入った。メロは、乱発されていたライセンスと商品を大幅に絞り込み、バンブーバッグやホースビットローファーなどのブランドの原点に立ち返る再建を指揮した。そして、まだ無名だった若いアメリカ人デザイナー、トム・フォードをウィメンズのデザイナーとして起用した。この人選が、1990年代のGucciの劇的な復活につながった。\n1994年にBergdorf Goodmanに戻った。2020年に死去した。"
  },
  "facchinetti": {
    "en": "Alessandra Facchinetti",
    "ja": "アレッサンドラ・ファッキネッティ",
    "bio": "1972年、イタリア生まれ。ミラノのIstituto Marangoniでファッションを学んだ。\n卒業後、Pradaのデザインチーム、Miu Miuで経験を積み、1990年代末にGucciに入り、トム・フォードのもとでウィメンズのデザインを担当した。2004年、フォードの退任を受けて、Gucciのウィメンズのクリエイティブディレクターに就任した。しかし、フォードの強い影響力の後を継ぐ重圧の中で、2005年春夏と2005-06年秋冬の2シーズンを発表したのち、2005年3月に退任した。\n2007年、ヴァレンティノ・ガラヴァーニの引退後のValentinoのクリエイティブディレクターに就任したが、約1年で退任し、マリア・グラツィア・キウリとピエールパオロ・ピッチョーリに交代した。その後は、Moncler Gamme Rouge、Pinko、Tod'sのウィメンズなどを手がけた。",
    "mentors": [
      "tomford"
    ]
  },
  "johnray": {
    "en": "John Ray",
    "ja": "ジョン・レイ",
    "bio": "スコットランド出身。ロンドンのセントラル・セント・マーチンズでファッションを学んだ。卒業後、キャサリン・ハムネットなどのもとで経験を積んだ。\n1990年代、Gucciに入り、トム・フォードのもとでメンズのデザインを担当した。フォードの官能的で洗練されたメンズを内側から支えた一人。2004年、フォードの退任を受けて、Gucciのメンズのクリエイティブディレクターに就任し、ウィメンズのアレッサンドラ・ファッキネッティ、アクセサリーのフリーダ・ジャンニーニとの3人体制でブランドを率いた。2006年頃、ジャンニーニがブランド全体を率いることになり、退任した。",
    "mentors": [
      "tomford"
    ]
  },
  "paulhelbers": {
    "en": "Paul Helbers",
    "ja": "ポール・ヘルバース",
    "bio": "オランダ出身。ベルギーのアントワープ王立芸術アカデミーで学んだ。\n卒業後、Maison Martin Margielaでメンズのデザインを担当した。マルジェラの匿名的で知的なメンズの服づくりを内側から経験した。\n2006年から2011年まで、マーク・ジェイコブスのもとでLouis Vuittonのメンズのスタジオを率い、メンズのコレクションの方向性を作った。2011年にキム・ジョーンズにメンズを引き継いだ。",
    "mentors": [
      "jacobs",
      "margiela"
    ]
  },
  "bergere": {
    "en": "Éric Bergère",
    "ja": "エリック・ベルジェール",
    "bio": "1960年、フランス生まれ。10代でパリのファッションの学校で学び、17歳でHermèsのデザインスタジオに入った。若くしてHermèsのウィメンズのプレタポルテのデザインを任され、1980年代を通じてHermèsの服を手がけた。\nその後、モデルのイネス・ド・ラ・フレサンジュのブランド、Lanvinなどでデザイナーを務め、1990年代には自身のブランド「Eric Bergère」を始めた。マルタン・マルジェラがHermèsのウィメンズを担当する前の時代のデザイナーとして、Hermèsの服の歴史の一部を担った。"
  },
  "sarahlinhtran": {
    "en": "Sarah-Linh Tran",
    "ja": "サラ＝リン・トラン",
    "bio": "フランス出身（ベトナム系）。クリストフ・ルメールのパートナーで、2014年からLEMAIREの共同アーティスティックディレクターとして、ルメールとともにブランドを率いる。もとはアートや建築に関心を持ち、ルメールのブランドの撮影やコミュニケーションにも関わっていた。"
  },
  "ourlegacy": {
    "en": "Jockum Hallin & Cristopher Nying",
    "ja": "ヨックム・ハリン&クリストファー・ニイング",
    "bio": "スウェーデンのストックホルムで、2005年頃（2004年とする資料もある）にOur Legacyを始めた2人。最初はグラフィックのTシャツから出発し、のちに上質な素材のシャツ、ニット、パンツなど、少しずれたベーシックな服でブランドを育てた。のちにリカルドス・クラーレンが加わり、3人で経営する。"
  },
  "jonnyjohansson": {
    "en": "Jonny Johansson",
    "ja": "ジョニー・ヨハンソン",
    "bio": "スウェーデン出身。ファッションの正式な教育は受けず、音楽やグラフィックの仕事をしていた。1996年、ストックホルムで仲間とクリエイティブ集団「ACNE（Ambition to Create Novel Expressions）」を立ち上げ、友人のために作った100本のジーンズから服づくりを始めた。Acne Studiosのクリエイティブディレクターとして、スカンジナビアのミニマリズムとアートや若者文化を組み合わせたブランドに育てた。"
  },
  "simonjacquemus": {
    "en": "Simon Porte Jacquemus",
    "ja": "シモン・ポルト・ジャックムス",
    "bio": "1990年、南フランスのサロン＝ド＝プロヴァンス近郊の農家に生まれる。パリのESMODに入ったが、母の急死を受けて中退し、19歳の2009年に、母の旧姓「ジャックムス」を名に自身のブランドを始めた。雑誌の仕事やCOMME des GARÇONSの店での販売の経験もある。南フランスの太陽、海、ラベンダー畑をテーマにした服と、極小のバッグ「ル・チキート」などで人気を得て、2019年にはラベンダー畑でのショーが話題になった。"
  },
  "simonerocha": {
    "en": "Simone Rocha",
    "ja": "シモーン・ロシャ",
    "bio": "1986年、アイルランドのダブリン生まれ。香港出身のデザイナー、ジョン・ロシャの娘。ダブリンのナショナル・カレッジ・オブ・アート・アンド・デザイン、ロンドンのセントラル・セント・マーチンズで学び、2010年にロンドンで自身のブランドを始めた。真珠、チュール、刺繍、ふくらんだ袖など、少女らしさと強さ、母性や宗教的なイメージを組み合わせた服で知られる。2021年にH&Mとの協業、2024年にJean Paul Gaultierのクチュールのゲストデザイナーを務めた。"
  },
  "minagawa": {
    "en": "Akira Minagawa",
    "ja": "皆川明",
    "bio": "1967年、東京生まれ。文化服装学院の夜間部で学び、10代でフィンランドなど北欧を旅したことが大きな影響を与えた。縫製工場や魚市場で働きながら服づくりを続け、1995年に「minä」を始め、2003年に「minä perhonen（フィンランド語で「私」「蝶」）」に改めた。オリジナルの図案を描き、日本各地の工場と生地から作る。25個の点を円に並べた刺繍「タンバリン」（2000-01年秋冬）が代表的なモチーフ。「せめて100年つづくブランド」を掲げ、家具や器、ホテルの仕事も手がける。"
  },
  "tsumori": {
    "en": "Chisato Tsumori",
    "ja": "津森千里",
    "bio": "1954年、埼玉県生まれ。文化服装学院を卒業し、1977年にイッセイ ミヤケに入社。ISSEY SPORTSのデザインを担当し、同ラインは1983年頃（1984年とする資料もある）に「I.S. Chisato Tsumori Design」と改められた。1990年に東京で自身のブランド「TSUMORI CHISATO」を始め、1999年にパリのマレ地区に店を開き、2003年（2004年春夏とする資料もある）からパリ・コレクションで発表した。猫や星、女の子などのイラストのプリントと刺繍の、カラフルで夢のある服で人気を集めた。",
    "mentors": [
      "miyake"
    ]
  },
  "hanaemori": {
    "en": "Hanae Mori",
    "ja": "森英恵",
    "bio": "1926年、島根県生まれ。東京女子大学を卒業後、1951年に東京・新宿に洋装店を開き、日本映画の衣装を数多く手がけた。1965年にニューヨークでコレクションを発表して成功し、1977年にパリでオートクチュールを始め、パリ・クチュール組合の正式メンバーとなった初めての日本人（アジア人）となった。蝶のモチーフから「マダム・バタフライ」と呼ばれた。皇太子妃（雅子さま）のウェディングドレスも手がけた。2004年にオートクチュールを終了し、2022年8月に96歳で死去した。"
  },
  "tayama": {
    "en": "Atsuro Tayama",
    "ja": "田山淳朗",
    "bio": "1955年、熊本県生まれ。文化服装学院を1975年に卒業し、同年に賞を受けた。在学中から山本耀司のもとで働き、ワイズのチーフアシスタント、ヨーロッパでの事業の責任者を務めた。1982年に独立して会社を設立し、東京で発表を始めた。1989年頃からパリを拠点にブランド「ATSURO TAYAMA」を展開し、1991年からパリ・コレクションで発表した。Cacharelのデザインなどにも関わった。ドレープと流れるシルエットの、柔らかく知的な服で知られる。",
    "mentors": [
      "yamamoto"
    ]
  },
  "paulsmith": {
    "en": "Paul Smith",
    "ja": "ポール・スミス",
    "bio": "1946年、イングランドのノッティンガム生まれ。15歳で学校を離れ、服の倉庫で働いた。プロの自転車選手を目指したが、17歳のときの大きな事故で断念し、入院中に知り合った仲間を通じて美術やファッションに触れた。のちに妻となるポーリーンの支援で服づくりを学び、1970年、ノッティンガムに小さな店を開いた。1976年にパリでメンズのコレクションを発表した。クラシックな英国のテーラリングに、カラフルなストライプや遊び心のある裏地、意外なプリントを組み合わせる「ひねりのあるクラシック」で知られ、特に日本で大成功した。2000年にナイトの称号を受けた。"
  },
  "viktorrolf": {
    "en": "Viktor Horsting & Rolf Snoeren",
    "ja": "ヴィクター・ホルスティン＆ロルフ・スノエレン",
    "aka": [
      "Viktor & Rolf",
      "ヴィクター＆ロルフ",
      "ヴィクターアンドロルフ"
    ],
    "bio": "ヴィクター・ホルスティンは1969年、ロルフ・スノエレンも1969年にオランダで生まれた。2人はアーネム芸術アカデミーで出会い、1992年に卒業すると、すぐにデュオとして活動を始めた。\n1993年、南フランスのイエール国際モードフェスティバルで受賞して注目を集めた。最初の数年は服を売るためではなく、アート作品のようなインスタレーションや展示で発表し、「売れない服」をあえて作ることで、ファッション業界そのものを問いかけた。\n1998年にパリでオートクチュールを発表し、1999-2000年秋冬にはモデル1人に9着の服をマトリョーシカ人形のように重ねて着せていくショーで伝説的な評価を得た。2000年に既製服を始め、2002-03年秋冬にはブルーの服に映像を映すクロマキーの演出で話題になった。2005年の香水「フラワーボム」は大ヒットし、ブランドを支える柱になった。2008年にディーゼル創業者のレンツォ・ロッソのグループ（現 OTB）が株式を取得した。2015年からは既製服をやめ、クチュールと香水に集中している。"
  },
  "gigli": {
    "en": "Romeo Gigli",
    "ja": "ロメオ・ジリ",
    "aka": [
      "ロメオジリ"
    ],
    "bio": "1949年、イタリア北部のファエンツァに生まれた。家は古書店で、本や美術に囲まれて育った。建築を学んだのち、若い頃に世界各地を旅し、その経験がのちの服づくりの土台になった。\n1970年代にニューヨークなどで仕事をしたあと、1983年にミラノで自分のブランドを始めた。1980年代のイタリアでは、肩パッドの入った力強い服が主流だったが、ジリは肩を小さく丸め、繭（コクーン）や卵のような柔らかいシルエット、深い宝石のような色、ビザンチンや東洋の装飾を使い、「反パワースーツ」の詩的な服で大きな人気を得た。1989年からパリで発表した。\n1990年代に経営のパートナーと対立し、2004年ごろには自分の名前のブランドの権利を失った。その後は別の名前で小さく活動を続けた。アレキサンダー・マックイーン、ドリス・ヴァン・ノッテンなど、多くのデザイナーに影響を与えたとされ、近年アーカイブとしての評価が高まっている。"
  },
  "capasa": {
    "en": "Ennio Capasa",
    "ja": "エンニオ・カパサ",
    "aka": [
      "カパサ"
    ],
    "bio": "1960年、イタリア南部のレッチェに生まれた。ミラノのブレラ美術学校で学んだのち、日本に渡り、1982年から約3年間、東京で山本耀司のもとで働いた。そこで黒の美しさ、余計な装飾のない服の考え方を学んだ。\n1986年にミラノに戻り、兄のカルロとともに「コスチューム・ナショナル」を始めた。日本で学んだミニマリズムに、ロックやパンクの雰囲気、細身のシルエット、レザーをまぜた黒い服は、1990年代のミラノで、プラダやジル・サンダーとはまた違う「ロックなミニマリズム」として人気を集めた。メンズでは、細いスーツやライダース、ブーツが特に人気だった。\n2016年にブランドを離れ、のちに新しいプロジェクトを始めた。",
    "mentors": [
      "yamamoto"
    ]
  },
  "montana": {
    "en": "Claude Montana",
    "ja": "クロード・モンタナ",
    "aka": [
      "モンタナ"
    ],
    "bio": "1947年、パリに生まれた。若い頃にロンドンへ渡り、張り子（パピエ・マシェ）で作ったジュエリーを売って評判を得た。パリに戻ってからはレザーの会社でデザイナーとして働いた。\n1979年に自分のブランドを始め、1981年にはメンズの「モンタナ・オム」を始めた。極端に大きく張り出した肩、細く絞ったウエスト、レザーを多く使ったシルエットは、1980年代の「パワー・ショルダー」を代表するスタイルになり、ティエリー・ミュグレーとともに80年代のパリを象徴した。\n1990〜1992年にはランバンのオートクチュールを担当し、2度の金の指ぬき賞を受けた。その後は私生活の悲劇や経営の問題が続き、1990年代後半にブランドの経営権を失った。2024年2月に亡くなった。近年、80年代のパワー・ショルダーのアーカイブとして再評価が進んでいる。"
  },
  "sitbon": {
    "en": "Martine Sitbon",
    "ja": "マルティーヌ・シットボン",
    "aka": [
      "シットボン"
    ],
    "bio": "1951年、モロッコのカサブランカに生まれ、10歳でパリに移った。パリのファッション学校ステュディオ・ベルソーで学び、卒業後はアジアやアメリカを旅しながら、フリーランスのデザイナーとして働いた。\n1986年に自分のブランドを始め、1988年からは約4年半、クロエのデザインも担当した。ロック、70年代、ユニセックスのテーラード、くすんだ色、ベルベットなどを組み合わせた服は、1990年代のパリで、グランジやロックの空気を表すブランドとして高く評価された。音楽やアートの世界とのつながりも深かった。\n自分のブランドは2004年に終わり、2006年に新しいブランド「ルー・デュ・メイル」を始めた（2013年まで）。1990年代のシットボンの服は、アーカイブ市場で静かに人気がある。"
  },
  "willhelm": {
    "en": "Bernhard Willhelm",
    "ja": "ベルンハルト・ウィルヘルム",
    "aka": [
      "ベルンハルトウィルヘルム"
    ],
    "bio": "1972年、ドイツのウルムに生まれた。アントワープ王立芸術アカデミーで学び、在学中からヴィヴィアン・ウエストウッド、アレキサンダー・マックイーン、ウォルター・ヴァン・ベイレンドンク、ダーク・ビッケンバーグなどのもとで経験を積んだ。\n1998年に卒業し、1999年にユッタ・クラウスとアントワープで自分のブランドを始めた。ドイツの民族衣装、子どものおもちゃ、スポーツウェア、民芸品などをごちゃまぜにした、明るい色と遊び心あふれる服で、パリのコレクションで異彩を放った。2002〜2004年にはイタリアのカポビアンコのクリエイティブ・ディレクターも務めた。\n2013年にロサンゼルスへ拠点を移し、ショーの代わりに写真や本、展示で服を見せるようになった。カンペールとのシューズ、ビョークの衣装なども手がけた。",
    "mentors": [
      "westwood",
      "mcqueen",
      "wvb",
      "bikkembergs"
    ]
  },
  "shayneoliver": {
    "en": "Shayne Oliver",
    "ja": "シェイン・オリヴァー",
    "aka": [
      "シェインオリバー"
    ],
    "bio": "1988年、カリブ海のトリニダード・トバゴに生まれ、ニューヨークのブルックリンで育った。パーソンズ美術大学でファッションを学んだが、中退した。\n2006年、友人のラウル・ロペスとともに「フッド・バイ・エア（HBA）」を始めた。ニューヨークのクラブ・カルチャー、ヴォーギング、黒人やクィアのコミュニティの感覚を取り入れ、ロゴを大胆に使ったTシャツ、性別の境界のない服、レイヤードで、2010年代前半のストリートファッションに大きな影響を与えた。リアーナ、カニエ・ウェスト、エイサップ・ロッキーなどが着たことでも知られる。2014年に LVMH プライズの特別審査員賞、2015年に CFDA の賞を受けた。\n2017年にブランドを休止したあと、ヘルムート・ラングの限定コレクション、ディーゼルとの協業などを手がけ、2020年ごろにブランドの再始動を発表した。"
  },
  "kuroda": {
    "en": "Yuichi Kuroda",
    "ja": "黒田雄一",
    "aka": [
      "黒田"
    ],
    "bio": "日本のデザイナー。1995年に「ラッド・ミュージシャン（LAD MUSICIAN）」を始めた。ブランド名は「音楽好きの若者」を意味し、ロックやニューウェーブ、ポストパンクなど音楽とファッションを結びつけることをテーマにしている。\n細身のシルエット、ロック・ミュージシャンのようなテーラード、シャツ、モノトーンのスタイルが、2000年代の日本のモード系・ロック系のファッションの中で人気を集めた。花柄やスタッズ、ロングカーディガン、ビッグシルエットなど、時代に合わせて作風を変えながら、東京コレクションでの発表を続けた。2000年代の日本の「ロック・モード」を代表するデザイナーの一人で、近年はその時代のアイテムがアーカイブとして再評価されている。"
  },
  "umawang": {
    "en": "Uma Wang",
    "ja": "ウマ・ワン",
    "aka": [
      "ウマワン",
      "王汁"
    ],
    "bio": "中国の江蘇省の生まれ。上海の中国紡績大学（現・東華大学）で服飾を学び、中国の企業でニットウェアのデザイナーとして働いた。のちにロンドンのセントラル・セント・マーチンズで修士課程を修了した。\n2005年に自分のブランドを始め、2009年にロンドンで発表したのち、ミラノ、パリへ発表の場を移した。手触りのある天然素材、手作業で加工したような風合い、ゆったりとして体を包み込むシルエット、くすんだ色合いで、「アルチザン系」「静かなラグジュアリー」のブランドとして高く評価されている。中国出身のデザイナーとして、早くから国際的に活躍した一人。"
  },
  "dawson": {
    "en": "Elena Dawson",
    "ja": "エレナ・ドーソン",
    "aka": [
      "エレナドーソン"
    ],
    "bio": "ロンドン生まれ。アートや手仕事への関心から、自分で服を作るようになった。\n2000年、ポール・ハーンデンとともに、ポール・ハーンデン シューメーカーズの服のラインを始め、19世紀の作業着や農民の服をもとにした、手作業の服づくりに関わった。2006年に自分のブランドを始め、イングランド南部の小さな工房で、ほとんどすべてを手作業で作っている。\nアイリッシュ・リネン、ウール、コットンなどの天然素材を、縫い代を見せたり、手で染めたり、何度も洗ったりして、ヴィクトリア朝の服や古い作業着のような、着古したような風合いに仕上げる。生産数は非常に少なく、限られた店でしか買えないため、アルチザン系の中でも特に入手が難しいブランドとされる。",
    "mentors": [
      "harnden"
    ]
  },
  "gsmall": {
    "en": "Geoffrey B. Small",
    "ja": "ジェフリー・B・スモール",
    "aka": [
      "ジェフリービースモール",
      "GBS"
    ],
    "bio": "アメリカのボストンで育った。1979年、両親の家のロフトでシンガーのミシンを使って服を作り始めた。独学で服づくりを学び、1980年代にはボストンで自分のブランドを育て、のちのデザイナーたちに先駆けて、古着を作り直す「リサイクル（アップサイクル）」の服を作った。\n1993年からパリで発表を始め、パリで100以上のコレクションを発表した、最も多くパリで発表したアメリカ人デザイナーの一人とされる。1999〜2000年ごろにイタリア・ヴェネト州のカヴァルゼレに移り、地元の職人たちと、ほとんどすべてを手作業で作るブランドに作り直した。\n大量生産や使い捨てのファッションに強く反対し、環境や社会への考えを服づくりの中心に置いている。重いウール、手縫いのボタンホール、古いナポレオン時代の軍服をもとにしたコートなどが特徴。"
  },
  "laurini": {
    "en": "Luca Laurini",
    "ja": "ルカ・ラウリーニ",
    "aka": [
      "ラウリーニ"
    ],
    "bio": "イタリアのデザイナー。1990年代後半から2000年代にかけて、マウリツィオ・アルティエリのカルペ・ディエムの仕事に関わり、イタリアのアルチザン系の服づくりを学んだ。\nその後「ラベル・アンダー・コンストラクション（Label Under Construction）」を始め、主にニットウェアで知られるようになった。手作業の縫製、ほつれや縫い目をそのまま見せる仕上げ、柔らかいウールやカシミアを使ったニットは、アルチザン系のファンの間で定番になっている。",
    "mentors": [
      "altieri"
    ]
  },
  "sellam": {
    "en": "Isaac Sellam",
    "ja": "アイザック・セラム",
    "aka": [
      "アイザックセラム"
    ],
    "bio": "フランスのデザイナー。革職人として経験を積み、2002年にパリで「アイザック・セラム・エクスペリエンス」を始めた。\n上質なレザーやエキゾチックレザー（ワニ、トカゲなど）を、裏地をつけずに一枚で仕立てたジャケットやコート、ブーツで知られる。革を染めたり洗ったりして、使い込んだような柔らかい風合いにする手法は、アルチザン系の中でも独特で、レザージャケットのブランドとして根強い人気がある。"
  },
  "uchise": {
    "en": "Teruki Uchise",
    "ja": "内瀬輝樹",
    "aka": [
      "ウチセテルキ"
    ],
    "bio": "日本のデザイナー。メキシコでジュエリーづくりと革小物の技術を学び、インドネシアのバリ島に移り住んで、2000年に「KMRii（ケムリ）」を始めた。バッグや革小物、レザーアクセサリーを中心に、民族的なモチーフとロックな雰囲気を組み合わせた。\n2007年に「14th Addiction（フォーティーンス・アディクション）」を始め、ビジュアル系の音楽シーンとつながるスタイルで知られるようになった。その後6年ほどの休止期間を経て、2023年に14th Addiction を再始動し、レザーグッズ、靴、アウター、パンツを中心にしている。2000年代の日本のロック系・Y2K 系のファッションとして、海外でも再評価されている。"
  },
  "satoh": {
    "en": "Nobuhiko Satoh",
    "ja": "佐藤信彦",
    "aka": [],
    "bio": "日本のデザイナー。ミュージシャンとしても活動していた。1990年代後半に東京で「L.G.B.（ル・グラン・ブルー）」のデザインを始めた。\nロックやバイカーのイメージを、手作業で加工したデニム、レザー、ニットに落とし込んだ服で、1990年代後半から2000年代の原宿のロック・ファッションの中で人気を集めた。同じ会社のブランドに「イフ・シックス・ワズ・ナイン（ifsixwasnine）」がある。2000年代の日本のロック系ブランドは、近年海外で「Japanese archive」として人気が高く、L.G.B. もその代表の一つとされる。"
  }
};
